import { createRequire } from 'module';

const require = createRequire(import.meta.url);

export default {
  plugins: {
    tailwindcss: {},
    autoprefixer: {},
  },
};

import React, { useState, useRef, useEffect } from 'react';
import { Smile, Paperclip, Send, FileText, Image as ImageIcon, File, X } from 'lucide-react';
import { io } from 'socket.io-client';
import { useGetMessagesQuery, useSendMessageMutation } from '../../redux/features/messages/messagesApi';
import { useSelector } from 'react-redux';
import { SOCKET_BASE_URL } from '../../config/urls';

export default function MessageActiveChat({ chatId }) {
  const { user } = useSelector(state => state.auth || { user: { _id: "admin" } });
  const isNewChat = String(chatId).startsWith('new-');
  const queryId = isNewChat ? "skip" : String(chatId);
  const { data: messagesResponse, isLoading } = useGetMessagesQuery(queryId, { skip: !chatId || isNewChat });
  const [sendMessageApi, { isLoading: isSending }] = useSendMessageMutation();

  const [message, setMessage] = useState("");
  const [attachments, setAttachments] = useState([]);
  const [socketMessages, setSocketMessages] = useState([]);
  const socketRef = useRef(null);

  const rawMessages = messagesResponse?.data || [];
  
  // Connect to socket when chat opens
  useEffect(() => {
    socketRef.current = io(SOCKET_BASE_URL);
    socketRef.current.emit('join_room', chatId);

    socketRef.current.on('receive_message', (newMsg) => {
      setSocketMessages(prev => [...prev, newMsg]);
    });

    return () => {
      socketRef.current.disconnect();
    };
  }, [chatId]);

  // Combine database messages and real-time socket messages
  const chatHistory = [...rawMessages, ...socketMessages].map((msg, index) => {
    // Check if it's already formatted from mock data (graceful fallback)
    if (msg.type) return msg;

    const isIncoming = msg.sender?.role === 'buyer' || (msg.sender?._id && user?._id && msg.sender._id !== user._id) || (msg.sender?.id && user?.id && msg.sender.id !== user.id) || (msg.sender !== 'me' && typeof msg.sender === 'string');
    const msgTime = new Date(msg.createdAt).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });

    let msgAttachments = [];
    if (msg.isFile) {
      msgAttachments.push({
        id: msg._id,
        name: msg.fileName,
        size: 'Unknown',
        ext: msg.fileName?.split('.').pop()?.toUpperCase() || 'FILE',
        type: msg.fileUrl?.match(/\.(jpeg|jpg|gif|png)$/) ? 'image' : 'doc',
        url: msg.fileUrl
      });
    }

    const senderInitials = msg.sender?.name ? `${msg.sender.name.charAt(0).toUpperCase()}` : (msg.sender?.role === 'buyer' ? 'B' : 'U');

    return {
      id: msg._id || index,
      type: isIncoming ? 'incoming' : 'outgoing',
      text: msg.text,
      time: msgTime,
      attachments: msgAttachments,
      avatarInitials: senderInitials,
    };
  });
  
  const chatEndRef = useRef(null);
  const fileInputRef = useRef(null);
  const [showEmojiPicker, setShowEmojiPicker] = useState(false);
  
  const commonEmojis = ['😀', '😂', '🥰', '😎', '👍', '🙏', '🔥', '✨', '🎉', '💡', '✅', '👀'];

  useEffect(() => {
    setTimeout(() => {
      chatEndRef.current?.scrollIntoView({ behavior: 'smooth', block: 'end' });
    }, 50);
  }, [chatHistory]);

  const handleSendMessage = async () => {
    if (!message.trim() && attachments.length === 0) return;

    try {
      // If there are attachments, normally we'd upload to S3 first. For now, we simulate.
      const isFile = attachments.length > 0;
      const fileName = isFile ? attachments[0].name : null;
      const fileUrl = isFile ? attachments[0].url : null;

      const payload = {
        text: message,
        isFile,
        fileName,
        fileUrl,
        ...(isNewChat ? { recipientId: String(chatId).split('-')[1] } : {})
      };

      const res = await sendMessageApi({ conversationId: isNewChat ? "new" : chatId, data: payload }).unwrap();
      const savedMsg = res.data;

      // Broadcast to socket
      socketRef.current.emit('send_message', { roomId: savedMsg.conversation || chatId, message: savedMsg });

      // Add to local real-time state instantly
      setSocketMessages(prev => [...prev, savedMsg]);
      
      setMessage("");
      setAttachments([]);
    } catch (err) {
      console.error("Failed to send message", err);
    }
  };

  const removeAttachment = (id) => {
    setAttachments(attachments.filter(a => a.id !== id));
  };

  const handleFileAttach = (e) => {
    if (e.target.files && e.target.files[0]) {
      const file = e.target.files[0];
      const ext = file.name.split('.').pop().toLowerCase();
      let type = 'doc';
      if (['jpg', 'jpeg', 'png', 'gif', 'webp'].includes(ext)) type = 'image';
      else if (ext === 'pdf') type = 'pdf';
      
      const newAttachment = {
        id: Date.now(),
        name: file.name,
        size: (file.size / 1024 / 1024).toFixed(2) + ' MB',
        ext: ext.toUpperCase(),
        type: type,
        url: type === 'image' ? URL.createObjectURL(file) : null
      };
      
      setAttachments([...attachments, newAttachment]);
    }
  };

  const handleEmojiClick = (emoji) => {
    setMessage(prev => prev + emoji);
    setShowEmojiPicker(false);
  };

  return (
    <div className="flex flex-col h-full bg-white rounded-xl shadow-sm border border-gray-200 overflow-hidden min-h-0">

      {/* Chat Messages Area */}
      <div className="flex-1 overflow-y-auto p-6 bg-[#F8F9FB] flex flex-col gap-6 min-h-0">

        {chatHistory.map((msg, index) => {
          return (
            <React.Fragment key={msg.id}>
              {/* Date Divider (Only shown if specified) */}
              {msg.showDate && (
                <div className="flex justify-center">
                  <span className="px-4 py-1.5 bg-gray-200 text-gray-500 rounded-full text-[11px] font-bold">
                    {msg.showDate}
                  </span>
                </div>
              )}

              {/* Message Bubble */}
              {msg.type === 'incoming' ? (
                <div className="flex items-start gap-3 max-w-[85%]">
                  {msg.avatar ? (
                    <img
                      src={msg.avatar}
                      alt="Buyer"
                      className="w-8 h-8 rounded-full object-cover shrink-0"
                    />
                  ) : (
                    <div className="w-8 h-8 rounded-full bg-blue-100 flex items-center justify-center shrink-0">
                      <span className="text-blue-700 font-bold text-[11px]">{msg.avatarInitials}</span>
                    </div>
                  )}
                  <div>
                    <div className="bg-white border border-gray-100 p-4 rounded-2xl rounded-tl-sm shadow-sm">
                      <p className="text-[13px] text-gray-600 leading-relaxed font-medium">
                        {msg.text}
                      </p>
                    </div>
                    <span className="text-[10px] text-gray-400 font-bold mt-1 ml-1">{msg.time}</span>
                  </div>
                </div>
              ) : (
                <div className="flex flex-col items-end w-full">
                  <div className="flex items-start justify-end gap-3 w-full">
                    <div className="flex flex-col items-end max-w-[85%]">
                      {msg.attachments && msg.attachments.length > 0 && (
                        <div className="flex flex-wrap gap-2 mb-2 justify-end">
                          {msg.attachments.map(att => (
                            att.type === 'image' ? (
                              <img key={att.id} src={att.url} alt={att.name} className="max-w-[240px] rounded-2xl border border-gray-200 shadow-sm" />
                            ) : (
                              <div key={att.id} className="bg-white border border-gray-200 p-3 rounded-xl flex items-center gap-3 shadow-sm min-w-[200px]">
                                <div className={`w-8 h-8 flex items-center justify-center rounded-lg ${att.type === 'pdf' ? 'bg-red-50 text-red-500' : 'bg-blue-50 text-blue-500'}`}>
                                  {att.type === 'pdf' ? <FileText size={16} /> : <File size={16} />}
                                </div>
                                <div className="text-left min-w-0">
                                  <p className="text-[12px] font-bold text-[#0F172A] truncate">{att.name}</p>
                                  <p className="text-[10px] text-gray-500">{att.size}</p>
                                </div>
                              </div>
                            )
                          ))}
                        </div>
                      )}
                      
                      {msg.text && (
                        <div className="bg-[#5B6270] text-white p-4 rounded-2xl rounded-tr-sm shadow-sm inline-block">
                          <p className="text-[13px] leading-relaxed font-medium">
                            {msg.text}
                          </p>
                        </div>
                      )}
                    </div>
                  </div>
                  <span className="text-[10px] text-gray-400 font-bold mt-1 mr-1">{msg.time}</span>
                </div>
              )}
            </React.Fragment>
          );
        })}
        <div ref={chatEndRef} />
      </div>

      {/* Input Area */}
      <div className="p-6 border-t border-gray-200 bg-white">

        {/* Attachments Preview */}
        {attachments.length > 0 && (
          <div className="flex flex-wrap gap-4 mb-4">
            {attachments.map(file => (
              <div key={file.id} className="flex items-center gap-3 p-3 border border-gray-200 rounded-xl hover:border-gray-300 transition cursor-pointer w-[240px] relative group">
                <button
                  onClick={() => removeAttachment(file.id)}
                  className="absolute -top-2 -right-2 w-5 h-5 bg-white border border-gray-200 rounded-full flex items-center justify-center text-gray-500 hover:text-red-500 shadow-sm opacity-0 group-hover:opacity-100 transition"
                >
                  <X size={12} />
                </button>
                <div className={`w-10 h-10 rounded-lg flex items-center justify-center shrink-0 overflow-hidden ${
                  file.type === 'pdf' ? 'bg-red-50 text-red-500' : 
                  file.type === 'doc' ? 'bg-blue-50 text-blue-500' : ''
                }`}>
                  {file.type === 'image' ? (
                    <img src={file.url || "https://images.unsplash.com/photo-1518770660439-4636190af475?w=100&h=100&fit=crop"} alt="Preview" className="w-full h-full object-cover" />
                  ) : file.type === 'pdf' ? (
                    <FileText size={20} />
                  ) : (
                    <File size={20} />
                  )}
                </div>
                <div className="min-w-0">
                  <h4 className="text-[13px] font-bold text-[#0F172A] truncate">{file.name}</h4>
                  <p className="text-[11px] font-bold text-gray-500">{file.size} · {file.ext}</p>
                </div>
              </div>
            ))}
          </div>
        )}

        {/* Text Input */}
        <div className="bg-[#F8F9FB] rounded-xl border border-gray-100 focus-within:border-gray-300 transition shrink-0 relative z-10">
          <textarea
            value={message}
            onChange={(e) => setMessage(e.target.value)}
            onKeyDown={(e) => {
              if (e.key === 'Enter' && !e.shiftKey) {
                e.preventDefault();
                handleSendMessage();
              }
            }}
            placeholder="Type your message here... (Press Enter to send)"
            className="w-full h-20 p-4 bg-transparent resize-none outline-none text-[13px] font-medium placeholder:text-gray-400"
          ></textarea>

          <div className="px-4 pb-3 flex justify-between items-center text-gray-400">
            <div className="flex items-center gap-4 relative">
              <button 
                onClick={() => setShowEmojiPicker(!showEmojiPicker)}
                className="hover:text-gray-700 transition"
              >
                <Smile size={18} strokeWidth={2.5} />
              </button>
              
              {showEmojiPicker && (
                <div className="absolute bottom-8 left-0 bg-white border border-gray-200 shadow-lg rounded-xl p-3 grid grid-cols-4 gap-2 z-10 w-[160px]">
                  {commonEmojis.map(emoji => (
                    <button 
                      key={emoji}
                      onClick={() => handleEmojiClick(emoji)}
                      className="hover:bg-gray-100 rounded text-lg p-1 transition flex items-center justify-center"
                    >
                      {emoji}
                    </button>
                  ))}
                </div>
              )}

              <input 
                type="file" 
                ref={fileInputRef}
                onChange={handleFileAttach}
                className="hidden"
              />
              <button 
                onClick={() => fileInputRef.current?.click()}
                className="hover:text-gray-700 transition"
              >
                <Paperclip size={18} strokeWidth={2.5} />
              </button>
            </div>
            <span className="text-[10px] font-bold tracking-wider">{message.length} characters</span>
          </div>
        </div>

        {/* Actions */}
        <div className="flex justify-end gap-3 mt-4">
          <button className="px-6 py-2.5 bg-white border border-gray-200 hover:bg-gray-50 transition rounded-full text-[13px] font-bold text-[#0F172A]">
            Save Draft
          </button>
          <button
            onClick={handleSendMessage}
            disabled={!message.trim() && attachments.length === 0}
            className="px-6 py-2.5 bg-[#0F172A] hover:bg-black disabled:opacity-50 transition rounded-full text-[13px] font-bold text-white shadow-sm flex items-center gap-2"
          >
            Send Message
            <Send size={14} strokeWidth={2.5} className="ml-1" />
          </button>
        </div>

      </div>
    </div>
  );
}

import React from 'react';
import { Filter } from 'lucide-react';

export default function MessageSidebar({ conversations = [], isLoading, activeTab, selectedChat, setSelectedChat }) {
  const allChats = conversations.map((conv, idx) => {
    // Determine the other participant
    const otherUser = conv.participants?.find(p => p.role !== 'admin' && p.role !== 'supplier') || conv.participants?.[0] || {};

    // Create random background colors for avatars based on id
    const bgColors = ["bg-blue-100 text-blue-700", "bg-gray-200 text-gray-700", "bg-orange-100 text-orange-800", "bg-yellow-100 text-yellow-700"];
    const avatarBg = bgColors[idx % bgColors.length];

    const tags = [];
    if (conv.rfq) tags.push({ label: `RFQ #${conv.rfq.rfqNumber || '...'}`, color: "bg-orange-100 text-orange-700" });
    if (conv.status === 'closed') tags.push({ label: "Closed", color: "bg-gray-100 text-gray-500" });
    else tags.push({ label: "Open", color: "bg-blue-50 text-blue-600" });

    return {
      id: conv._id,
      buyerInitials: otherUser.name ? otherUser.name.charAt(0).toUpperCase() : "U",
      buyerName: otherUser.name || "Unknown User",
      avatarBg,
      time: new Date(conv.lastMessageAt || Date.now()).toLocaleDateString(),
      tags,
      preview: conv.lastMessage?.text || "Started a new conversation...",
    };
  });

  // For dynamic filtering (mocking)
  const filteredChats = activeTab === 'Unread'
    ? allChats.filter(c => c.tags.some(t => t.label === 'Unread'))
    : activeTab === 'RFQ'
      ? allChats.filter(c => c.tags.some(t => t.label === 'RFQ'))
      : allChats;

  return (
    <div className="bg-white rounded-xl shadow-sm border border-gray-200 h-full flex flex-col overflow-hidden">
      {/* Header */}
      <div className="p-4 border-b border-gray-100 flex items-center justify-between bg-[#F8F9FB]">
        <span className="text-[11px] font-bold text-gray-500 tracking-wider">RECENT CHATS</span>
        <button className="text-gray-400 hover:text-gray-700 transition">
          <Filter size={18} />
        </button>
      </div>

      {/* Chat List */}
      <div className="flex-1 overflow-y-auto no-scrollbar">
        {filteredChats.map(chat => {
          const isSelected = selectedChat === chat.id || (!selectedChat && chat.isActive);

          return (
            <div
              key={chat.id}
              onClick={() => setSelectedChat(chat.id)}
              className={`p-4 border-b border-gray-50 cursor-pointer transition relative ${isSelected ? 'bg-[#F8F9FB]' : 'hover:bg-gray-50 bg-white'
                }`}
            >
              {isSelected && (
                <div className="absolute left-0 top-0 bottom-0 w-1 bg-[#D4AF37]"></div>
              )}

              <div className="flex gap-3">
                {/* Avatar */}
                <div className={`w-10 h-10 rounded-md shrink-0 flex items-center justify-center text-[13px] font-bold ${chat.isLogo ? 'bg-[#0F172A]' : chat.avatarBg
                  }`}>
                  {chat.isLogo ? (
                    <div className="w-4 h-4 bg-[#D4AF37] rotate-45 flex items-center justify-center">
                      <div className="w-2 h-2 bg-[#0F172A]"></div>
                    </div>
                  ) : chat.buyerInitials}
                </div>

                {/* Content */}
                <div className="flex-1 min-w-0">
                  <div className="flex justify-between items-start mb-1">
                    <h3 className="text-[13px] font-bold text-[#0F172A] truncate pr-2">{chat.buyerName}</h3>
                    <span className="text-[10px] font-bold text-gray-400 whitespace-nowrap pt-0.5">{chat.time}</span>
                  </div>

                  <div className="flex flex-wrap gap-1.5 mb-2">
                    {chat.tags.map((tag, idx) => (
                      <span key={idx} className={`px-1.5 py-0.5 rounded text-[10px] font-bold ${tag.color}`}>
                        {tag.label}
                      </span>
                    ))}
                  </div>

                  <p className={`text-[12px] text-gray-500 leading-snug line-clamp-2 ${chat.isItalic ? 'italic' : 'font-medium'}`}>
                    {chat.preview}
                  </p>
                </div>
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
}

import React, { useState, useRef } from 'react';
import { useParams, Link } from 'react-router-dom';
import { ChevronRight, Printer, X, FileText, Image as ImageIcon, File, Paperclip, Send, MapPin, CheckCircle, Clock, Star } from 'lucide-react';
import { useSelector } from 'react-redux';
import { useGetRfqQuery, useGetRfqMessagesQuery, useReplyToRfqMutation, useUpdateRfqStatusMutation } from '../../redux/features/rfqs/rfqsApi';
import { useCreateReviewMutation } from '../../redux/features/reviews/reviewsApi';

export default function RFQDetails() {
  const { id } = useParams();
  const [message, setMessage] = useState('');
  const [attachedFile, setAttachedFile] = useState(null);
  const fileInputRef = useRef(null);

  const { data: rfqResponse, isLoading: isRfqLoading } = useGetRfqQuery(id);
  const { data: messagesResponse } = useGetRfqMessagesQuery(id);
  const [replyToRfq, { isLoading: isReplying }] = useReplyToRfqMutation();
  const [updateStatus] = useUpdateRfqStatusMutation();
  const [createReview, { isLoading: isReviewing }] = useCreateReviewMutation();
  
  const { user } = useSelector((state) => state.auth);
  
  const [reviewRating, setReviewRating] = useState(5);
  const [reviewText, setReviewText] = useState('');

  const rawRfq = rfqResponse?.data;
  const messages = messagesResponse?.data || [];

  const rfq = rawRfq ? {
    id: `RFQ-${rawRfq._id.substring(rawRfq._id.length - 4).toUpperCase()}`,
    rawId: rawRfq._id,
    status: rawRfq.status === 'pending' ? 'NEW' : rawRfq.status === 'responded' ? 'RESPONDED' : rawRfq.status === 'closed' ? 'CLOSED' : rawRfq.status.toUpperCase(),
    category: rawRfq.subject || "Not specified", 
    quantity: `${rawRfq.quantity}`,
    deadline: "N/A", 
    location: "N/A",
    notes: rawRfq.details || '',
    attachments: rawRfq.attachments?.map(url => ({ name: url.split('/').pop(), url, type: 'file' })) || [],
    buyer: {
      name: rawRfq.buyerUser?.name || rawRfq.buyerName,
      title: "Buyer",
      company: "Company", 
      location: "Location",
      isVerified: !!rawRfq.buyerUser
    },
    activity: [
      { date: new Date(rawRfq.createdAt).toLocaleString([], { dateStyle: 'medium', timeStyle: 'short' }), title: "RFQ Created", desc: "Request submitted by buyer" },
      ...messages.map(msg => {
        const isSupplier = msg.sender?._id === rawRfq.supplier || msg.sender?._id === rawRfq.supplier?._id || msg.sender?.role === 'supplier';
        return {
          date: new Date(msg.createdAt).toLocaleString([], { dateStyle: 'medium', timeStyle: 'short' }),
          title: isSupplier ? "Proposal Sent" : "Message Received",
          desc: msg.text
        };
      })
    ]
  } : null;

  const handleReplySubmit = async () => {
    if ((message.trim() || attachedFile) && rfq) {
      try {
        // We'll skip S3 file upload logic for now since this is just a quick reply
        // In a real scenario, you'd upload attachedFile to S3 and get the URL
        await replyToRfq({
          id: rfq.rawId,
          data: {
            text: message,
            attachments: [] // Add S3 URLs here if implemented
          }
        }).unwrap();
        
        if (rfq.status !== 'RESPONDED') {
          await updateStatus({ id: rfq.rawId, status: 'responded' }).unwrap();
        }
        
        setMessage('');
        setAttachedFile(null);
        alert("Reply sent successfully!");
      } catch (error) {
        alert("Failed to send reply");
      }
    }
  };

  const handleFileAttach = (e) => {
    if (e.target.files && e.target.files[0]) {
      setAttachedFile(e.target.files[0]);
    }
  };

  const handleComplete = async () => {
    if (rfq) {
      if (window.confirm("Are you sure you want to mark this RFQ as completed?")) {
        try {
          await updateStatus({ id: rfq.rawId, status: 'resolved' }).unwrap();
          alert("RFQ marked as completed.");
        } catch (error) {
          alert("Failed to complete RFQ");
        }
      }
    }
  };

  const handleSubmitReview = async () => {
    if (!reviewText.trim()) {
      alert("Please enter a review comment.");
      return;
    }
    try {
      await createReview({
        supplierId: rawRfq.supplier._id || rawRfq.supplier,
        rfqId: rfq.rawId,
        rating: reviewRating,
        comment: reviewText
      }).unwrap();
      alert("Review submitted successfully!");
      setReviewText('');
    } catch (err) {
      alert(err.data?.message || "Failed to submit review");
    }
  };

  const handleDecline = async () => {
    if (rfq) {
      if (window.confirm("Are you sure you want to decline this RFQ?")) {
        try {
          await updateStatus({ id: rfq.rawId, status: 'closed' }).unwrap();
          alert("RFQ declined.");
        } catch (error) {
          alert("Failed to decline RFQ");
        }
      }
    }
  };

  const handlePrint = () => {
    window.print();
  };

  const renderAttachmentIcon = (type) => {
    switch (type) {
      case 'pdf': return <div className="w-8 h-8 rounded bg-red-50 text-red-500 flex items-center justify-center shrink-0"><FileText size={16} /></div>;
      case 'image': return <div className="w-8 h-8 rounded bg-blue-50 text-blue-500 flex items-center justify-center shrink-0"><ImageIcon size={16} /></div>;
      case 'doc': return <div className="w-8 h-8 rounded bg-gray-100 text-gray-500 flex items-center justify-center shrink-0"><File size={16} /></div>;
      default: return <div className="w-8 h-8 rounded bg-gray-100 text-gray-500 flex items-center justify-center shrink-0"><File size={16} /></div>;
    }
  };

  if (!rfq) return null;

  return (
    <div className="min-h-screen p-6 lg:p-8 bg-[#F8F9FB] text-[#0F172A] font-sans mt-16">
      {/* Breadcrumb & Header */}
      <div className="mb-6">
        <div className="flex items-center gap-2 text-[13px] font-bold text-gray-500 mb-4">
          <Link to="/rfqs" className="hover:text-gray-900 transition">RFQs</Link>
          <ChevronRight size={14} />
          <span className="text-[#0F172A]">{rfq.id}</span>
        </div>
        
        <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
          <div className="flex items-center gap-4">
            <h1 className="text-[32px] font-bold tracking-tight text-[#0F172A]">{rfq.id}</h1>
            <span className={`px-3 py-1 text-white rounded-full text-[11px] font-bold tracking-wider uppercase flex items-center gap-1.5 ${
              rfq.status === 'NEW' ? 'bg-[#0066FF]' : 
              rfq.status === 'RESPONDED' ? 'bg-[#D4AF37] text-[#0F172A]' : 
              rfq.status === 'DECLINED' ? 'bg-[#DC2626]' : 'bg-gray-500'
            }`}>
              <div className={`w-1.5 h-1.5 rounded-full ${rfq.status === 'RESPONDED' ? 'bg-[#0F172A]' : 'bg-white'}`}></div>
              {rfq.status}
            </span>
          </div>
          
          <div className="flex items-center gap-3">
            <button onClick={handlePrint} className="px-4 py-2 bg-white border border-gray-300 rounded-md text-[13px] font-bold text-[#0F172A] shadow-sm hover:bg-gray-50 transition flex items-center gap-2">
              <Printer size={16} strokeWidth={2.5} />
              Print
            </button>
            {user?.role === 'buyer' && rfq.status !== 'RESOLVED' && rfq.status !== 'CLOSED' && rfq.status !== 'DECLINED' && (
              <button 
                onClick={handleComplete} 
                className="px-4 py-2 bg-[#D1FAE5] hover:bg-[#A7F3D0] text-[#065F46] transition rounded-md text-[13px] font-bold shadow-sm flex items-center gap-2"
              >
                <CheckCircle size={16} strokeWidth={2.5} />
                Complete
              </button>
            )}
            <button 
              onClick={handleDecline} 
              disabled={rfq.status === 'DECLINED'}
              className="px-4 py-2 bg-[#FEE2E2] hover:bg-[#FECACA] disabled:opacity-50 text-[#DC2626] transition rounded-md text-[13px] font-bold shadow-sm flex items-center gap-2"
            >
              <X size={16} strokeWidth={2.5} />
              Decline
            </button>
          </div>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        {/* Left Column (Main Content) */}
        <div className="lg:col-span-2 space-y-6">
          
          {/* Request Information */}
          <div className="bg-white rounded-xl shadow-sm border border-gray-200 p-6">
            <h2 className="flex items-center gap-2 text-[18px] font-bold text-[#0F172A] mb-6">
              <FileText size={20} className="text-gray-700" strokeWidth={2} />
              Request Information
            </h2>
            
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6 mb-8">
              <div>
                <p className="text-[11px] font-bold text-gray-500 tracking-wider mb-1">PRODUCT CATEGORY</p>
                <p className="text-[14px] text-gray-800 font-medium">{rfq.category}</p>
              </div>
              <div>
                <p className="text-[11px] font-bold text-gray-500 tracking-wider mb-1">QUANTITY REQUESTED</p>
                <p className="text-[14px] text-gray-800 font-medium">{rfq.quantity}</p>
              </div>
              <div>
                <p className="text-[11px] font-bold text-gray-500 tracking-wider mb-1">TARGET DEADLINE</p>
                <p className="text-[14px] text-gray-800 font-medium flex items-center gap-1.5">
                  <span className="text-red-500"><Clock size={14} /></span>
                  {rfq.deadline}
                </p>
              </div>
              <div>
                <p className="text-[11px] font-bold text-gray-500 tracking-wider mb-1">DELIVERY LOCATION</p>
                <p className="text-[14px] text-gray-800 font-medium">{rfq.location}</p>
              </div>
            </div>
            
            <div>
              <p className="text-[11px] font-bold text-gray-500 tracking-wider mb-2">BUYER NOTES</p>
              <div className="bg-[#F8F9FB] border border-gray-100 rounded-lg p-5 whitespace-pre-wrap">
                <p className="text-[13px] text-gray-700 leading-relaxed font-medium">{rfq.notes}</p>
              </div>
            </div>
          </div>

          {/* Attachments */}
          {rfq.attachments && rfq.attachments.length > 0 && (
            <div className="bg-white rounded-xl shadow-sm border border-gray-200 p-6">
              <h2 className="flex items-center gap-2 text-[18px] font-bold text-[#0F172A] mb-6">
                <Paperclip size={20} className="text-gray-700" strokeWidth={2} />
                Attachments
              </h2>
              
              <div className="space-y-3">
                {rfq.attachments.map((file, idx) => (
                  <a key={idx} href={file.url} target="_blank" rel="noreferrer" className="flex items-center gap-3 p-3 border border-gray-100 rounded-lg hover:bg-gray-50 transition cursor-pointer">
                    {renderAttachmentIcon(file.type)}
                    <div>
                      <h4 className="text-[13px] font-bold text-[#0F172A] mb-0.5">{file.name}</h4>
                      <p className="text-[11px] font-bold text-gray-500">Attachment</p>
                    </div>
                  </a>
                ))}
              </div>
            </div>
          )}

          {/* Reply to Request */}
          {rfq.status === 'RESOLVED' && user?.role === 'buyer' ? (
            <div className="bg-white rounded-xl shadow-sm border border-gray-200 p-6">
              <h2 className="text-[20px] font-bold text-[#0F172A] mb-4">Leave a Review</h2>
              <div className="border border-gray-200 rounded-lg overflow-hidden bg-[#F8F9FB] p-4">
                <div className="flex gap-2 mb-4">
                  {[1, 2, 3, 4, 5].map(star => (
                    <button key={star} onClick={() => setReviewRating(star)}>
                      <Star size={24} className={star <= reviewRating ? 'fill-yellow-400 text-yellow-400' : 'text-gray-300'} />
                    </button>
                  ))}
                </div>
                <textarea 
                  value={reviewText}
                  onChange={(e) => setReviewText(e.target.value)}
                  className="w-full h-24 p-3 bg-white border border-gray-200 rounded-lg resize-none outline-none text-[13px] font-medium placeholder:text-gray-400 mb-4"
                  placeholder="Share your experience working with this supplier..."
                ></textarea>
                <div className="flex justify-end">
                  <button 
                    onClick={handleSubmitReview}
                    disabled={isReviewing}
                    className="px-5 py-2.5 bg-[#D4AF37] hover:bg-[#C29F31] disabled:bg-[#e4ce84] transition rounded-md text-[13px] font-bold text-[#0F172A] shadow-sm flex items-center gap-2"
                  >
                    <Star size={16} strokeWidth={2.5} />
                    Submit Review
                  </button>
                </div>
              </div>
            </div>
          ) : (
            <div className="bg-white rounded-xl shadow-sm border border-gray-200 p-6">
              <h2 className="text-[20px] font-bold text-[#0F172A] mb-4">Reply to Request</h2>
              
              <div className="border border-gray-200 rounded-lg overflow-hidden bg-[#F8F9FB]">
                <textarea 
                  value={message}
                  onChange={(e) => setMessage(e.target.value)}
                  className="w-full h-32 p-4 bg-transparent resize-none outline-none text-[13px] font-medium placeholder:text-gray-400"
                  placeholder="Type your response or quote details here..."
                ></textarea>
                
                {attachedFile && (
                  <div className="px-4 pb-3 flex items-center gap-2">
                    <div className="flex items-center gap-2 bg-blue-50 border border-blue-100 text-blue-700 px-3 py-1.5 rounded-md text-[12px] font-bold">
                      <FileText size={14} />
                      <span className="truncate max-w-[200px]">{attachedFile.name}</span>
                      <button 
                        onClick={() => setAttachedFile(null)}
                        className="ml-1 hover:text-blue-900 transition"
                      >
                        <X size={14} />
                      </button>
                    </div>
                  </div>
                )}
                
                <div className="bg-white border-t border-gray-200 p-3 flex justify-between items-center">
                  <input 
                    type="file" 
                    className="hidden" 
                    ref={fileInputRef} 
                    onChange={handleFileAttach}
                  />
                  <button 
                    onClick={() => fileInputRef.current?.click()}
                    className="flex items-center gap-2 text-[13px] font-bold text-gray-600 hover:text-gray-900 transition px-2"
                  >
                    <Paperclip size={16} />
                    Attach Quote
                  </button>
                  <button 
                    onClick={handleReplySubmit}
                    disabled={!message.trim() && !attachedFile}
                    className="px-5 py-2.5 bg-[#D4AF37] hover:bg-[#C29F31] disabled:bg-[#e4ce84] transition rounded-md text-[13px] font-bold text-[#0F172A] shadow-sm flex items-center gap-2"
                  >
                    <Send size={16} strokeWidth={2.5} />
                    Send Proposal
                  </button>
                </div>
              </div>
            </div>
          )}

        </div>

        {/* Right Column (Sidebar Content) */}
        <div className="space-y-6">
          
          {/* Buyer Profile */}
          <div className="bg-white rounded-xl shadow-sm border border-gray-200 p-6">
            <h2 className="flex items-center gap-2 text-[18px] font-bold text-[#0F172A] mb-6">
              <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="text-gray-700"><path d="M20 21v-2a4 4 0 0 0-4-4H8a4 4 0 0 0-4 4v2"></path><circle cx="12" cy="7" r="4"></circle></svg>
              Buyer Profile
            </h2>
            
            <div className="flex items-center gap-4 mb-6 pb-6 border-b border-gray-100">
              <div className="w-14 h-14 bg-gray-200 rounded-lg overflow-hidden shrink-0">
                <img src="https://images.unsplash.com/photo-1560250097-0b93528c311a?w=150&h=150&fit=crop" alt="Buyer" className="w-full h-full object-cover" />
              </div>
              <div>
                <h3 className="text-[14px] font-bold text-[#0F172A] mb-0.5">{rfq.buyer.name}</h3>
                <p className="text-[12px] font-bold text-gray-500">{rfq.buyer.title}</p>
              </div>
            </div>

            <div className="space-y-5">
              <div className="flex items-start gap-3">
                <div className="mt-0.5 text-gray-400">
                  <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><rect x="4" y="4" width="16" height="16" rx="2" ry="2"></rect><rect x="9" y="9" width="6" height="6"></rect><line x1="9" y1="1" x2="9" y2="4"></line><line x1="15" y1="1" x2="15" y2="4"></line><line x1="9" y1="20" x2="9" y2="23"></line><line x1="15" y1="20" x2="15" y2="23"></line><line x1="20" y1="9" x2="23" y2="9"></line><line x1="20" y1="14" x2="23" y2="14"></line><line x1="1" y1="9" x2="4" y2="9"></line><line x1="1" y1="14" x2="4" y2="14"></line></svg>
                </div>
                <div>
                  <p className="text-[10px] font-bold text-gray-500 tracking-wider mb-0.5">COMPANY</p>
                  <p className="text-[13px] font-medium text-[#0F172A]">{rfq.buyer.company}</p>
                </div>
              </div>

              <div className="flex items-start gap-3">
                <div className="mt-0.5 text-gray-400">
                  <MapPin size={16} strokeWidth={2} />
                </div>
                <div>
                  <p className="text-[10px] font-bold text-gray-500 tracking-wider mb-0.5">LOCATION</p>
                  <p className="text-[13px] font-medium text-[#0F172A]">{rfq.buyer.location}</p>
                </div>
              </div>

              <div className="flex items-start gap-3">
                <div className="mt-0.5 text-gray-400">
                  <CheckCircle size={16} strokeWidth={2} />
                </div>
                <div>
                  <p className="text-[10px] font-bold text-gray-500 tracking-wider mb-0.5">STATUS</p>
                  <p className="text-[13px] font-bold text-[#0066FF]">{rfq.buyer.isVerified ? "Verified Buyer" : "Unverified Buyer"}</p>
                </div>
              </div>
            </div>
          </div>

          {/* Activity */}
          <div className="bg-white rounded-xl shadow-sm border border-gray-200 p-6">
            <h2 className="flex items-center gap-2 text-[18px] font-bold text-[#0F172A] mb-6 pb-6 border-b border-gray-100">
              <Clock size={20} className="text-gray-700" strokeWidth={2} />
              Activity
            </h2>
            
            <div className="relative border-l-2 border-gray-100 ml-2 pl-4 py-1">
              <div className="absolute -left-[5px] top-1.5 w-2 h-2 rounded-full bg-[#0066FF] ring-4 ring-white"></div>
              {rfq.activity.map((act, idx) => (
                <div key={idx}>
                  <p className="text-[11px] font-bold text-gray-500 mb-1">{act.date}</p>
                  <h4 className="text-[13px] font-bold text-[#0F172A] mb-1">{act.title}</h4>
                  <p className="text-[12px] text-gray-500 font-medium whitespace-pre-wrap">{act.desc}</p>
                </div>
              ))}
            </div>
          </div>

        </div>
      </div>
      
      {/* Footer */}
      <div className="flex flex-col md:flex-row justify-between items-center text-[11px] font-bold text-gray-500 pt-6 mt-12 pb-4 border-t border-gray-200">
        <p>© 2024 WULFARA Industrial Marketplace. All rights reserved.</p>
        <div className="flex gap-6 mt-4 md:mt-0 text-gray-500">
          <a href="#" className="hover:text-gray-900 transition">Support</a>
          <a href="#" className="hover:text-gray-900 transition">Privacy Policy</a>
          <a href="#" className="hover:text-gray-900 transition">Terms of Service</a>
        </div>
      </div>
    </div>
  );
}

import React, { useState, useRef, useMemo } from 'react';
import { useParams, Link, useNavigate } from 'react-router-dom';
import { ChevronRight, FileText, Clock, CloudUpload, Send, CheckCircle2, Circle, X } from 'lucide-react';
import { useGetRfqQuery, useReplyToRfqMutation, useUpdateRfqStatusMutation } from '../../redux/features/rfqs/rfqsApi';

export default function RFQReply() {
  const { id } = useParams();
  const navigate = useNavigate();
  const fileInputRef = useRef(null);
  
  const { data: rfqResponse, isLoading } = useGetRfqQuery(id);
  const [replyToRfq] = useReplyToRfqMutation();
  const [updateStatus] = useUpdateRfqStatusMutation();
  
  const rawRfq = rfqResponse?.data;
  
  const [formData, setFormData] = useState({
    price: '',
    isNegotiable: false,
    timeline: '',
    shippingNotes: '',
    message: ''
  });
  
  const [attachedFile, setAttachedFile] = useState(null);

  const rfq = rawRfq ? {
    id: `RFQ-${rawRfq._id.substring(rawRfq._id.length - 4).toUpperCase()}`,
    rawId: rawRfq._id,
    product: rawRfq.subject || rawRfq.productDetails || 'Unknown',
    quantity: `${rawRfq.quantity}`,
    targetDate: 'N/A', // Assuming targetDate isn't directly on RFQ yet
    buyerName: rawRfq.buyerUser?.name || rawRfq.buyerName || 'Unknown Buyer'
  } : null;

  if (isLoading || !rfq) {
    return <div className="p-8 mt-16 text-center text-gray-500 font-bold">Loading RFQ details...</div>;
  }

  const handleInputChange = (e) => {
    const { name, value, type, checked } = e.target;
    setFormData(prev => ({
      ...prev,
      [name]: type === 'checkbox' ? checked : value
    }));
  };

  const handleFileChange = (e) => {
    if (e.target.files && e.target.files[0]) {
      setAttachedFile(e.target.files[0]);
    }
  };

  const handleSendReply = async () => {
    if (!formData.price.trim() || !formData.timeline.trim() || !formData.message.trim()) {
      alert("Please fill in all required fields (Price, Timeline, and Message).");
      return;
    }
    
    if (rfq) {
      try {
        const textMessage = `[QUOTE DETAILS]
Price: $${formData.price} ${formData.isNegotiable ? '(Negotiable)' : '(Fixed)'}
Timeline: ${formData.timeline}
Shipping Notes: ${formData.shippingNotes || 'None'}

[MESSAGE]
${formData.message}`;

        await replyToRfq({
          id: rfq.rawId,
          data: {
            text: textMessage,
            attachments: [] // Skip attachments for now, or implement S3 upload
          }
        }).unwrap();
        
        await updateStatus({ id: rfq.rawId, status: 'responded' }).unwrap();
        
        alert(`Quote Response sent successfully for ${rfq.id}!`);
        navigate(`/rfqs/${rfq.rawId}`);
      } catch (error) {
        alert("Failed to send quote response");
      }
    }
  };

  const handleSaveDraft = () => {
    alert(`Draft saved for ${rfq.id}.`);
    navigate(`/rfqs`);
  };

  return (
    <div className="min-h-screen p-6 lg:p-8 bg-[#F8F9FB] text-[#0F172A] font-sans mt-16">
      {/* Breadcrumb */}
      <div className="mb-6">
        <div className="flex items-center gap-2 text-[13px] font-bold text-gray-500 mb-4">
          <Link to="/rfqs" className="hover:text-gray-900 transition">RFQs</Link>
          <ChevronRight size={14} />
          <Link to={`/rfqs/${rfq.id}`} className="hover:text-gray-900 transition">{rfq.id}</Link>
          <ChevronRight size={14} />
          <span className="text-[#0F172A]">Reply</span>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        {/* Left Column (Form) */}
        <div className="lg:col-span-2">
          <div className="bg-white rounded-xl shadow-sm border border-gray-200 overflow-hidden">
            
            {/* Header */}
            <div className="p-6 border-b border-gray-100 flex items-center gap-3">
              <FileText className="text-emerald-600" size={24} />
              <h1 className="text-[24px] font-bold text-[#0F172A]">Quote Response</h1>
            </div>

            {/* Form Content */}
            <div className="p-6 space-y-6">
              
              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <div>
                  <label className="block text-[13px] font-bold text-[#0F172A] mb-2">
                    <span className="text-red-500">*</span>
                  </label>
                  <div className="relative">
                    <div className="absolute inset-y-0 left-0 pl-4 flex items-center pointer-events-none">
                      <span className="text-gray-500 font-medium text-[15px]">$</span>
                    </div>
                    <input 
                      type="text" 
                      name="price"
                      value={formData.price}
                      onChange={handleInputChange}
                      placeholder="0.00"
                      className="w-full pl-8 pr-4 py-3 bg-[#F8F9FB] border border-gray-200 rounded-lg text-[14px] font-medium focus:outline-none focus:border-blue-500 transition"
                    />
                  </div>
                  <div className="mt-3 flex items-center gap-2">
                    <input 
                      type="checkbox" 
                      id="isNegotiable"
                      name="isNegotiable"
                      checked={formData.isNegotiable}
                      onChange={handleInputChange}
                      className="w-4 h-4 rounded border-gray-300 text-blue-600 focus:ring-blue-500 cursor-pointer"
                    />
                    <label htmlFor="isNegotiable" className="text-[12px] font-bold text-gray-600 cursor-pointer">
                      Price is negotiable
                    </label>
                  </div>
                </div>

                <div>
                  <label className="block text-[13px] font-bold text-[#0F172A] mb-2">
                    Delivery Timeline <span className="text-red-500">*</span>
                  </label>
                  <div className="relative">
                    <div className="absolute inset-y-0 left-0 pl-4 flex items-center pointer-events-none">
                      <Clock className="text-gray-400" size={16} />
                    </div>
                    <input 
                      type="text" 
                      name="timeline"
                      value={formData.timeline}
                      onChange={handleInputChange}
                      placeholder="e.g., 10-15 business days"
                      className="w-full pl-11 pr-4 py-3 bg-[#F8F9FB] border border-gray-200 rounded-lg text-[14px] font-medium focus:outline-none focus:border-blue-500 transition"
                    />
                  </div>
                </div>
              </div>

              <div>
                <label className="block text-[13px] font-bold text-[#0F172A] mb-2">
                  Shipping Notes <span className="text-gray-400 font-medium">(Optional)</span>
                </label>
                <textarea 
                  name="shippingNotes"
                  value={formData.shippingNotes}
                  onChange={handleInputChange}
                  placeholder="FOB, CIF, or any specific logistics constraints..."
                  className="w-full h-24 p-4 bg-[#F8F9FB] border border-gray-200 rounded-lg text-[14px] font-medium resize-none focus:outline-none focus:border-blue-500 transition"
                ></textarea>
              </div>

              <div>
                <label className="block text-[13px] font-bold text-[#0F172A] mb-2">
                  Message to Buyer <span className="text-red-500">*</span>
                </label>
                <textarea 
                  name="message"
                  value={formData.message}
                  onChange={handleInputChange}
                  placeholder="Detail your offering, terms, and any variations from the original request..."
                  className="w-full h-32 p-4 bg-[#F8F9FB] border border-gray-200 rounded-lg text-[14px] font-medium resize-none focus:outline-none focus:border-blue-500 transition"
                ></textarea>
              </div>

              <div>
                <label className="block text-[13px] font-bold text-[#0F172A] mb-2">
                  Attach Quote Document
                </label>
                <input 
                  type="file" 
                  ref={fileInputRef}
                  onChange={handleFileChange}
                  className="hidden"
                />
                
                {!attachedFile ? (
                  <div 
                    onClick={() => fileInputRef.current?.click()}
                    className="border-2 border-dashed border-gray-200 rounded-xl p-8 flex flex-col items-center justify-center bg-[#F8F9FB] hover:bg-gray-50 transition cursor-pointer"
                  >
                    <CloudUpload className="text-gray-400 mb-3" size={32} />
                    <p className="text-[14px] font-bold text-[#0F172A] mb-1">Drag and drop your file here</p>
                    <p className="text-[12px] font-bold text-gray-500 mb-4">Supported formats: PDF, DOCX (Max 10MB)</p>
                    <button className="px-6 py-2 bg-white border border-gray-200 rounded-md text-[13px] font-bold text-[#0F172A] hover:bg-gray-50 transition pointer-events-none">
                      Browse Files
                    </button>
                  </div>
                ) : (
                  <div className="border border-blue-100 bg-blue-50 rounded-xl p-6 flex items-center justify-between">
                    <div className="flex items-center gap-3">
                      <div className="w-10 h-10 bg-white rounded-lg flex items-center justify-center shadow-sm">
                        <FileText className="text-blue-600" size={20} />
                      </div>
                      <div>
                        <p className="text-[14px] font-bold text-[#0F172A]">{attachedFile.name}</p>
                        <p className="text-[11px] font-bold text-gray-500">{(attachedFile.size / 1024 / 1024).toFixed(2)} MB</p>
                      </div>
                    </div>
                    <button 
                      onClick={() => setAttachedFile(null)}
                      className="p-2 text-gray-400 hover:text-red-500 hover:bg-white rounded-lg transition"
                    >
                      <X size={20} />
                    </button>
                  </div>
                )}
              </div>

            </div>

            {/* Action Buttons */}
            <div className="p-6 border-t border-gray-100 bg-[#F8F9FB] flex justify-end gap-3">
              <button 
                onClick={handleSaveDraft}
                className="px-6 py-2.5 bg-white border border-gray-200 hover:bg-gray-50 transition rounded-md text-[13px] font-bold text-[#0F172A]"
              >
                Save Draft
              </button>
              <button 
                onClick={handleSendReply}
                className="px-6 py-2.5 bg-[#D4AF37] hover:bg-[#C29F31] transition rounded-md text-[13px] font-bold text-[#0F172A] shadow-sm flex items-center gap-2"
              >
                <Send size={16} strokeWidth={2.5} />
                Send Reply
              </button>
            </div>
          </div>
        </div>

        {/* Right Column (Sidebar) */}
        <div className="space-y-6">
          
          {/* RFQ Summary Card */}
          <div className="bg-white rounded-xl shadow-sm border border-gray-200 overflow-hidden">
            <div className="bg-[#1E293B] p-4 flex items-center gap-2 text-white">
              <FileText size={18} />
              <h2 className="text-[14px] font-bold">RFQ Summary</h2>
            </div>
            
            <div className="p-5">
              <div className="space-y-4">
                <div className="flex justify-between items-center py-2 border-b border-gray-50">
