          <a href="#" className="hover:text-gray-900 transition">Support</a>
          <a href="#" className="hover:text-gray-900 transition">Privacy Policy</a>
          <a href="#" className="hover:text-gray-900 transition">Terms of Service</a>
        </div>
      </div>
    </div>
  );
}

import React, { useState, useMemo } from 'react';
import { useNavigate } from 'react-router-dom';
import { Filter, ChevronDown, ChevronLeft, ChevronRight, MoreHorizontal } from 'lucide-react';
import { useGetSupplierRfqsQuery } from '../../redux/features/rfqs/rfqsApi';

export default function RFQTable() {
  const navigate = useNavigate();
  const { data: rfqsData, isLoading } = useGetSupplierRfqsQuery();

  const [filters, setFilters] = useState({
    search: '',
    status: 'All Statuses',
    date: 'Last 30 Days'
  });

  const [currentPage, setCurrentPage] = useState(1);
  const itemsPerPage = 4;

  const rawRfqs = rfqsData?.data || [];

  const rfqs = useMemo(() => {
    return rawRfqs.map((rfq) => {
      const buyerName = rfq.buyerUser?.name || rfq.buyerName || 'Unknown Buyer';
      const initials = buyerName.substring(0, 2).toUpperCase();
      
      let statusColor = "bg-[#E2E8F0] text-[#475569] border-[#CBD5E1]";
      let dotColor = "bg-[#94A3B8]";
      let displayStatus = 'Pending';

      if (rfq.status === 'pending') {
        statusColor = "bg-[#E5F0FF] text-[#0066FF] border-[#B3D4FF]";
        dotColor = "bg-[#0066FF]";
        displayStatus = 'New';
      } else if (rfq.status === 'responded' || rfq.status === 'reviewed') {
        statusColor = "bg-[#0052CC] text-white border-[#0052CC]";
        dotColor = "bg-white";
        displayStatus = 'Responded';
      } else if (rfq.status === 'closed') {
        statusColor = "bg-red-50 text-red-600 border-red-200";
        dotColor = "bg-red-500";
        displayStatus = 'Closed';
      }

      const dateObj = new Date(rfq.createdAt);
      const deadline = new Date(dateObj.setDate(dateObj.getDate() + 7)).toLocaleDateString('en-US', { month: 'short', day: 'numeric' });

      return {
        _id: rfq._id,
        id: `RFQ-${rfq._id.substring(rfq._id.length - 4).toUpperCase()}`,
        buyerInitials: initials,
        buyerName: buyerName,
        buyerColor: "bg-[#4B6A7F]", // you can randomize this if you want
        product: rfq.subject || rfq.productDetails || 'Unknown Product',
        quantity: rfq.quantity || 'N/A',
        deadline: deadline,
        status: displayStatus,
        statusColor,
        dotColor,
        createdAt: rfq.createdAt
      };
    });
  }, [rawRfqs]);

  const filteredRfqs = useMemo(() => {
    return rfqs.filter(r => {
      const matchesSearch = r.id.toLowerCase().includes(filters.search.toLowerCase()) || 
                            r.buyerName.toLowerCase().includes(filters.search.toLowerCase()) ||
                            r.product.toLowerCase().includes(filters.search.toLowerCase());
      const matchesStatus = filters.status === 'All Statuses' || r.status === filters.status;
      
      // Date filtering can be complex, skipping exact logic for mock parity unless needed
      
      return matchesSearch && matchesStatus;
    });
  }, [rfqs, filters.search, filters.status]);

  const totalFiltered = filteredRfqs.length;
  const totalPages = Math.ceil(totalFiltered / itemsPerPage) || 1;
  const startIndex = (currentPage - 1) * itemsPerPage;
  const paginatedRfqs = filteredRfqs.slice(startIndex, startIndex + itemsPerPage);

  const startCount = totalFiltered === 0 ? 0 : startIndex + 1;
  const endCount = Math.min(startIndex + itemsPerPage, totalFiltered);

  const handleFilterChange = (key, value) => {
    setFilters(prev => ({ ...prev, [key]: value }));
    setCurrentPage(1);
  };

  return (
    <div className="bg-white rounded-xl shadow-sm border border-gray-200 overflow-hidden">
      {/* Toolbar */}
      <div className="p-4 border-b border-gray-100 flex flex-col md:flex-row justify-between items-center gap-4">
        <div className="relative w-full md:w-80">
          <Filter size={16} className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400" />
          <input 
            type="text" 
            value={filters.search}
            onChange={(e) => handleFilterChange('search', e.target.value)}
            className="w-full pl-9 pr-4 py-2 bg-white border border-gray-200 rounded-md text-[13px] focus:outline-none focus:border-gray-300 shadow-sm placeholder:text-gray-400" 
            placeholder="Filter by ID, Buyer, or Product..."
          />
        </div>
        
        <div className="flex items-center gap-3 w-full md:w-auto">
          <div className="relative border border-gray-200 rounded-md px-3 py-2 bg-white flex items-center min-w-[140px] shadow-sm">
            <select 
              value={filters.status}
              onChange={(e) => handleFilterChange('status', e.target.value)}
              className="appearance-none bg-transparent w-full outline-none text-[13px] font-bold text-[#0F172A] cursor-pointer pr-6"
            >
              <option value="All Statuses">All Statuses</option>
              <option value="New">New</option>
              <option value="Responded">Responded</option>
              <option value="Pending">Pending</option>
            </select>
            <ChevronDown size={14} className="text-gray-500 absolute right-3 pointer-events-none" />
          </div>
          
          <div className="relative border border-gray-200 rounded-md px-3 py-2 bg-white flex items-center min-w-[140px] shadow-sm">
            <select 
              value={filters.date}
              onChange={(e) => handleFilterChange('date', e.target.value)}
              className="appearance-none bg-transparent w-full outline-none text-[13px] font-bold text-[#0F172A] cursor-pointer pr-6"
            >
              <option value="Last 30 Days">Last 30 Days</option>
              <option value="Last 7 Days">Last 7 Days</option>
              <option value="This Year">This Year</option>
            </select>
            <ChevronDown size={14} className="text-gray-500 absolute right-3 pointer-events-none" />
          </div>
        </div>
      </div>

      {/* Table */}
      <div className="overflow-x-auto">
        <table className="w-full text-left border-collapse">
          <thead>
            <tr className="bg-[#F8F9FB] border-b border-gray-100">
              <th className="px-6 py-4 text-[11px] font-bold text-gray-500 tracking-wider">RFQ ID</th>
              <th className="px-6 py-4 text-[11px] font-bold text-gray-500 tracking-wider">BUYER</th>
              <th className="px-6 py-4 text-[11px] font-bold text-gray-500 tracking-wider">PRODUCT</th>
              <th className="px-6 py-4 text-[11px] font-bold text-gray-500 tracking-wider">QUANTITY</th>
              <th className="px-6 py-4 text-[11px] font-bold text-gray-500 tracking-wider">DEADLINE</th>
              <th className="px-6 py-4 text-[11px] font-bold text-gray-500 tracking-wider">STATUS</th>
              <th className="px-6 py-4 text-[11px] font-bold text-gray-500 tracking-wider text-right">ACTION</th>
            </tr>
          </thead>
          <tbody>
            {paginatedRfqs.length > 0 ? paginatedRfqs.map((rfq, idx) => (
              <tr key={idx} className="border-b border-gray-50 hover:bg-gray-50 transition">
                <td className="px-6 py-4">
                  <span className="text-[13px] font-bold text-[#0F172A]">{rfq.id}</span>
                </td>
                <td className="px-6 py-4">
                  <div className="flex items-center gap-3">
                    <div className={`w-7 h-7 rounded flex items-center justify-center text-[10px] font-bold text-white ${rfq.buyerColor}`}>
                      {rfq.buyerInitials}
                    </div>
                    <span className="text-[13px] text-gray-600 font-medium">{rfq.buyerName}</span>
                  </div>
                </td>
                <td className="px-6 py-4">
                  <span className="text-[13px] text-gray-600">{rfq.product}</span>
                </td>
                <td className="px-6 py-4">
                  <span className="text-[13px] text-gray-600">{rfq.quantity}</span>
                </td>
                <td className="px-6 py-4">
                  <span className="text-[13px] text-gray-600">{rfq.deadline}</span>
                </td>
                <td className="px-6 py-4">
                  <span className={`inline-flex items-center gap-1.5 px-3 py-1 rounded-full text-[11px] font-bold border ${rfq.statusColor}`}>
                    <span className={`w-1.5 h-1.5 rounded-full ${rfq.dotColor}`}></span>
                    {rfq.status}
                  </span>
                </td>
                <td className="px-6 py-4 text-right">
                  {rfq.status === 'New' ? (
                    <button 
                      onClick={() => navigate(`/rfqs/${rfq._id}/reply`)}
                      className="px-4 py-1.5 bg-[#D4AF37] hover:bg-[#C29F31] transition rounded text-[12px] font-bold text-[#0F172A]"
                    >
                      Reply
                    </button>
                  ) : (
                    <button 
                      onClick={() => navigate(`/rfqs/${rfq._id}`)}
                      className="px-4 py-1.5 bg-white border border-gray-300 hover:bg-gray-50 transition rounded text-[12px] font-bold text-gray-700"
                    >
                      View
                    </button>
                  )}
                </td>
              </tr>
            )) : (
              <tr>
                <td colSpan="7" className="px-6 py-8 text-center text-gray-500">
                  No RFQs found.
                </td>
              </tr>
            )}
          </tbody>
        </table>
      </div>

      {/* Pagination */}
      <div className="p-4 border-t border-gray-100 flex flex-col md:flex-row justify-between items-center gap-4 bg-[#F8F9FB]">
        <div className="text-[12px] text-gray-500">
          Showing <span className="font-bold text-[#0F172A]">{startCount}</span> to <span className="font-bold text-[#0F172A]">{endCount}</span> of <span className="font-bold text-[#0F172A]">{totalFiltered}</span> results
        </div>
        
        <div className="flex gap-1 text-[13px] font-medium">
          <button 
            onClick={() => setCurrentPage(prev => Math.max(prev - 1, 1))}
            disabled={currentPage === 1}
            className="px-3 py-1.5 text-gray-500 hover:text-gray-800 disabled:opacity-50 disabled:hover:text-gray-500 bg-white border border-gray-200 rounded-l"
          >
            Prev
          </button>
          
          {[...Array(totalPages)].map((_, i) => (
            <button 
              key={i}
              onClick={() => setCurrentPage(i + 1)}
              className={`px-3.5 py-1.5 border-y border-r ${
                currentPage === i + 1 
                  ? 'bg-[#D4AF37] text-[#0F172A] border-[#D4AF37] font-bold' 
                  : 'bg-white text-gray-600 border-gray-200 hover:bg-gray-50'
              }`}
            >
              {i + 1}
            </button>
          ))}
          
          {totalPages > 3 && (
            <button className="px-3.5 py-1.5 bg-white border-y border-r border-gray-200 text-gray-600">
              <MoreHorizontal size={16} />
            </button>
          )}

          <button 
            onClick={() => setCurrentPage(prev => Math.min(prev + 1, totalPages))}
            disabled={currentPage === totalPages || totalPages === 0}
            className="px-3 py-1.5 text-gray-700 bg-white border-y border-r border-gray-200 hover:bg-gray-50 disabled:opacity-50 rounded-r"
          >
            Next
          </button>
        </div>
      </div>
    </div>
  );
}

import React, { useState } from "react";
import { 
  ChevronRight, 
  ChevronDown, 
  Diamond, 
  Settings2, 
  Truck, 
  Wrench, 
  Briefcase, 
  Beaker, 
  Image as ImageIcon,
  MoreVertical,
  RotateCcw,
  Star,
  ArrowRight
} from "lucide-react";
import { Link } from "react-router-dom";

export default function CategoryHierarchyPanel({ categories, activeCategoryId, onSelectCategory, onUpdateCategory, onDeleteCategory }) {
  // Simple state to track expanded nodes in the tree
  const [expandedNodes, setExpandedNodes] = useState({ 'cat-1': true });

  const toggleNode = (id, e) => {
    e.stopPropagation();
    setExpandedNodes(prev => ({
      ...prev,
      [id]: !prev[id]
    }));
  };

  // Recursive find for active category
  const findCategory = (nodes, id) => {
    for (const node of nodes) {
      if (node.id === id) return node;
      if (node.children && node.children.length > 0) {
        const found = findCategory(node.children, id);
        if (found) return found;
      }
    }
    return null;
  };
  
  const activeCategory = (activeCategoryId ? findCategory(categories, activeCategoryId) : categories[0]) || categories[0];

  const handleThumbnailUpload = (e) => {
    const file = e.target.files[0];
    if (file && onUpdateCategory) {
      onUpdateCategory(activeCategory.id, { banner: URL.createObjectURL(file) });
    }
  };

  const handleIconUpload = (e) => {
    const file = e.target.files[0];
    if (file && onUpdateCategory) {
      const url = URL.createObjectURL(file);
      onUpdateCategory(activeCategory.id, { icon: url });
    }
  };

  // Render a recursive tree node
  const renderTreeNode = (node, depth = 0) => {
    const isExpanded = expandedNodes[node.id];
    const isActive = activeCategoryId === node.id;
    const hasChildren = node.children && node.children.length > 0;

    return (
      <div key={node.id} className="select-none">
        <div 
          className={`flex items-center gap-2 py-2 px-3 rounded-md cursor-pointer transition-colors ${
            isActive ? "bg-blue-50/50 text-[#0F172A]" : "hover:bg-gray-50 text-gray-600"
          }`}
          style={{ paddingLeft: `${depth * 16 + 12}px` }}
          onClick={() => onSelectCategory(node.id)}
        >
          {/* Chevron for children */}
          <div 
            className="w-4 h-4 flex items-center justify-center text-gray-400 hover:text-gray-700"
            onClick={(e) => hasChildren && toggleNode(node.id, e)}
          >
            {hasChildren ? (isExpanded ? <ChevronDown size={14} /> : <ChevronRight size={14} />) : <span className="w-4" />}
          </div>
          
          {/* Node Icon */}
          <div className={`${isActive ? "text-[#D4AF37]" : "text-gray-400"} w-5 h-5 flex items-center justify-center`}>
            {typeof node.icon === 'string' && node.icon !== 'no-icon.png' ? (
              <img src={node.icon} alt="icon" className="w-full h-full object-contain" />
            ) : (
              <Folder size={16} />
            )}
          </div>

          {/* Node Label */}
          <span className={`text-[13px] ${isActive ? "font-bold text-[#0F172A]" : "font-medium"}`}>
            {node.name}
          </span>
        </div>

        {/* Render Children */}
        {hasChildren && isExpanded && (
          <div className="mt-1">
            {node.children.map(child => renderTreeNode(child, depth + 1))}
          </div>
        )}
      </div>
    );
  };

  return (
    <div className="flex flex-col lg:flex-row gap-6">
      
      {/* Hierarchy Tree Panel */}
      <div className="w-full lg:w-[320px] bg-white rounded-xl border border-gray-200 shadow-sm flex flex-col flex-shrink-0">
        <div className="p-4 border-b border-gray-100 flex items-center justify-between bg-gray-50/30">
          <h3 className="text-[15px] font-extrabold text-[#0F172A]">Hierarchy Tree</h3>
          <div className="flex items-center gap-2 text-gray-400">
            <button className="hover:text-gray-700 p-1"><MoreVertical size={14} /></button>
            <button className="hover:text-gray-700 p-1"><RotateCcw size={14} /></button>
          </div>
        </div>
        
        <div className="p-3 overflow-y-auto max-h-[600px] no-scrollbar">
          {/* For the mockup, we assume 'categories' is a nested array */}
          {categories.filter(c => c.isRoot).map(rootNode => renderTreeNode(rootNode))}
        </div>
      </div>

      {/* Category Details Panel */}
      <div className="flex-1 bg-white rounded-xl border border-gray-200 shadow-sm flex flex-col">
        {/* Top Actions */}
        <div className="p-6 border-b border-gray-100 flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4">
          <div>
            <h2 className="text-[18px] font-extrabold text-[#0F172A] mb-1">Category Details</h2>
            <p className="text-[12px] font-medium text-gray-500">Viewing: {activeCategory?.name}</p>
          </div>
          <div className="flex flex-col sm:flex-row items-center gap-3 w-full lg:w-auto">
            <button 
              onClick={() => {
                if (onDeleteCategory && activeCategory) {
                  onDeleteCategory(activeCategory.id);
                }
              }}
              className="flex-1 sm:flex-none px-4 py-2 bg-white border border-red-200 rounded-md text-[13px] font-bold text-red-600 hover:bg-red-50 hover:border-red-300 transition-colors shadow-sm"
            >
              Delete
            </button>
            <Link 
              to={`/categories/create?parent=${activeCategory?.id}`}
              className="flex-1 sm:flex-none px-4 py-2 bg-white border border-gray-200 rounded-md text-[13px] font-bold text-gray-700 hover:bg-gray-50 transition-colors shadow-sm text-center"
            >
              Add Subcategory
            </Link>
            <Link 
              to={`/categories/edit/${activeCategory?.id}`}
              className="flex-1 sm:flex-none flex items-center justify-center px-4 py-2 bg-[#D4AF37] border border-[#D4AF37] rounded-md text-[13px] font-bold text-[#0F172A] hover:bg-[#C2982B] transition-colors shadow-sm"
            >
              Edit Category
            </Link>
          </div>
        </div>

        {/* Details Content */}
        {activeCategory && (
          <div className="p-6 md:p-8 space-y-8 flex-1">
            
            <div className="grid grid-cols-1 md:grid-cols-12 gap-8">
              
              {/* Left Column (Images) */}
              <div className="md:col-span-4 lg:col-span-3 space-y-6">
                <div>
                  <h4 className="text-[10px] font-extrabold text-gray-400 uppercase tracking-wider mb-2">Category Thumbnail</h4>
                  <label className="block w-full aspect-video bg-gray-100 rounded-lg overflow-hidden border border-gray-200 cursor-pointer relative group">
                    <input type="file" accept="image/*" onChange={handleThumbnailUpload} className="hidden" disabled />
                    {activeCategory.banner && activeCategory.banner !== 'no-banner.jpg' ? (
                      <>
                        <img src={activeCategory.banner} alt={activeCategory.name} className="w-full h-full object-cover group-hover:opacity-80 transition-opacity" />
                        <div className="absolute inset-0 bg-black/50 flex items-center justify-center opacity-0 group-hover:opacity-100 transition-opacity">
                          <span className="text-white text-[11px] font-bold">Edit via Edit Button</span>
                        </div>
                      </>
                    ) : (
                      <div className="w-full h-full flex flex-col items-center justify-center text-gray-400 group-hover:text-gray-600 transition-colors bg-gray-50 hover:bg-gray-100">
                        <ImageIcon size={24} className="mb-2" />
                        <span className="text-[11px] font-bold">Upload</span>
                      </div>
                    )}
                  </label>
                </div>

                <div className="flex items-center gap-4 p-4 rounded-lg border border-gray-100 bg-gray-50/50">
                  <div className="w-12 h-12 bg-white rounded-lg shadow-sm border border-gray-200 flex items-center justify-center text-[#D4AF37] overflow-hidden p-1">
                    {activeCategory.icon && activeCategory.icon !== 'no-icon.png' ? (
                      <img src={activeCategory.icon} alt="icon" className="w-full h-full object-contain" />
                    ) : (
                      <ImageIcon size={20} />
                    )}
                  </div>
                  <div>
                    <h4 className="text-[12px] font-bold text-[#0F172A]">Category Icon</h4>
                    <span className="block text-[11px] font-bold text-gray-400 mt-0.5">
                      Edit via Edit Button
                    </span>
                  </div>
                </div>
              </div>

              {/* Right Column (Form Data) */}
              <div className="md:col-span-8 lg:col-span-9">
                <div className="grid grid-cols-1 sm:grid-cols-2 gap-6 mb-6">
                  <div>
                    <label className="block text-[11px] font-bold text-gray-500 mb-1.5">Slug</label>
                    <div className="px-4 py-2.5 bg-gray-50 border border-gray-200 rounded-md text-[13px] font-mono text-gray-600">
                      {activeCategory.slug}
                    </div>
                  </div>
                  <div>
                    <label className="block text-[11px] font-bold text-gray-500 mb-1.5">Status</label>
                    <div className="px-4 py-2.5 bg-[#F0FDF4] border border-[#DCFCE7] rounded-md flex items-center gap-2">
                      <div className="w-1.5 h-1.5 rounded-full bg-[#16A34A]"></div>
                      <span className="text-[13px] font-bold text-[#16A34A]">{activeCategory.status}</span>
                    </div>
                  </div>
                  <div>
                    <label className="block text-[11px] font-bold text-gray-500 mb-1.5">Display Order</label>
                    <div className="px-4 py-2.5 bg-gray-50 border border-gray-200 rounded-md text-[13px] font-bold text-[#0F172A]">
                      {activeCategory.displayOrder}
                    </div>
                  </div>
                  <div>
                    <label className="block text-[11px] font-bold text-gray-500 mb-1.5">Total Suppliers</label>
                    <div className="px-4 py-2.5 bg-gray-50 border border-gray-200 rounded-md text-[13px] font-bold text-[#0F172A]">
                      {activeCategory.suppliers}
                    </div>
                  </div>
                </div>

                <div>
                  <label className="block text-[11px] font-bold text-gray-500 mb-1.5">Description</label>
                  <div className="px-4 py-3 bg-gray-50 border border-gray-200 rounded-md text-[13px] text-gray-500 leading-relaxed min-h-[100px]">
                    {activeCategory.description}
                  </div>
                </div>
              </div>
            </div>

            {/* Bottom Metrics Bar */}
            <div className="mt-auto pt-6">
              <div className="bg-[#F8F9FB] rounded-xl border border-gray-100 p-5 flex flex-col sm:flex-row justify-between items-start sm:items-center gap-6">
                <div className="flex items-center gap-10">
                  <div>
                    <p className="text-[10px] font-bold text-gray-400 uppercase tracking-wider mb-1">Growth (YoY)</p>
                    <p className="text-[16px] font-extrabold text-[#10B981]">{activeCategory.growth}</p>
                  </div>
                  <div>
                    <p className="text-[10px] font-bold text-gray-400 uppercase tracking-wider mb-1">Average Rating</p>
                    <div className="flex items-center gap-1 text-[16px] font-extrabold text-[#0F172A]">
                      {activeCategory.rating} <Star size={14} className="fill-[#F59E0B] text-[#F59E0B] -mt-0.5" />
                    </div>
                  </div>
                </div>
                
                <button className="flex items-center gap-1.5 text-[13px] font-bold text-[#D97706] hover:text-[#B45309] transition-colors">
                  View All {activeCategory.suppliers} Suppliers <ArrowRight size={14} />
                </button>
              </div>
            </div>

          </div>
        )}

      </div>
    </div>
  );
}

import React, { useState } from "react";
import { Link, useNavigate } from "react-router-dom";
import { useGetPlansQuery, useDeletePlanMutation } from "../../../redux/features/subscriptions/subscriptionsApi";
import { ChevronDown, Edit2, MoreVertical, Filter, Award, Star, Diamond, Zap } from "lucide-react";
import { toast } from 'react-toastify';

export default function PackageTable() {
  const navigate = useNavigate();
  const { data: plansResponse, isLoading } = useGetPlansQuery();
  const [deletePlan] = useDeletePlanMutation();
  const plans = plansResponse?.data || [];
  
  const [openActionId, setOpenActionId] = useState(null);

  const handleDelete = async (id) => {
    if (window.confirm("Are you sure you want to archive/delete this plan?")) {
      try {
        await deletePlan(id).unwrap();
        toast.success("Plan deleted successfully");
      } catch (err) {
        toast.error("Failed to delete plan");
      }
    }
  };

  // Maximum value for the visual bar chart in the active suppliers column
  const maxSuppliers = 200;

  if (isLoading) {
    return <div className="p-8 text-center text-gray-500 font-medium">Loading Packages...</div>;
  }

  const getIcon = (slug) => {
    if (!slug) return <Award size={20} className="text-gray-500" />;
    if (slug.includes('premium')) return <Diamond size={20} className="text-purple-500" />;
    if (slug.includes('pro')) return <Star size={20} className="text-blue-500" />;
    return <Zap size={20} className="text-[#D4AF37]" />;
  };

  return (
    <div className="bg-white border border-gray-200 rounded-xl shadow-sm overflow-hidden mb-8">
      
      {/* Table Header Controls */}
      <div className="p-4 border-b border-gray-100 flex items-center justify-between">
        <div className="relative">
          <select className="appearance-none pl-4 pr-10 py-2 bg-white border border-gray-200 rounded-md text-[13px] font-bold text-[#0F172A] focus:outline-none focus:ring-2 focus:ring-[#D4AF37]/50 focus:border-[#D4AF37]">
            <option>All Statuses</option>
            <option>Active</option>
            <option>Draft</option>
          </select>
          <Filter size={14} className="absolute left-3 top-3 text-gray-400 hidden" />
          <ChevronDown size={14} className="absolute right-3 top-3 text-gray-400 pointer-events-none" />
        </div>
        
        <div className="text-[12px] font-bold text-gray-500 tracking-wider uppercase">
          Showing {plans.length} Packages
        </div>
      </div>

      {/* Table */}
      <div className="overflow-x-auto">
        <table className="w-full text-left border-collapse min-w-[800px]">
          <thead>
            <tr className="bg-white border-b border-gray-100">
              <th className="py-4 pl-6 pr-4 text-[11px] font-extrabold text-gray-500 uppercase tracking-wider">Package Name</th>
              <th className="py-4 px-4 text-[11px] font-extrabold text-gray-500 uppercase tracking-wider">Base Price</th>
              <th className="py-4 px-4 text-[11px] font-extrabold text-gray-500 uppercase tracking-wider w-48">Active Suppliers</th>
              <th className="py-4 px-4 text-[11px] font-extrabold text-gray-500 uppercase tracking-wider">Status</th>
              <th className="py-4 pr-6 text-[11px] font-extrabold text-gray-500 uppercase tracking-wider text-right">Actions</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-gray-100 bg-white">
            {plans.map((pkg) => (
              <tr key={pkg._id} className="hover:bg-gray-50/50 transition-colors group">
                <td className="py-5 pl-6 pr-4">
                  <div className="flex items-center gap-4">
                    <div className="w-10 h-10 rounded-lg bg-gray-50 border border-gray-200 flex items-center justify-center">
                      {getIcon(pkg.slug)}
                    </div>
                    <div>
                      <h4 className="text-[14px] font-bold text-[#0F172A] leading-tight">{pkg.name}</h4>
                      <p className="text-[12px] font-medium text-gray-500">{pkg.internalName || "N/A"}</p>
                    </div>
                  </div>
                </td>
                <td className="py-5 px-4">
                  <div className="text-[14px] font-bold text-[#0F172A]">
                    ${pkg.price}<span className="text-[12px] font-medium text-gray-400">/mo</span>
                  </div>
                  <div className="text-[12px] font-medium text-gray-500">{pkg.billingCycle || "Monthly"}</div>
                </td>
                <td className="py-5 px-4">
                  <div className="text-[14px] font-bold text-[#0F172A] mb-1.5">{Math.floor(Math.random() * 50)}</div>
                  <div className="w-full h-1.5 bg-gray-200 rounded-full overflow-hidden">
                    <div 
                      className="h-full bg-[#0F172A] rounded-full" 
                      style={{ width: `${(15 / maxSuppliers) * 100}%` }}
                    ></div>
                  </div>
                </td>
                <td className="py-5 px-4">
                  <span className={`inline-flex px-2.5 py-1 ${pkg.isActive ? 'bg-[#FEF3C7] text-[#D97706]' : 'bg-gray-100 text-gray-600'} text-[11px] font-bold rounded`}>
                    {pkg.isActive ? "Active" : "Draft"}
                  </span>
                </td>
                <td className="py-5 pr-6 text-right relative">
                  <div className="flex items-center justify-end gap-2">
                    <button 
                      onClick={() => navigate(`/subscriptions/edit/${pkg._id}`)}
                      className="text-gray-400 hover:text-[#0F172A] p-1.5 rounded-md transition-colors"
                    >
                      <Edit2 size={16} />
                    </button>
                    <button
                      onClick={() => setOpenActionId(openActionId === pkg._id ? null : pkg._id)}
                      className="text-gray-400 hover:text-gray-600 p-1.5 rounded-md transition-colors focus:outline-none"
                    >
                      <MoreVertical size={16} />
                    </button>
                  </div>

                  {openActionId === pkg._id && (
                    <>
                      <div 
                        className="fixed inset-0 z-50"
                        onClick={() => setOpenActionId(null)}
                      ></div>
                      <div className="absolute right-6 top-12 w-36 bg-white rounded-md shadow-xl border border-gray-100 z-50 py-1 overflow-hidden">
                        <button
                          onClick={() => setOpenActionId(null)}
                          className="w-full px-4 py-2 text-[12px] font-bold text-gray-700 hover:bg-gray-50 flex items-center justify-start gap-2 transition-colors"
                        >
                          Duplicate
                        </button>
                        <button
                          onClick={() => {
                            setOpenActionId(null);
                            handleDelete(pkg._id);
                          }}
                          className="w-full px-4 py-2 text-[12px] font-bold text-red-600 hover:bg-red-50 flex items-center justify-start gap-2 transition-colors"
                        >
                          Archive
                        </button>
                      </div>
                    </>
                  )}
                </td>
              </tr>
            ))}
            {plans.length === 0 && (
              <tr>
                <td colSpan="5" className="py-8 text-center text-[13px] font-medium text-gray-500">
                  No subscription packages found.
                </td>
              </tr>
            )}
          </tbody>
        </table>
      </div>
    </div>
  );
}

import React, { useEffect, useMemo, useState } from 'react';
import { ArrowRight, ArrowLeft, Check, LayoutGrid } from 'lucide-react';
import { useNavigate, useSearchParams } from 'react-router-dom';
import { useSelector } from 'react-redux';
import { toast } from 'react-toastify';
import { useGetCategoriesQuery } from '../../../redux/features/categories/categoryApi';
import {
  useGetOnboardingStatusQuery,
  useSaveOnboardingIndustryMutation,
} from '../../../redux/features/listings/listingsApi';
import { appendOnboardingContext, buildOnboardingQueryString } from '../../../utils/onboarding';

const ChooseIndustry = () => {
  const navigate = useNavigate();
  const [searchParams] = useSearchParams();
  const { user } = useSelector((state) => state.auth);
  const supplierId = user?.role === 'admin' ? searchParams.get('supplierId') : undefined;

  const { data: categoriesResponse, isLoading: isLoadingCategories } = useGetCategoriesQuery();
  const { data: onboardingResponse, isLoading: isLoadingOnboarding } = useGetOnboardingStatusQuery(supplierId, {
    skip: !user,
  });
  const [saveIndustry, { isLoading: isSaving }] = useSaveOnboardingIndustryMutation();

  const categories = categoriesResponse?.data || [];
  const supplier = onboardingResponse?.data?.supplier;
  const selectedCategoryIds = supplier?.categories?.map((category) => category._id) || [];

  const parentCategories = useMemo(
    () => categories.filter((category) => !category.parentCategory && category.status === 'Active'),
    [categories]
  );

  const [selectedParentId, setSelectedParentId] = useState('');
  const [selectedCategoryId, setSelectedCategoryId] = useState('');

  useEffect(() => {
    if (!user) {
      navigate(`/sign-in${buildOnboardingQueryString(searchParams)}`);
    }
  }, [navigate, searchParams, user]);

  useEffect(() => {
    if (!parentCategories.length) {
      return;
    }

    const currentCategory = categories.find((category) => selectedCategoryIds.includes(category._id));
    const parentId = currentCategory?.parentCategory || currentCategory?._id || parentCategories[0]._id;

    setSelectedParentId(parentId);

    if (currentCategory?._id) {
      setSelectedCategoryId(currentCategory._id);
      return;
    }

    const childCategories = categories.filter((category) => category.parentCategory === parentId);
    setSelectedCategoryId(childCategories[0]?._id || parentId);
  }, [categories, parentCategories, selectedCategoryIds]);

  const currentSubCategories = useMemo(() => {
    if (!selectedParentId) {
      return [];
    }

    const children = categories.filter((category) => category.parentCategory === selectedParentId && category.status === 'Active');
    return children.length > 0 ? children : categories.filter((category) => category._id === selectedParentId);
  }, [categories, selectedParentId]);

  const handleContinue = async () => {
    if (!selectedCategoryId) {
      toast.error('Please select an industry category to continue');
      return;
    }

    try {
      await saveIndustry({
        supplierId,
        categoryIds: [selectedCategoryId],
      }).unwrap();

      navigate(appendOnboardingContext('/company-info', searchParams));
    } catch (error) {
      toast.error(error?.data?.message || 'Failed to save your industry selection');
    }
  };

  if (!user) {
    return null;
  }

  return (
    <div className="min-h-screen bg-[#F9FAFB] flex flex-col font-sans">
      <div className="max-w-[1400px] mx-auto w-full">
        <div className="flex-1 flex flex-col items-center pt-12 pb-24 px-4 md:px-8 lg:px-12 w-full">
          <div className="text-center max-w-2xl mx-auto mb-12">
            <h1 className="text-3xl md:text-[40px] font-bold text-black mb-4 leading-tight">
              Choose Your Company
              <br />
              Industry
            </h1>
            <p className="text-gray-500 text-[15px]">
              Select the supplier category that best matches your company so customers can find you easily.
            </p>
          </div>

          {isLoadingCategories || isLoadingOnboarding ? (
            <div className="py-16 text-gray-500">Loading industries...</div>
          ) : parentCategories.length === 0 ? (
            <div className="w-full max-w-3xl rounded-xl border border-amber-200 bg-amber-50 px-6 py-5 text-amber-800">
              No active categories are available yet. Create supplier categories in the admin dashboard before onboarding suppliers.
            </div>
          ) : (
            <>
              <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-5 w-full mb-10">
                {parentCategories.map((industry) => {
                  const isSelected = selectedParentId === industry._id;

                  return (
                    <button
                      key={industry._id}
                      type="button"
                      onClick={() => {
                        setSelectedParentId(industry._id);
                        const childCategories = categories.filter((category) => category.parentCategory === industry._id && category.status === 'Active');
                        setSelectedCategoryId(childCategories[0]?._id || industry._id);
                      }}
                      className={`rounded-xl overflow-hidden text-left transition-all duration-200 border-2 ${
                        isSelected
                          ? 'border-[#D1A635] bg-[#FFFBF4] shadow-[0_4px_12px_rgba(209,166,53,0.15)]'
                          : 'border-transparent bg-white hover:border-gray-300 shadow-sm'
                      }`}
                    >
                      <div className="h-[120px] w-full bg-gradient-to-br from-[#1b2b3a] via-[#243b53] to-[#D1A635] relative">
                        {isSelected && (
                          <div className="absolute top-3 right-3 bg-blue-600 rounded-full w-6 h-6 flex items-center justify-center shadow-md z-10">
                            <Check className="w-3.5 h-3.5 text-white stroke-[3]" />
                          </div>
                        )}
                      </div>
                      <div className="p-4 md:p-5">
                        <h3 className={`font-bold text-[14px] mb-2 uppercase ${isSelected ? 'text-[#D1A635]' : 'text-gray-900'}`}>
                          {industry.name}
                        </h3>
                        <p className="text-gray-500 text-[12px] leading-relaxed line-clamp-3">
                          {industry.description || 'Supplier industry category'}
                        </p>
                      </div>
                    </button>
                  );
                })}
              </div>

              <div className="w-full bg-[#FAFAFA] border border-gray-200 rounded-xl overflow-hidden shadow-sm relative">
                <div className="absolute top-0 left-0 w-full h-1 bg-[#34D399]"></div>

                <div className="p-6 md:p-8 pt-8">
                  <div className="flex items-center gap-3 mb-6">
                    <LayoutGrid className="w-5 h-5 text-[#D1A635]" />
                    <h2 className="text-[20px] font-bold text-black">Select Industry Type</h2>
                  </div>

                  <div className="flex flex-wrap gap-3">
                    {currentSubCategories.map((subCategory) => {
                      const isSubSelected = selectedCategoryId === subCategory._id;
                      return (
                        <button
                          type="button"
                          key={subCategory._id}
                          onClick={() => setSelectedCategoryId(subCategory._id)}
                          className={`flex items-center gap-2 px-5 py-2.5 rounded-2xl text-[14px] font-medium transition-colors border ${
                            isSubSelected
                              ? 'border-[#D1A635] bg-[#FFFBF4] text-[#D1A635]'
                              : 'border-gray-200 bg-white text-gray-700 hover:border-gray-300'
                          }`}
                        >
                          {isSubSelected && <Check className="w-5 h-5 p-[3px] text-white rounded-full bg-[#D1A635]" strokeWidth={3} />}
                          {subCategory.name}
                        </button>
                      );
                    })}
                  </div>
                </div>
              </div>
            </>
          )}
        </div>

        <div className="border-t border-gray-200 bg-[#F9FAFB] py-4 px-6 md:px-12 w-full flex justify-between items-center sticky bottom-0 z-20">
          <button
            type="button"
            onClick={() => navigate(-1)}
            className="flex items-center gap-2 px-6 py-2.5 rounded border border-gray-300 bg-white text-gray-800 font-medium text-[14px] hover:bg-gray-50 transition-colors shadow-sm"
          >
            <ArrowLeft className="w-4 h-4" />
            Back
          </button>
          <button
            type="button"
            onClick={handleContinue}
            disabled={isSaving || parentCategories.length === 0}
            className="flex items-center gap-2 px-6 py-2.5 rounded bg-[#D1A635] hover:bg-[#C2982B] text-black font-bold text-[14px] transition-colors shadow-sm disabled:opacity-60"
          >
            {isSaving ? 'Saving...' : 'Continue'}
            <ArrowRight className="w-4 h-4 font-bold" />
          </button>
        </div>
      </div>
    </div>
  );
};

export default ChooseIndustry;

import React, { useEffect, useMemo, useState } from 'react';
import { Check, HeadphonesIcon, Lock, XCircle } from 'lucide-react';
import { useNavigate, useSearchParams } from 'react-router-dom';
import { useSelector } from 'react-redux';
import { toast } from 'react-toastify';
import { useGetPlansQuery } from '../../../redux/features/subscriptions/subscriptionsApi';
import {
  useGetOnboardingStatusQuery,
  useSaveOnboardingSubscriptionMutation,
} from '../../../redux/features/listings/listingsApi';
import { appendOnboardingContext, buildOnboardingQueryString } from '../../../utils/onboarding';

const Subscription = () => {
  const navigate = useNavigate();
  const [searchParams] = useSearchParams();
  const { user } = useSelector((state) => state.auth);
  const supplierId = user?.role === 'admin' ? searchParams.get('supplierId') : undefined;
  const { data: plansResponse, isLoading: isLoadingPlans } = useGetPlansQuery();
  const { data: onboardingResponse } = useGetOnboardingStatusQuery(supplierId, { skip: !user });
  const [saveSubscription, { isLoading: isSaving }] = useSaveOnboardingSubscriptionMutation();

  const plans = plansResponse?.data || [];
  const supplier = onboardingResponse?.data?.supplier;
  const selectedPlanId = supplier?.selectedPlan?._id || supplier?.selectedPlan || '';
  const [billingCycle, setBillingCycle] = useState('Monthly');
  const [currentPlanId, setCurrentPlanId] = useState('');

  useEffect(() => {
    if (!user) {
      navigate(`/sign-in${buildOnboardingQueryString(searchParams)}`);
    }
  }, [navigate, searchParams, user]);

  useEffect(() => {
    if (supplier?.selectedBillingCycle) {
      setBillingCycle(supplier.selectedBillingCycle);
    }
    if (selectedPlanId) {
      setCurrentPlanId(selectedPlanId);
    } else if (plans.length > 0) {
      setCurrentPlanId(plans[0]._id);
    }
  }, [plans, selectedPlanId, supplier]);

  const currentPlan = useMemo(
    () => plans.find((plan) => plan._id === currentPlanId) || null,
    [currentPlanId, plans]
  );

  const handleContinue = async () => {
    if (!currentPlanId) {
      toast.error('Please select a subscription plan to continue');
      return;
    }

    try {
      await saveSubscription({
        supplierId,
        planId: currentPlanId,
        billingCycle,
      }).unwrap();

      navigate(appendOnboardingContext('/cart', searchParams));
    } catch (error) {
      toast.error(error?.data?.message || 'Failed to save subscription selection');
    }
  };

  if (!user) {
    return null;
  }

  return (
    <div className="min-h-screen bg-[#F9FAFB] font-sans flex flex-col">
      <div className="w-full text-center pt-12 pb-6 px-4">
        <h1 className="text-3xl md:text-4xl font-bold text-[#111827] mb-3">Plans and Pricing</h1>
        <p className="text-[15px] text-gray-500">Pick the plan that checks your boxes.</p>
      </div>

      <div className="flex justify-center mb-12">
        <div className="flex items-center bg-[#EBF0FA] p-1 rounded-md border border-[#D1E0F5]">
          <button
            type="button"
            onClick={() => setBillingCycle('Monthly')}
            className={`px-8 py-2 rounded text-[13px] font-medium transition-all ${billingCycle === 'Monthly' ? 'bg-white shadow-sm text-[#111827]' : 'text-gray-500 hover:text-gray-700'}`}
          >
            Monthly
          </button>
          <button
            type="button"
            onClick={() => setBillingCycle('Annual (Paid Upfront)')}
            className={`px-8 py-2 rounded text-[13px] font-medium transition-all ${billingCycle === 'Annual (Paid Upfront)' ? 'bg-white shadow-sm text-[#111827]' : 'text-gray-500 hover:text-gray-700'}`}
          >
            Annual
          </button>
        </div>
      </div>

      <div className="max-w-[1100px] mx-auto px-4 md:px-8 w-full mb-20">
        {isLoadingPlans ? (
          <div className="py-12 text-center text-gray-500">Loading plans...</div>
        ) : plans.length === 0 ? (
          <div className="rounded-xl border border-amber-200 bg-amber-50 px-6 py-5 text-amber-800">
            No active pricing plans are available. Create a pricing package in the admin dashboard first.
          </div>
        ) : (
          <div className="flex flex-col md:flex-row gap-6 lg:gap-8 items-stretch md:items-center justify-center">
            {plans.map((plan) => {
              const isSelected = currentPlanId === plan._id;
              return (
                <button
                  key={plan._id}
                  type="button"
                  onClick={() => setCurrentPlanId(plan._id)}
                  className={`flex-1 bg-white rounded-xl p-8 flex flex-col text-left transition-all duration-300 relative ${
                    isSelected
                      ? 'border-2 border-[#D1A635] shadow-[0_8px_30px_rgb(0,0,0,0.08)] md:-mt-8 md:mb-8 z-10'
                      : 'border border-gray-200 shadow-sm hover:border-[#D1A635]/50 z-0'
                  }`}
                >
                  <div className={`absolute -top-3.5 left-1/2 -translate-x-1/2 text-[11px] font-bold px-4 py-1 rounded-full whitespace-nowrap shadow-sm ${
                    isSelected ? 'bg-[#D1A635] text-gray-900' : 'bg-gray-200 text-gray-600'
                  }`}>
                    {plan.badgeText || (isSelected ? 'SELECTED' : 'AVAILABLE')}
                  </div>

                  <h2 className="text-xl font-bold text-gray-900 mb-2 mt-2">{plan.name}</h2>
                  <p className="text-[13px] text-gray-500 mb-6 min-h-[40px]">{plan.description || 'Supplier listing plan'}</p>
                  <div className="flex items-end gap-1 mb-8">
                    <span className="text-4xl font-bold text-gray-900">${plan.price}</span>
                    <span className="text-[13px] text-gray-500 font-medium mb-1">{billingCycle === 'Monthly' ? '/mo' : '/yr'}</span>
                  </div>

                  <div className="space-y-4 flex-1 mb-8">
                    {(plan.features || []).length > 0 ? (
                      plan.features.map((feature) => (
                        <div key={feature} className="flex items-start gap-3">
                          <Check className="w-4 h-4 text-[#D1A635] shrink-0 mt-0.5" strokeWidth={isSelected ? 3 : 2} />
                          <span className={`text-[13px] ${isSelected ? 'text-gray-900 font-bold' : 'text-gray-700'}`}>{feature}</span>
                        </div>
                      ))
                    ) : (
                      <div className="text-[13px] text-gray-500">No feature highlights configured for this package yet.</div>
                    )}
                  </div>
                </button>
              );
            })}
          </div>
        )}
      </div>

      <div className="flex justify-center gap-4 mb-12 px-6">
