export default Subscription;

import React, { useState, useEffect } from 'react';
import GalleryHeader from '../../Components/Gallery/GalleryHeader';
import GalleryUploader from '../../Components/Gallery/GalleryUploader';
import GalleryTabs from '../../Components/Gallery/GalleryTabs';
import GalleryGrid from '../../Components/Gallery/GalleryGrid';
import GalleryTips from '../../Components/Gallery/GalleryTips';
import GalleryModal from '../../Components/Gallery/GalleryModal';
import { toast } from 'react-toastify';
import { useGetSupplierDashboardQuery, useUpdateListingMutation, useGetSupplierUploadUrlMutation } from '../../redux/features/listings/listingsApi';

export default function Gallery() {
  const { data: dashboardData, isLoading: isFetching, refetch } = useGetSupplierDashboardQuery();
  const [updateListing] = useUpdateListingMutation();
  const [getUploadUrl] = useGetSupplierUploadUrlMutation();

  const [activeTab, setActiveTab] = useState('All Files');
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isSaving, setIsSaving] = useState(false);
  const [files, setFiles] = useState([]);

  useEffect(() => {
    if (dashboardData?.data?.profile?.gallery) {
      // Map the MongoDB objects (which have _id) to ensure they have an id for the frontend
      const mappedFiles = dashboardData.data.profile.gallery.map(f => ({
        ...f,
        id: f._id || f.id || Date.now() + Math.random()
      }));
      setFiles(mappedFiles);
    }
  }, [dashboardData]);

  const handleUpload = async (newFiles) => {
    toast.info(`Uploading ${newFiles.length} file(s)...`);
    setIsSaving(true);
    try {
      const uploaded = await Promise.all(newFiles.map(async (file, idx) => {
        const isPdf = file.type.includes('pdf');
        const folder = isPdf ? 'documents' : 'galleries';
        
        const res = await getUploadUrl({ folder, contentType: file.type }).unwrap();
        const { uploadUrl, fileUrl } = res.data;
        
        await fetch(uploadUrl, {
          method: 'PUT',
          headers: { 'Content-Type': file.type },
          body: file
        });
        
        return {
          id: Date.now() + idx,
          title: file.name,
          type: isPdf ? 'Certificates' : 'Product Images',
          isPdf: isPdf,
          isPrimary: false,
          size: `${(file.size / (1024 * 1024)).toFixed(1)} MB`,
          url: fileUrl
        };
      }));
      const newFilesArray = [...files, ...uploaded];
      setFiles(newFilesArray);
      
      if (dashboardData?.data?.profile?._id) {
        await updateListing({ 
          id: dashboardData.data.profile._id, 
          data: { gallery: newFilesArray } 
        }).unwrap();
      }
      toast.success("Files uploaded and saved successfully.");
    } catch (error) {
      toast.error(error?.data?.message || "Failed to upload files.");
    } finally {
      setIsSaving(false);
    }
  };

  const handleSetPrimary = async (id) => {
    const newFilesArray = files.map(file => {
      if (file.isPdf) return file; 
      return {
        ...file,
        isPrimary: file.id === id || file._id === id
      };
    });
    setFiles(newFilesArray);
    
    if (dashboardData?.data?.profile?._id) {
      try {
        await updateListing({ 
          id: dashboardData.data.profile._id, 
          data: { gallery: newFilesArray } 
        }).unwrap();
        toast.success("Primary image updated successfully.");
      } catch (error) {
        toast.error("Failed to update primary image.");
      }
    }
  };

  const handleSaveModalFile = async (data) => {
    setIsSaving(true);
    toast.info("Uploading file...");
    try {
      const isPdf = data.isPdf;
      const folder = isPdf ? 'documents' : 'galleries';
      
      const res = await getUploadUrl({ folder, contentType: data.file.type }).unwrap();
      const { uploadUrl, fileUrl } = res.data;
      
      await fetch(uploadUrl, {
        method: 'PUT',
        headers: { 'Content-Type': data.file.type },
        body: data.file
      });
      
      const newFile = {
        id: Date.now(),
        title: data.title,
        type: data.type,
        isPdf: data.isPdf,
        isPrimary: false,
        size: `${(data.file.size / (1024 * 1024)).toFixed(1)} MB`,
        url: fileUrl
      };
      const newFilesArray = [...files, newFile];
      setFiles(newFilesArray);
      
      if (dashboardData?.data?.profile?._id) {
        await updateListing({ 
          id: dashboardData.data.profile._id, 
          data: { gallery: newFilesArray } 
        }).unwrap();
      }
      toast.success("File uploaded and saved successfully.");
    } catch (error) {
      toast.error(error?.data?.message || "Failed to upload file.");
    } finally {
      setIsSaving(false);
    }
  };

  const handleSave = async () => {
    if (!dashboardData?.data?.profile?._id) return;
    setIsSaving(true);
    try {
      await updateListing({ 
        id: dashboardData.data.profile._id, 
        data: { gallery: files } 
      }).unwrap();
      toast.success(`Gallery saved successfully! You currently have ${files.length} items in your gallery.`);
      refetch();
    } catch (error) {
      toast.error(error?.data?.message || "Failed to save gallery.");
    } finally {
      setIsSaving(false);
    }
  };

  const handlePreview = () => {
    const primaryImage = files.find(f => f.isPrimary);
    if (primaryImage) {
      toast.info(`Previewing Listing: Primary Image is "${primaryImage.title}" (Total Files: ${files.length})`);
    } else {
      toast.info(`Previewing Listing: Total Files: ${files.length}. No primary image set yet!`);
    }
  };

  return (
    <div className="min-h-screen p-6 lg:p-8 bg-[#F8F9FB] text-[#0F172A] font-sans mt-16">
      <GalleryHeader 
        onPreview={handlePreview}
        onSave={handleSave}
        saveText={isSaving ? "Saving..." : "Save Gallery"}
      />

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
        {/* Main Content Area */}
        <div className="lg:col-span-2">
          <GalleryUploader onUpload={handleUpload} />
          
          <div>
            <GalleryTabs activeTab={activeTab} onTabChange={setActiveTab} />
            <GalleryGrid 
              files={files} 
              activeTab={activeTab} 
              onSetPrimary={handleSetPrimary} 
              onAddNewFile={() => setIsModalOpen(true)}
            />
          </div>
        </div>

        {/* Right Sidebar */}
        <div>
          <GalleryTips />
        </div>
      </div>
      
      <GalleryModal 
        isOpen={isModalOpen}
        onClose={() => setIsModalOpen(false)}
        onSave={handleSaveModalFile}
      />

      {/* Footer */}
      <div className="flex flex-col md:flex-row justify-between items-center text-[11px] font-bold text-gray-500 pt-6 mt-12 pb-4 border-t border-gray-200">
        <p>© 2024 WULFARA Industrial Marketplace. All rights reserved.</p>
        <div className="flex gap-6 mt-4 md:mt-0 text-gray-500">
          <a href="#" className="hover:text-gray-900 transition">Support</a>
          <a href="#" className="hover:text-gray-900 transition">Privacy Policy</a>
          <a href="#" className="hover:text-gray-900 transition">Terms of Service</a>
        </div>
      </div>
    </div>
  );
}

import React, { useState, useMemo } from 'react';
import { useSearchParams } from 'react-router-dom';
import MessageSidebar from '../../Components/Messages/MessageSidebar';
import MessageContent from '../../Components/Messages/MessageContent';
import { Plus } from 'lucide-react';
import { useGetConversationsQuery } from '../../redux/features/messages/messagesApi';

export default function Messages() {
  const [searchParams] = useSearchParams();
  const newUserId = searchParams.get('new');
  const newUserName = searchParams.get('name');

  const [activeTab, setActiveTab] = useState('Inbox');
  const [selectedChat, setSelectedChat] = useState(newUserId ? `new-${newUserId}` : null);

  const { data: conversationsResponse, isLoading } = useGetConversationsQuery(undefined, { pollingInterval: 30000 });
  const rawConversations = conversationsResponse?.data || [];

  const conversations = useMemo(() => {
    let list = [...rawConversations];

    if (newUserId && newUserName) {
      const exists = list.some((c) => c.participants?.some((p) => p._id === newUserId));
      if (!exists) {
        list.unshift({
          _id: `new-${newUserId}`,
          participants: [{ _id: newUserId, name: newUserName, role: 'buyer' }],
          lastMessage: { text: "Start a new conversation..." },
          lastMessageAt: new Date().toISOString(),
          hasUnread: false
        });
      }
    }

    return list;
  }, [rawConversations, newUserId, newUserName]);

  const tabs = [
    { id: 'Inbox', label: 'Inbox' },
    { id: 'Sourcing', label: 'Sourcing' },
    { id: 'RFQ', label: 'RFQ Conversations' },
    { id: 'Unread', label: 'Unread', badge: conversations.filter(c => c.hasUnread).length || null }
  ];

  return (
    <div className="min-h-screen p-6 lg:p-8 bg-[#F8F9FB] text-[#0F172A] font-sans mt-10">

      {/* Header */}
      <div className="mb-6 flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h1 className="text-[28px] font-bold tracking-tight text-[#0F172A] mb-1">Messages</h1>
          <p className="text-[13px] font-medium text-gray-500">
            Manage conversations with buyers, RFQs, sourcing requests, and supplier inquiries.
          </p>
        </div>
      </div>

      {/* Tabs */}
      <div className="border-b border-gray-200 mb-6 flex gap-6 overflow-x-auto no-scrollbar">
        {tabs.map(tab => (
          <button
            key={tab.id}
            onClick={() => setActiveTab(tab.id)}
            className={`pb-3 text-[13px] font-bold whitespace-nowrap transition border-b-2 flex items-center gap-2 ${activeTab === tab.id
              ? 'border-[#0F172A] text-[#0F172A]'
              : 'border-transparent text-gray-500 hover:text-gray-900'
              }`}
          >
            {tab.label}
            {tab.badge && (
              <span className={`px-1.5 py-0.5 rounded-full text-[10px] ${activeTab === tab.id ? 'bg-[#DC2626] text-white' : 'bg-[#DC2626] text-white'
                }`}>
                {tab.badge}
              </span>
            )}
          </button>
        ))}
      </div>

      {/* Main Grid */}
      <div className="grid grid-cols-1 lg:grid-cols-12 gap-6 h-[calc(100vh-220px)] min-h-0">
        {/* Left Sidebar */}
        <div className="lg:col-span-4 xl:col-span-3 h-full min-h-0">
          <MessageSidebar
            conversations={conversations}
            isLoading={isLoading}
            activeTab={activeTab}
            selectedChat={selectedChat}
            setSelectedChat={setSelectedChat}
          />
        </div>

        {/* Right Content */}
        <div className="lg:col-span-8 xl:col-span-9 h-full min-h-0">
          <MessageContent selectedChat={selectedChat} />
        </div>
      </div>

    </div>
  );
}

import React, { useState, useMemo } from 'react';
import ProductsHeader from '../../Components/ProductsServices/ProductsHeader';
import ProductsSummaryCards from '../../Components/ProductsServices/ProductsSummaryCards';
import ProductsDataGrid from '../../Components/ProductsServices/ProductsDataGrid';
import ProductModal from '../../Components/ProductsServices/ProductModal';

import { toast } from 'react-toastify';
import { useGetSupplierDashboardQuery, useUpdateListingMutation, useGetSupplierUploadUrlMutation } from '../../redux/features/listings/listingsApi';

export default function ProductsServices() {
  const { data: dashboardData, isLoading: isFetching, refetch } = useGetSupplierDashboardQuery();
  const [updateListing, { isLoading: isUpdating }] = useUpdateListingMutation();
  const [getUploadUrl] = useGetSupplierUploadUrlMutation();

  const [filters, setFilters] = useState({
    search: '',
    category: 'All Categories',
    status: 'All Statuses'
  });

  const products = dashboardData?.data?.profile?.products || [];

  const summaryData = useMemo(() => {
    return {
      total: products.length,
      published: products.filter(p => p.status === 'Published').length,
      drafts: products.filter(p => p.status === 'Draft').length,
      quoteEnabled: products.filter(p => p.priceVis === 'Quote Only').length
    };
  }, [products]);

  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingProduct, setEditingProduct] = useState(null);

  const [currentPage, setCurrentPage] = useState(1);
  const itemsPerPage = 3;

  const filteredProducts = useMemo(() => {
    return products.filter(p => {
      const pTitle = p.title || p.name || '';
      const pDesc = p.description || '';
      const matchesSearch = pTitle.toLowerCase().includes(filters.search.toLowerCase()) || 
                            pDesc.toLowerCase().includes(filters.search.toLowerCase());
      const matchesCategory = filters.category === 'All Categories' || p.category === filters.category;
      const matchesStatus = filters.status === 'All Statuses' || p.status === filters.status;
      
      return matchesSearch && matchesCategory && matchesStatus;
    });
  }, [products, filters.search, filters.category, filters.status]);

  const totalFiltered = filteredProducts.length;
  const totalPages = Math.ceil(totalFiltered / itemsPerPage) || 1;
  const startIndex = (currentPage - 1) * itemsPerPage;
  const paginatedProducts = filteredProducts.slice(startIndex, startIndex + itemsPerPage);

  const pagination = {
    start: totalFiltered === 0 ? 0 : startIndex + 1,
    end: Math.min(startIndex + itemsPerPage, totalFiltered),
    total: totalFiltered,
    currentPage: currentPage,
    totalPages: totalPages
  };

  const handleFilterChange = (newFilters) => {
    setFilters(newFilters);
    setCurrentPage(1); 
  };

  const handlePageChange = (page) => {
    setCurrentPage(page);
  };

  const handleAddProduct = () => {
    setEditingProduct(null);
    setIsModalOpen(true);
  };

  const handleEditProduct = (product) => {
    setEditingProduct(product);
    setIsModalOpen(true);
  };

  const handleSaveProduct = async (productData) => {
    let finalImageUrl = productData.image;

    // Handle new image upload to S3 if a file was selected
    if (productData.imageFile) {
      toast.info("Uploading product image...");
      try {
        const file = productData.imageFile;
        const res = await getUploadUrl({ folder: 'galleries', contentType: file.type }).unwrap();
        const { uploadUrl, fileUrl } = res.data;
        
        await fetch(uploadUrl, {
          method: 'PUT',
          headers: { 'Content-Type': file.type },
          body: file
        });
        
        finalImageUrl = fileUrl;
      } catch (error) {
        toast.error("Failed to upload product image, proceeding without it.");
      }
    }

    const formattedPriceVis = productData.priceVis === 'Publicly Visible' ? 'Visible' : 
                              productData.priceVis === 'Quote Only (Requires RFQ)' ? 'Quote Only' : 'Hidden';
    const formattedStatus = productData.status === 'Publish Immediately' ? 'Published' : 'Draft';
    
    let updatedProducts = [...products];

    if (editingProduct) {
      updatedProducts = updatedProducts.map(p => {
        if (p._id === editingProduct._id) {
          return {
            ...p,
            title: productData.title,
            description: productData.description,
            category: productData.category,
            moq: productData.moq,
            image: finalImageUrl,
            priceVis: formattedPriceVis,
            status: formattedStatus
          };
        }
        return p;
      });
    } else {
      const newProduct = {
        title: productData.title,
        description: productData.description,
        category: productData.category,
        moq: productData.moq,
        image: finalImageUrl,
        priceVis: formattedPriceVis,
        status: formattedStatus
      };
      updatedProducts = [newProduct, ...updatedProducts];
    }
    
    try {
      await updateListing({ 
        id: dashboardData.data.profile._id, 
        data: { products: updatedProducts } 
      }).unwrap();
      
      toast.success(editingProduct ? "Product updated successfully!" : "Product added successfully!");
      refetch();
    } catch (error) {
      toast.error(error?.data?.message || "Failed to save product");
    }
  };

  return (
    <div className="min-h-screen p-6 lg:p-8 bg-[#F8F9FB] text-[#0F172A] font-sans mt-16">
      <ProductsHeader onAddProduct={handleAddProduct} />
      
      <ProductsSummaryCards summaryData={summaryData} />

      <ProductsDataGrid 
        products={paginatedProducts} 
        filters={filters} 
        onFilterChange={handleFilterChange}
        pagination={pagination}
        onPageChange={handlePageChange}
        onEditProduct={handleEditProduct}
      />

      <ProductModal 
        isOpen={isModalOpen}
        onClose={() => setIsModalOpen(false)}
        product={editingProduct}
        onSave={handleSaveProduct}
      />

      {/* Footer */}
      <div className="flex flex-col md:flex-row justify-between items-center text-[11px] font-bold text-gray-500 pt-4 pb-4 border-t border-gray-200">
        <p>© 2024 WULFARA Industrial Marketplace. All rights reserved.</p>
        <div className="flex gap-6 mt-4 md:mt-0 text-gray-500">
          <a href="#" className="hover:text-gray-900 transition">Support</a>
          <a href="#" className="hover:text-gray-900 transition">Privacy Policy</a>
          <a href="#" className="hover:text-gray-900 transition">Terms of Service</a>
        </div>
      </div>
    </div>
  );
}

import React, { useState, useMemo } from "react";
import { Download, Plus, ChevronDown } from "lucide-react";
import { 
  useGetUsersQuery, 
  useCreateUserMutation, 
  useUpdateUserMutation, 
  useDeleteUserMutation 
} from "../../../redux/features/users/usersApi";
import BuyerTable, { Pagination } from "../../../Components/admin-components/buyer/BuyerTable";
import BuyerFormModal from "../../../Components/admin-components/buyer/BuyerFormModal";

export default function BuyerManagement() {
  const { data: usersResponse, isLoading } = useGetUsersQuery();
  const users = usersResponse?.data || [];
  const [createUser] = useCreateUserMutation();
  const [updateUser] = useUpdateUserMutation();
  const [deleteUser] = useDeleteUserMutation();

  // Filter only buyers
  const buyers = useMemo(() => {
    return users.filter(user => user.role === 'buyer').map(user => ({
      id: user._id,
      name: user.name,
      email: user.email,
      status: user.status || "Active",
      verification: user.isVerified ? "Verified" : "Unverified",
      rfqs: 0, // Placeholder
      favs: 0, // Placeholder
      createdDate: new Date(user.createdAt).toLocaleDateString('en-US', { month: 'short', day: '2-digit' }) + ',',
      createdYear: new Date(user.createdAt).getFullYear().toString(),
      avatarColor: "bg-[#DBEAFE]", // default
      initials: user.name ? user.name.substring(0, 2).toUpperCase() : "NA"
    }));
  }, [users]);

  const [currentPage, setCurrentPage] = useState(1);
  const [selectedIds, setSelectedIds] = useState([]);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingBuyer, setEditingBuyer] = useState(null);
  const [statusFilter, setStatusFilter] = useState("All");
  const [verificationFilter, setVerificationFilter] = useState("All");
  const pageSize = 6;

  const handleSaveBuyer = async (savedBuyer) => {
    try {
      const isVerified = savedBuyer.verification === 'Verified';
      
      if (editingBuyer) {
        await updateUser({ 
          id: savedBuyer.id, 
          userData: { 
            name: savedBuyer.name, 
            email: savedBuyer.email, 
            status: savedBuyer.status,
            isVerified
          } 
        }).unwrap();
      } else {
        await createUser({
          name: savedBuyer.name,
          email: savedBuyer.email,
          password: "DefaultPassword123!", // Require strong default for now
          role: "buyer",
          status: savedBuyer.status,
          isVerified
        }).unwrap();
      }
      setEditingBuyer(null);
      setIsModalOpen(false);
    } catch (err) {
      console.error(err);
      alert("Error saving buyer");
    }
  };

  const handleDeleteBuyer = async (id) => {
    if (window.confirm("Are you sure you want to delete this buyer?")) {
      try {
        await deleteUser(id).unwrap();
      } catch (err) {
        console.error(err);
        alert("Error deleting buyer");
      }
    }
  };

  const openAddModal = () => {
    setEditingBuyer(null);
    setIsModalOpen(true);
  };

  const openEditModal = (buyer) => {
    setEditingBuyer(buyer);
    setIsModalOpen(true);
  };

  const handlePrint = () => {
    window.print();
  };

  const filteredBuyers = useMemo(() => {
    return buyers.filter(buyer => {
      const matchStatus = statusFilter === "All" || buyer.status === statusFilter;
      const matchVerification = verificationFilter === "All" || buyer.verification === verificationFilter;
      return matchStatus && matchVerification;
    });
  }, [buyers, statusFilter, verificationFilter]);

  const paginatedBuyers = useMemo(() => {
    const start = (currentPage - 1) * pageSize;
    return filteredBuyers.slice(start, start + pageSize);
  }, [currentPage, filteredBuyers]);

  const handleSelect = (id) => {
    setSelectedIds((prev) =>
      prev.includes(id) ? prev.filter((i) => i !== id) : [...prev, id]
    );
  };

  const handleSelectAll = (e) => {
    if (e.target.checked) {
      setSelectedIds(paginatedBuyers.map(b => b.id));
    } else {
      setSelectedIds([]);
    }
  };

  const handleBulkVerify = async () => {
    try {
      await Promise.all(selectedIds.map(id => 
        updateUser({ id, userData: { isVerified: true } }).unwrap()
      ));
      setSelectedIds([]);
    } catch (err) {
      console.error(err);
      alert("Error verifying buyers");
    }
  };

  const handleBulkSuspend = async () => {
    try {
      await Promise.all(selectedIds.map(id => 
        updateUser({ id, userData: { status: 'Suspended' } }).unwrap()
      ));
      setSelectedIds([]);
    } catch (err) {
      console.error(err);
      alert("Error suspending buyers");
    }
  };

  const hasSelection = selectedIds.length > 0;

  return (
    <div className="min-h-screen p-6 mt-16 lg:p-8 bg-[#F8F9FB] text-[#0F172A] font-sans pt-24">

      {/* Header Section */}
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center mb-8 gap-4">
        <div>
          <h1 className="text-3xl font-extrabold text-[#0F172A] mb-2 tracking-tight">
            Buyer Management
          </h1>
          <p className="text-[14px] text-gray-500 font-medium">
            Manage public buyers, monitor activity, and handle verifications.
          </p>
        </div>

        <div className="flex items-center gap-3">
          <button 
            onClick={handlePrint}
            className="flex items-center gap-2 px-4 py-2 bg-white border border-gray-200 rounded-md text-[13px] font-bold text-[#0F172A] hover:bg-gray-50 transition-colors shadow-sm print:hidden"
          >
            <Download size={16} />
            Print Data
          </button>
          <button 
            onClick={openAddModal}
            className="flex items-center gap-2 px-4 py-2 bg-[#D4AF37] border border-[#D4AF37] rounded-md text-[13px] font-bold text-[#0F172A] hover:bg-[#C2982B] transition-colors shadow-sm"
          >
            <Plus size={16} strokeWidth={3} />
            Add Buyer
          </button>
        </div>
      </div>

      {/* Main Content Area */}
      <div className="bg-white border border-gray-200 rounded-xl shadow-sm mb-8">

        {/* Filters and Bulk Actions Bar */}
        <div className="flex flex-col lg:flex-row justify-between items-start lg:items-center p-4 border-b border-gray-100 gap-4">

          <div className="flex flex-wrap items-center gap-3">
            <div className="relative">
              <select 
                value={statusFilter}
                onChange={(e) => {
                  setStatusFilter(e.target.value);
                  setCurrentPage(1);
                }}
                className="appearance-none flex items-center justify-between gap-2 pl-3 pr-8 py-2 bg-[#F1F5F9] rounded-md text-[12px] font-bold text-[#475569] min-w-[120px] hover:bg-[#E2E8F0] transition-colors outline-none cursor-pointer"
              >
                <option value="All">All Statuses</option>
                <option value="Active">Active</option>
                <option value="Pending">Pending</option>
                <option value="Suspended">Suspended</option>
              </select>
              <ChevronDown size={14} className="absolute right-3 top-2.5 text-[#475569] pointer-events-none" />
            </div>

            <div className="relative">
              <select 
                value={verificationFilter}
                onChange={(e) => {
                  setVerificationFilter(e.target.value);
                  setCurrentPage(1);
                }}
                className="appearance-none flex items-center justify-between gap-2 pl-3 pr-8 py-2 bg-[#E0E7FF] rounded-md text-[12px] font-bold text-[#4338CA] min-w-[140px] hover:bg-[#C7D2FE] transition-colors outline-none cursor-pointer"
              >
                <option value="All">Verification: All</option>
                <option value="Verified">Verified</option>
                <option value="Unverified">Unverified</option>
                <option value="TOS Violation">TOS Violation</option>
              </select>
              <ChevronDown size={14} className="absolute right-3 top-2.5 text-[#4338CA] pointer-events-none" />
            </div>

            <button className="flex items-center justify-between gap-2 px-3 py-2 bg-[#E0E7FF] rounded-md text-[12px] font-bold text-[#4338CA] min-w-[160px] hover:bg-[#C7D2FE] transition-colors">
              Activity: Last 30 Days
              <ChevronDown size={14} />
            </button>
          </div>

          <div className="flex items-center gap-3 w-full lg:w-auto">
            <span className="text-[12px] font-bold text-gray-500 mr-1">Bulk Actions:</span>
            <button
              onClick={handleBulkVerify}
              disabled={!hasSelection || isLoading}
              className="px-4 py-2 border border-gray-200 rounded-md text-[12px] font-bold text-gray-600 bg-white hover:bg-gray-50 disabled:opacity-50 disabled:cursor-not-allowed transition-colors shadow-sm"
            >
              Verify
            </button>
            <button
              onClick={handleBulkSuspend}
              disabled={!hasSelection || isLoading}
              className="px-4 py-2 border border-gray-200 rounded-md text-[12px] font-bold text-gray-600 bg-white hover:bg-gray-50 disabled:opacity-50 disabled:cursor-not-allowed transition-colors shadow-sm"
            >
              Suspend
            </button>
          </div>

        </div>

        {/* Table Area */}
        {isLoading ? (
          <div className="p-8 text-center text-gray-500">Loading buyers...</div>
        ) : (
          <BuyerTable 
            buyers={paginatedBuyers}
            selectedIds={selectedIds}
            onSelect={handleSelect}
            onSelectAll={handleSelectAll}
            onEdit={openEditModal}
            onDelete={handleDeleteBuyer}
          />
        )}

        {/* Pagination Area */}
        {!isLoading && (
          <Pagination 
            currentPage={currentPage}
            totalItems={filteredBuyers.length}
            pageSize={pageSize}
            onPageChange={setCurrentPage}
          />
        )}

      </div>

      <BuyerFormModal 
        isOpen={isModalOpen} 
        onClose={() => setIsModalOpen(false)}
        onSave={handleSaveBuyer}
        buyer={editingBuyer}
      />
    </div>
  );
}

import React, { useState } from "react";
import {
  Folder,
  Network,
  Eye,
  EyeOff,
  Download,
  Plus,
  Diamond,
  Settings2,
  Truck,
  Wrench,
  Briefcase,
  Beaker,
  Factory
} from "lucide-react";
import CategoryHierarchyPanel from "../../../Components/admin-components/categories/CategoryHierarchyPanel";
import CategoryRegistryTable from "../../../Components/admin-components/categories/CategoryRegistryTable";
import { Link } from "react-router-dom";
import { useGetCategoriesQuery, useDeleteCategoryMutation } from "../../../redux/features/categories/categoryApi";

// Helper to build tree from flat list
const buildCategoryTree = (flatCats) => {
  const categoryMap = new Map();
  flatCats.forEach(c => categoryMap.set(c._id, {
    ...c,
    id: c._id,
    isRoot: !c.parentCategory,
    children: []
  }));

  const rootNodes = [];
  flatCats.forEach(c => {
    if (c.parentCategory && categoryMap.has(c.parentCategory)) {
      categoryMap.get(c.parentCategory).children.push(categoryMap.get(c._id));
    } else {
      rootNodes.push(categoryMap.get(c._id));
    }
  });
  return rootNodes;
};

export default function CategoryManagement() {
  const { data: categoriesResponse, isLoading } = useGetCategoriesQuery();
  const categories = categoriesResponse?.data || [];
  const [deleteCategory] = useDeleteCategoryMutation();
  const [activeCategoryId, setActiveCategoryId] = useState(null);

  const handleUpdateCategory = (categoryId, updates) => {
    // For now, this is mock UI update. Proper implementation needs PUT API.
    console.log("Update requested for", categoryId, updates);
  };

  const handleDeleteCategory = async (categoryId) => {
    if (!window.confirm("Are you sure you want to delete this category?")) return;
    try {
      await deleteCategory(categoryId).unwrap();
      if (activeCategoryId === categoryId) {
        setActiveCategoryId(null);
      }
    } catch (err) {
      console.error("Failed to delete category", err);
    }
  };

  const categoryTree = buildCategoryTree(categories);
  const flatCategories = categories;

  // Calculate dynamic stats
  const mainCategories = categories.filter(c => !c.parentCategory);
  const subCategories = categories.filter(c => c.parentCategory);
  
  const oneWeekAgo = new Date();
  oneWeekAgo.setDate(oneWeekAgo.getDate() - 7);
  const newMainCategoriesCount = mainCategories.filter(c => c.createdAt && new Date(c.createdAt) > oneWeekAgo).length;
  
  const activeSubcategoriesCount = subCategories.filter(c => c.status === 'Active').length;
  
  const activeCategoriesCount = categories.filter(c => c.status === 'Active').length;
  const activeRatio = categories.length > 0 ? Math.round((activeCategoriesCount / categories.length) * 100) : 0;
  
  const hiddenCategoriesCount = categories.filter(c => c.status === 'Hidden').length;
  const draftCategoriesCount = categories.filter(c => c.status === 'Draft').length;

  return (
    <div className="min-h-screen p-6 mt-16 lg:p-8 bg-[#F8F9FB] text-[#0F172A] font-sans pt-24">

      {/* Header */}
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center mb-8 gap-4">
        <div>
          <h1 className="text-3xl font-extrabold text-[#0F172A] tracking-tight mb-1">
            Category Management
          </h1>
          <p className="text-[13px] font-medium text-gray-500 max-w-md leading-relaxed">
            Create, organize, edit, and manage WULFARA supplier categories and subcategories.
          </p>
        </div>
        <div className="flex items-center gap-3">
          <button className="flex items-center gap-2 px-4 py-2.5 bg-white border border-gray-200 rounded-md text-[13px] font-bold text-gray-700 hover:bg-gray-50 transition-colors shadow-sm">
            <Download size={16} />
            Export Data
          </button>
          <Link
            to="/categories/create"
            className="flex items-center gap-2 px-4 py-2.5 bg-[#D4AF37] border border-[#D4AF37] rounded-md text-[13px] font-bold text-[#0F172A] hover:bg-[#C2982B] transition-colors shadow-sm"
          >
            <Plus size={16} className="text-[#0F172A]" />
            New Category
          </Link>
        </div>
      </div>

      {/* Summary Cards */}
      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-6 mb-8">

        <div className="bg-white rounded-xl shadow-sm border border-gray-200 p-6 flex flex-col justify-between h-32">
          <div className="flex justify-between items-start">
            <div className="w-10 h-10 rounded-lg bg-gray-50 flex items-center justify-center text-gray-400">
              <Folder size={20} />
            </div>
            <span className={`text-[11px] font-bold ${newMainCategoriesCount > 0 ? 'text-[#10B981]' : 'text-gray-400'}`}>
              +{newMainCategoriesCount} New
            </span>
          </div>
          <div>
            <div className="text-3xl font-extrabold text-[#0F172A]">{mainCategories.length}</div>
            <div className="text-[12px] font-medium text-gray-400">Main Categories</div>
          </div>
        </div>

        <div className="bg-white rounded-xl shadow-sm border border-gray-200 p-6 flex flex-col justify-between h-32">
          <div className="flex justify-between items-start">
            <div className="w-10 h-10 rounded-lg bg-[#F0FDF4] flex items-center justify-center text-[#10B981]">
              <Network size={20} />
            </div>
            <span className="text-[11px] font-bold text-[#10B981]">{activeSubcategoriesCount} Active</span>
          </div>
          <div>
            <div className="text-3xl font-extrabold text-[#0F172A]">{subCategories.length}</div>
            <div className="text-[12px] font-medium text-gray-400">Subcategories</div>
          </div>
        </div>

        <div className="bg-white rounded-xl shadow-sm border border-gray-200 p-6 flex flex-col justify-between h-32">
          <div className="flex justify-between items-start">
            <div className="w-10 h-10 rounded-lg bg-[#ECFDF5] flex items-center justify-center text-[#10B981]">
              <Eye size={20} />
            </div>
            <span className={`text-[11px] font-bold ${activeRatio >= 50 ? 'text-[#10B981]' : 'text-[#D97706]'}`}>
              {activeRatio}% Ratio
            </span>
          </div>
          <div>
            <div className="text-3xl font-extrabold text-[#0F172A]">{activeCategoriesCount}</div>
            <div className="text-[12px] font-medium text-gray-400">Active Categories</div>
          </div>
        </div>

        <div className="bg-white rounded-xl shadow-sm border border-gray-200 p-6 flex flex-col justify-between h-32">
          <div className="flex justify-between items-start">
            <div className="w-10 h-10 rounded-lg bg-[#FEF2F2] flex items-center justify-center text-[#EF4444]">
              <EyeOff size={20} />
            </div>
            {draftCategoriesCount > 0 ? (
              <span className="text-[11px] font-bold text-[#D97706]">{draftCategoriesCount} Draft</span>
            ) : (
              <span className="text-[11px] font-bold text-gray-400">Review Done</span>
            )}
          </div>
          <div>
            <div className="text-3xl font-extrabold text-[#0F172A]">{hiddenCategoriesCount}</div>
            <div className="text-[12px] font-medium text-gray-400">Hidden Categories</div>
          </div>
        </div>

      </div>

      <div className="space-y-8">
        {/* Red Box 1: Hierarchy Tree & Category Details */}
        {/* <CategoryHierarchyPanel 
            categories={categoryTree} 
            activeCategoryId={activeCategoryId} 
            onSelectCategory={setActiveCategoryId} 
            onUpdateCategory={handleUpdateCategory}
            onDeleteCategory={handleDeleteCategory}
          /> */}

        {/* Red Box 2: All Categories Registry */}
        <CategoryRegistryTable
          categories={flatCategories}
          onDeleteCategory={handleDeleteCategory}
        />
      </div>

    </div>
  );
}

import React, { useState, useEffect } from "react";
import { Link, useNavigate, useSearchParams } from "react-router-dom";
import { useGetCategoriesQuery, useCreateCategoryMutation, useGetUploadUrlMutation } from "../../../redux/features/categories/categoryApi";
import axios from "axios";
import { 
  Info, 
  Image as ImageIcon, 
  CloudUpload, 
  Eye
} from "lucide-react";

export default function CreateCategory() {
  const navigate = useNavigate();
  const [searchParams] = useSearchParams();
  const parentParam = searchParams.get("parent");
  
  const { data: categoriesResponse, isLoading: isLoadingCategories } = useGetCategoriesQuery();
  const categories = categoriesResponse?.data || [];
  const [createCategory, { isLoading: isCreating, isError, isSuccess, error }] = useCreateCategoryMutation();
  const [getUploadUrl] = useGetUploadUrlMutation();

  const [localLoading, setLocalLoading] = useState(false);
  const [localError, setLocalError] = useState("");
  const [submitted, setSubmitted] = useState(false);

  const [bannerFile, setBannerFile] = useState(null);
  const [iconFile, setIconFile] = useState(null);
  const [bannerPreview, setBannerPreview] = useState("https://images.unsplash.com/photo-1518709268805-4e9042af9f23?q=80&w=2104&auto=format&fit=crop");
  const [iconPreview, setIconPreview] = useState(null);
  const [formData, setFormData] = useState({
    name: "",
    slug: "",
    description: "",
    displayOrder: "1",
    parentCategory: parentParam || "None (Main Category)",
    status: "Active"
  });

  // Auto-generate slug when name changes
  useEffect(() => {
    if (formData.name) {
      const generatedSlug = formData.name
        .toLowerCase()
        .replace(/[^a-z0-9]+/g, '-')
        .replace(/(^-|-$)+/g, '');
      
      setFormData(prev => ({ ...prev, slug: generatedSlug }));
    } else {
      setFormData(prev => ({ ...prev, slug: "" }));
    }
  }, [formData.name]);

  useEffect(() => {
    if (isError && submitted) {
      setLocalError(error?.data?.message || "Error creating category");
      setSubmitted(false);
    }
    if (isSuccess && submitted) {
      navigate("/categories");
    }
  }, [isError, isSuccess, error, navigate, submitted]);

  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData(prev => ({ ...prev, [name]: value }));
  };

  const handleBannerUpload = (e) => {
    const file = e.target.files[0];
    if (file) {
      setBannerFile(file);
      setBannerPreview(URL.createObjectURL(file));
    }
  };

  const handleIconUpload = (e) => {
    const file = e.target.files[0];
    if (file) {
      setIconFile(file);
      setIconPreview(URL.createObjectURL(file));
    }
  };

  const uploadFileToS3 = async (uploadUrl, file) => {
    return axios.put(uploadUrl, file, {
      headers: {
        'Content-Type': file.type
      }
    });
  };

  const handleSubmit = async () => {
    setLocalLoading(true);
    setLocalError("");
    try {
      let iconUrl = "no-icon.png";
      let bannerUrl = "no-banner.jpg";

      const uploadTasks = [];

      // Upload Icon
      if (iconFile) {
        uploadTasks.push((async () => {
          const iconPresignData = await getUploadUrl(iconFile.type).unwrap();
          if (iconPresignData.success) {
            await uploadFileToS3(iconPresignData.data.uploadUrl, iconFile);
            iconUrl = iconPresignData.data.fileUrl;
          }
        })());
      }

      // Upload Banner
      if (bannerFile) {
        uploadTasks.push((async () => {
          const bannerPresignData = await getUploadUrl(bannerFile.type).unwrap();
          if (bannerPresignData.success) {
            await uploadFileToS3(bannerPresignData.data.uploadUrl, bannerFile);
            bannerUrl = bannerPresignData.data.fileUrl;
          }
        })());
      }

      await Promise.all(uploadTasks);

      const categoryData = {
        ...formData,
        parentCategory: formData.parentCategory === "None (Main Category)" ? null : formData.parentCategory,
        icon: iconUrl,
        banner: bannerUrl
      };

      setSubmitted(true);
      await createCategory(categoryData).unwrap();
    } catch (err) {
      console.error(err);
      setLocalError("Error creating category. Please try again.");
      setSubmitted(false);
    } finally {
      setLocalLoading(false);
    }
  };

  return (
    <div className="min-h-screen p-6 mt-16 lg:p-8 bg-[#F8F9FB] text-[#0F172A] font-sans pt-24 pb-32">
      
      {/* Breadcrumbs */}
      <div className="flex items-center text-[10px] font-extrabold text-gray-400 mb-4 gap-2 tracking-wider uppercase">
        <Link to="/" className="hover:text-gray-600">Admin</Link>
        <span>&gt;</span>
        <Link to="/categories" className="hover:text-gray-600">Categories</Link>
        <span>&gt;</span>
        <span className="text-[#D4AF37]">Create Category</span>
      </div>

      {/* Header */}
      <div className="mb-8">
        <h1 className="text-3xl font-extrabold text-[#0F172A] tracking-tight mb-2">
          Create Category
        </h1>
        <p className="text-[14px] font-medium text-gray-500">
          Add a new supplier category or subcategory to organize WULFARA listings.
        </p>
      </div>

      <div className="flex flex-col lg:flex-row gap-8">
        
        {/* Left Column (Form) */}
        <div className="flex-1 bg-white rounded-xl shadow-sm border border-gray-200 p-8">
          
          <div className="flex items-center gap-2 mb-8 border-b border-gray-100 pb-4">
            <Info size={20} className="text-[#D4AF37]" />
            <h2 className="text-[18px] font-extrabold text-[#0F172A]">Category Information</h2>
          </div>

          <div className="space-y-6">
            
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              {/* Category Name */}
              <div>
                <label className="block text-[13px] font-bold text-[#0F172A] mb-2">Category Name</label>
                <input 
                  type="text" 
                  name="name"
                  value={formData.name}
                  onChange={handleChange}
                  placeholder="e.g. Raw Material Suppliers"
                  className="w-full px-4 py-2.5 bg-white border border-gray-300 rounded-md text-[13px] font-medium text-[#0F172A] focus:outline-none focus:ring-2 focus:ring-[#D4AF37]/50 focus:border-[#D4AF37] placeholder-gray-400"
                />
              </div>

              {/* Slug */}
              <div>
                <label className="block text-[13px] font-bold text-[#0F172A] mb-2">Slug</label>
                <div className="flex rounded-md shadow-sm">
                  <span className="inline-flex items-center px-4 rounded-l-md border border-r-0 border-gray-300 bg-gray-50 text-gray-500 text-[13px] font-medium">
                    wulfara.com/c/
                  </span>
                  <input 
                    type="text" 
                    name="slug"
                    value={formData.slug}
                    onChange={handleChange}
                    className="flex-1 min-w-0 block w-full px-4 py-2.5 rounded-none rounded-r-md bg-white border border-gray-300 text-[13px] font-medium text-[#0F172A] focus:outline-none focus:ring-2 focus:ring-[#D4AF37]/50 focus:border-[#D4AF37]"
                  />
                </div>
              </div>
            </div>

            {/* Description */}
            <div>
              <label className="block text-[13px] font-bold text-[#0F172A] mb-2">Description</label>
              <textarea 
                name="description"
                value={formData.description}
                onChange={handleChange}
                placeholder="Provide a brief summary of the products or services offered in this category..."
                rows={4}
                className="w-full px-4 py-3 bg-white border border-gray-300 rounded-md text-[13px] font-medium text-[#0F172A] focus:outline-none focus:ring-2 focus:ring-[#D4AF37]/50 focus:border-[#D4AF37] placeholder-gray-400 resize-none"
              ></textarea>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              {/* Icon Upload */}
              <div>
                <label className="block text-[13px] font-bold text-[#0F172A] mb-2">Icon</label>
                <div className="flex items-center gap-4">
                  <div className="w-14 h-14 rounded-lg border border-gray-200 bg-gray-50 flex items-center justify-center text-gray-400 overflow-hidden">
                    {iconPreview ? (
                      <img src={iconPreview} alt="Icon Preview" className="w-full h-full object-contain p-2" />
                    ) : (
                      <ImageIcon size={20} />
                    )}
                  </div>
                  <div>
                    <label className="text-[13px] font-bold text-[#D4AF37] hover:underline cursor-pointer">
                      Upload SVG or PNG
                      <input type="file" accept="image/svg+xml,image/png" onChange={handleIconUpload} className="hidden" />
                    </label>
                    <p className="text-[11px] font-medium text-gray-400 mt-1">Max size 500kb</p>
                  </div>
                </div>
              </div>

              {/* Display Order */}
              <div>
                <label className="block text-[13px] font-bold text-[#0F172A] mb-2">Display Order</label>
                <input 
                  type="number" 
                  name="displayOrder"
                  value={formData.displayOrder}
                  onChange={handleChange}
                  className="w-full px-4 py-2.5 bg-white border border-gray-300 rounded-md text-[13px] font-medium text-[#0F172A] focus:outline-none focus:ring-2 focus:ring-[#D4AF37]/50 focus:border-[#D4AF37]"
                />
              </div>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              {/* Parent Category */}
              <div>
                <label className="block text-[13px] font-bold text-[#0F172A] mb-2">Parent Category</label>
                <select 
                  name="parentCategory"
                  value={formData.parentCategory}
                  onChange={handleChange}
                  className="w-full appearance-none px-4 py-2.5 bg-white border border-gray-300 rounded-md text-[13px] font-medium text-[#0F172A] focus:outline-none focus:ring-2 focus:ring-[#D4AF37]/50 focus:border-[#D4AF37]"
                >
                  <option value="None (Main Category)">None (Main Category)</option>
                  {categories.map(cat => (
                    <option key={cat._id} value={cat._id}>{cat.name}</option>
                  ))}
                </select>
              </div>

              {/* Status */}
              <div>
                <label className="block text-[13px] font-bold text-[#0F172A] mb-2">Status</label>
                <div className="flex bg-gray-100 p-1 rounded-md">
                  {["Active", "Hidden", "Draft"].map(status => (
                    <button
                      key={status}
                      type="button"
                      onClick={() => setFormData(prev => ({ ...prev, status }))}
                      className={`flex-1 py-1.5 text-[12px] font-bold rounded ${
                        formData.status === status 
                          ? "bg-white text-[#D97706] shadow-sm" 
                          : "text-gray-500 hover:text-gray-700"
                      }`}
                    >
                      {status}
                    </button>
                  ))}
                </div>
              </div>
            </div>

            {/* Banner Image */}
            <div>
              <label className="block text-[13px] font-bold text-[#0F172A] mb-2">Banner Image</label>
              <label className="border-2 border-dashed border-gray-300 rounded-xl p-8 flex flex-col items-center justify-center text-center hover:bg-gray-50/50 transition-colors cursor-pointer relative overflow-hidden group block">
                <input type="file" accept="image/*" onChange={handleBannerUpload} className="hidden" />
                <img src={bannerPreview} alt="Banner Preview" className="absolute inset-0 w-full h-full object-cover opacity-20 group-hover:opacity-10 transition-opacity" />
                <div className="relative z-10 flex flex-col items-center">
                  <div className="w-10 h-10 rounded-full bg-[#FEF3C7] text-[#D97706] flex items-center justify-center mb-4 shadow">
                    <CloudUpload size={20} />
                  </div>
                  <h4 className="text-[14px] font-bold text-[#0F172A] mb-1">Click to upload or drag and drop</h4>
                  <p className="text-[12px] font-medium text-gray-400">SVG, PNG, JPG or WEBP (max. 1920x1080px)</p>
                </div>
              </label>
            </div>

          </div>

          {localError && (
            <div className="mt-6 p-4 bg-red-50 text-red-600 rounded-lg text-[13px] font-bold">
              {localError}
            </div>
          )}

        </div>

        {/* Right Column (Preview & Admin Summary) */}
        <div className="w-full lg:w-[320px] xl:w-[360px] flex-shrink-0 space-y-6">
          
          {/* Public Preview */}
          <div className="bg-white rounded-xl shadow-sm border border-gray-200 overflow-hidden">
            <div className="px-4 py-3 border-b border-gray-100 flex items-center gap-2 bg-gray-50/50">
              <Eye size={14} className="text-gray-400" />
              <span className="text-[10px] font-extrabold text-gray-400 uppercase tracking-wider">Public Preview</span>
            </div>
            
            <div className="p-4 bg-gray-50">
              <div className="bg-white rounded-xl shadow-sm border border-gray-200 overflow-hidden">
                <div className="h-32 bg-slate-800 relative">
                  <img src={bannerPreview} alt="Banner Preview" className="w-full h-full object-cover opacity-50" />
                </div>
                <div className="p-5">
                  <div className="flex justify-between items-start mb-3">
                    <h3 className="text-[16px] font-extrabold text-[#0F172A] leading-tight">
                      {formData.name || "Category Name"}
                    </h3>
                    <div className="flex flex-col items-center bg-gray-50 border border-gray-100 rounded-lg px-2 py-1">
                      <span className="text-[10px] font-bold text-[#D4AF37]">148</span>
                      <span className="text-[8px] font-bold text-gray-400 uppercase">Suppliers</span>
                    </div>
                  </div>
                  <p className="text-[12px] font-medium text-gray-500 line-clamp-2 mb-6">
                    {formData.description || "High-performance industrial materials ranging from..."}
                  </p>
                  <button className="w-full py-2 bg-[#D4AF37] text-[#0F172A] rounded-md text-[13px] font-bold hover:bg-[#C2982B] transition-colors flex items-center justify-center gap-1.5">
                    View Suppliers <span>&rarr;</span>
                  </button>
                </div>
              </div>
            </div>
          </div>

          {/* Admin Summary */}
          <div className="bg-white rounded-xl shadow-sm border border-gray-200 p-6">
            <h3 className="text-[10px] font-extrabold text-gray-400 uppercase tracking-wider border-b border-gray-100 pb-3 mb-4">
              Admin Summary
            </h3>
            
            <div className="space-y-4">
              <div className="flex items-center justify-between">
                <span className="text-[12px] font-medium text-gray-500">Status</span>
                <span className={`text-[13px] font-bold flex items-center gap-1.5 ${
                  formData.status === 'Active' ? 'text-[#10B981]' : 
                  formData.status === 'Hidden' ? 'text-gray-400' : 'text-[#D97706]'
                }`}>
                  <div className={`w-1.5 h-1.5 rounded-full ${
                    formData.status === 'Active' ? 'bg-[#10B981]' : 
                    formData.status === 'Hidden' ? 'bg-gray-400' : 'bg-[#D97706]'
                  }`}></div>
                  {formData.status === 'Active' ? 'Live' : formData.status}
                </span>
              </div>
              <div className="flex items-center justify-between">
                <span className="text-[12px] font-medium text-gray-500">Public Path</span>
                <span className="px-2 py-1 bg-gray-50 border border-gray-100 text-gray-600 rounded text-[11px] font-mono max-w-[150px] truncate">
                  /c/{formData.slug || "category"}
                </span>
              </div>
              <div className="flex items-center justify-between">
                <span className="text-[12px] font-medium text-gray-500">Search Index</span>
                <span className={`text-[12px] font-bold ${formData.status === 'Active' ? 'text-[#D97706]' : 'text-gray-400'}`}>
                  {formData.status === 'Active' ? 'Prioritized' : 'Excluded'}
                </span>
              </div>
            </div>
          </div>

        </div>

      </div>

      {/* Bottom Sticky Actions */}
      <div className="fixed bottom-0 left-0 right-0 lg:left-64 bg-white border-t border-gray-200 p-4 flex items-center justify-center sm:justify-end gap-4 z-40 px-6 lg:px-8">
        <button 
          onClick={() => navigate("/categories")}
          className="px-6 py-2.5 text-[13px] font-bold text-gray-600 hover:text-gray-900 transition-colors"
        >
          Cancel
        </button>
        <button 
          onClick={handleSubmit}
          disabled={isCreating || localLoading}
          className="px-8 py-2.5 bg-[#D4AF37] border border-[#D4AF37] rounded-md text-[13px] font-bold text-[#0F172A] hover:bg-[#C2982B] transition-colors shadow-sm disabled:opacity-70"
        >
          {isCreating || localLoading ? "Saving..." : "Save Category"}
        </button>
      </div>

    </div>
  );
}

import React, { useState } from 'react';
import { 
  FileText, 
  ImageIcon, 
  Edit3, 
  AlertTriangle, 
  Home, 
  HelpCircle, 
  Book, 
  Gavel,
  Plus,
  RefreshCw,
  CheckCircle2,
  Clock,
  AlertCircle,
  UploadCloud
} from 'lucide-react';
import StatCard from '../../../Components/admin-components/content/StatCard';
import SectionCard from '../../../Components/admin-components/content/SectionCard';
import { Link } from 'react-router-dom';
import { Modal, Form, Input, message, Button, Collapse } from 'antd';
import { 
  useGetPagesQuery, 
  useCreatePageMutation, 
  useUpdatePageMutation,
  useGetBannersQuery,
  useCreateBannerMutation,
  useUpdateBannerMutation,
  useDeleteBannerMutation
} from '../../../redux/features/cms/cmsApi';

const ContentManagement = () => {
  const { data: pagesResponse } = useGetPagesQuery();
  const [createPage] = useCreatePageMutation();
  const [updatePage] = useUpdatePageMutation();

  const faqPage = pagesResponse?.data?.find(p => p.slug === 'faq');
  const policyPage = pagesResponse?.data?.find(p => p.slug === 'policies');
  const helpCenterPage = pagesResponse?.data?.find(p => p.slug === 'help-center');
  
  const [isFaqModalVisible, setIsFaqModalVisible] = useState(false);
  const [isPolicyModalVisible, setIsPolicyModalVisible] = useState(false);
  const [isHelpCenterModalVisible, setIsHelpCenterModalVisible] = useState(false);
  
  const [form] = Form.useForm();
  const [faqForm] = Form.useForm();
  const [policyForm] = Form.useForm();
  const [helpCenterForm] = Form.useForm();
  
  // Banners
  const { data: bannersResponse } = useGetBannersQuery();
  const [createBanner] = useCreateBannerMutation();
  const [updateBanner] = useUpdateBannerMutation();
  const [deleteBanner] = useDeleteBannerMutation();
  const [isBannerModalVisible, setIsBannerModalVisible] = useState(false);
  const [bannerForm] = Form.useForm();

  const showFaqModal = () => {
    if (faqPage && faqPage.htmlContent) {
      try {
        const parsed = JSON.parse(faqPage.htmlContent);
        faqForm.setFieldsValue({ faqs: parsed });
      } catch (e) {
        faqForm.setFieldsValue({ faqs: [] });
      }
    } else {
      faqForm.setFieldsValue({ faqs: [] });
    }
    setIsFaqModalVisible(true);
  };

  const handleFaqOk = async () => {
    try {
      const values = await faqForm.validateFields();
      const payload = {
        title: 'FAQ',
        slug: 'faq',
        htmlContent: JSON.stringify(values.faqs || [])
      };
      
      if (faqPage) {
        await updatePage({ id: faqPage._id, ...payload }).unwrap();
      } else {
        await createPage(payload).unwrap();
      }
      message.success('FAQs updated successfully!');
      setIsFaqModalVisible(false);
    } catch (err) {
      console.error(err);
      if (err.errorFields) return; // Validation error
      message.error('Failed to update FAQs');
    }
  };

  const showPolicyModal = () => {
    if (policyPage && policyPage.htmlContent) {
      try {
        const parsed = JSON.parse(policyPage.htmlContent);
        policyForm.setFieldsValue(parsed);
      } catch (e) {
        policyForm.resetFields();
      }
    } else {
      policyForm.resetFields();
    }
    setIsPolicyModalVisible(true);
  };

  const handlePolicyOk = async () => {
    try {
      const values = await policyForm.validateFields();
      const payload = {
        title: 'Policies',
        slug: 'policies',
        htmlContent: JSON.stringify(values)
      };
      
      if (policyPage) {
        await updatePage({ id: policyPage._id, ...payload }).unwrap();
      } else {
        await createPage(payload).unwrap();
      }
      message.success('Policies updated successfully!');
      setIsPolicyModalVisible(false);
    } catch (err) {
      console.error(err);
      if (err.errorFields) return;
      message.error('Failed to update Policies');
    }
  };

  const showHelpCenterModal = () => {
    if (helpCenterPage && helpCenterPage.htmlContent) {
      try {
        const parsed = JSON.parse(helpCenterPage.htmlContent);
        helpCenterForm.setFieldsValue({ articles: parsed });
      } catch (e) {
        helpCenterForm.setFieldsValue({ articles: [] });
      }
    } else {
      helpCenterForm.setFieldsValue({ articles: [] });
    }
    setIsHelpCenterModalVisible(true);
  };

  const handleHelpCenterOk = async () => {
    try {
      const values = await helpCenterForm.validateFields();
      const payload = {
        title: 'Help Center',
        slug: 'help-center',
        htmlContent: JSON.stringify(values.articles || [])
      };
      
      if (helpCenterPage) {
        await updatePage({ id: helpCenterPage._id, ...payload }).unwrap();
      } else {
        await createPage(payload).unwrap();
      }
      message.success('Help Center Articles updated successfully!');
      setIsHelpCenterModalVisible(false);
    } catch (err) {
      console.error(err);
      if (err.errorFields) return; // Validation error
      message.error('Failed to update Help Center Articles');
    }
  };

  const showBannerModal = () => {
    bannerForm.resetFields();
    setIsBannerModalVisible(true);
  };

  const handleBannerSubmit = async (values) => {
    try {
      await createBanner({
        title: values.title,
        imageUrl: values.imageUrl,
        linkTarget: values.linkTarget,
        isActive: values.isActive ?? true
      }).unwrap();
      message.success('Banner added successfully!');
      bannerForm.resetFields();
    } catch (err) {
      console.error(err);
      message.error('Failed to add banner');
    }
  };

  const handleDeleteBanner = async (id) => {
    try {
      await deleteBanner(id).unwrap();
      message.success('Banner deleted');
    } catch (err) {
      message.error('Failed to delete banner');
    }
  };

  return (
    <div className="p-8 max-w-7xl mx-auto bg-[#FAFAFA] min-h-screen mt-16">
      {/* Header */}
      <div className="flex justify-between items-start mb-8">
        <div>
          <h1 className="text-3xl font-bold text-[#1a1f36] mb-2">Content Management</h1>
          <p className="text-[#697386]">Manage homepage content, FAQs, policies, and static pages.</p>
        </div>
      </div>

      {/* Top Stats */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4 mb-8">
        <StatCard
          title="Published Pages"
          value="12"
          icon={<FileText size={24} />}
          badgeColor="bg-yellow-50"
          badgeTextColor="text-yellow-600"
        />
        <StatCard
          title="Draft Updates"
          value="3"
          icon={<Edit3 size={24} />}
          badgeColor="bg-orange-50"
          badgeTextColor="text-orange-600"
        />
        <StatCard
          title="SEO Issues"
          value="2"
          icon={<AlertTriangle size={24} />}
          badgeColor="bg-red-50"
          badgeTextColor="text-red-600"
          borderColor="border-red-200 bg-red-50/30"
        />
      </div>

      {/* Main Grid */}
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">

        {/* Left Column - Content Sections (Spans 2 columns on large screens) */}
        <div className="lg:col-span-2 grid grid-cols-1 md:grid-cols-2 gap-6">
          <SectionCard
            title="Homepage Content"
            description="Control sections, feature highlights, and body copy on the main landing page."
            badgeText="Published"
            badgeType="success"
            icon={<Home size={20} />}
            editLink="/content/homepage"
          />
          <SectionCard
            title="FAQ"
            description="Common questions and answers structured for easy user consumption and help desk deflection."
            badgeText="Published"
            badgeType="success"
            icon={<HelpCircle size={20} />}
            onEdit={showFaqModal}
          />
          <SectionCard
            title="Banners"
            description="Manage promotional banners and announcements shown across the platform."
            badgeText="Active"
            badgeType="success"
            icon={<ImageIcon size={20} />}
            onEdit={showBannerModal}
          />
          <SectionCard
            title="Help Center Articles"
            description="Comprehensive guides, tutorials, and troubleshooting articles for complex platform features."
            badgeText="Drafts Available"
            badgeType="warning"
            icon={<Book size={20} />}
            onEdit={showHelpCenterModal}
          />
          <SectionCard
            title="Policies"
            description="Legal terms, privacy policy, and cookie consent documentation management."
            badgeText="Published"
            badgeType="success"
            icon={<Gavel size={20} />}
            onEdit={showPolicyModal}
          />
        </div>

        {/* Right Column - Sidebar Widgets */}
        <div className="space-y-6">
          {/* Content Health Widget */}
          <div className="bg-white rounded-xl border border-gray-200 p-6">
            <h3 className="text-lg font-bold text-gray-900 mb-6 flex items-center gap-2">
              <RefreshCw size={20} className="text-yellow-600" />
              Content Health
            </h3>

            <div className="mb-6">
              <div className="flex justify-between text-xs font-semibold text-gray-500 uppercase tracking-wider mb-2">
                <span>System Sync</span>
                <span className="text-yellow-600">94%</span>
              </div>
              <div className="w-full bg-gray-200 rounded-full h-1.5">
                <div className="bg-green-500 h-1.5 rounded-full" style={{ width: '94%' }}></div>
              </div>
            </div>

            <div className="space-y-4">
              <div className="flex items-start gap-3 border-l-2 border-green-500 pl-3">
                <CheckCircle2 size={16} className="text-green-500 mt-0.5" />
                <div>
                  <p className="text-sm font-semibold text-gray-900">Policies Updated</p>
                  <p className="text-xs text-gray-500">Terms of Service sync 2h ago</p>
                </div>
              </div>
              <div className="flex items-start gap-3 border-l-2 border-orange-500 pl-3">
                <Clock size={16} className="text-orange-500 mt-0.5" />
                <div>
                  <p className="text-sm font-semibold text-gray-900">Pending Drafts</p>
                  <p className="text-xs text-gray-500">3 items awaiting approval</p>
                </div>
              </div>
              <div className="flex items-start gap-3 border-l-2 border-red-500 pl-3">
                <AlertCircle size={16} className="text-red-500 mt-0.5" />
                <div>
                  <p className="text-sm font-semibold text-gray-900">Broken Links</p>
                  <p className="text-xs text-gray-500">2 links in Help Center</p>
                </div>
              </div>
            </div>
          </div>

          {/* Audit Logs Widget */}
          <div className="bg-white rounded-xl border border-gray-200 p-6">
            <h3 className="text-xs font-semibold text-gray-500 uppercase tracking-wider mb-4">
              Audit Logs
            </h3>
            <div className="space-y-4">
              <div className="flex items-center justify-between text-sm">
                <div className="flex items-center gap-2">
                  <div className="w-1.5 h-1.5 rounded-full bg-yellow-500"></div>
                  <span className="text-gray-600">Admin_01 edited "Home"</span>
                </div>
                <span className="text-gray-400 text-xs">12m</span>
              </div>
              <div className="flex items-center justify-between text-sm">
                <div className="flex items-center gap-2">
                  <div className="w-1.5 h-1.5 rounded-full bg-yellow-500"></div>
                  <span className="text-gray-600">SEO Bot scanned site</span>
                </div>
                <span className="text-gray-400 text-xs">1h</span>
              </div>
              <div className="flex items-center justify-between text-sm">
                <div className="flex items-center gap-2">
                  <div className="w-1.5 h-1.5 rounded-full bg-green-500"></div>
                  <span className="text-gray-600">New Banner "Summer24"</span>
                </div>
                <span className="text-gray-400 text-xs">4h</span>
              </div>
            </div>
          </div>

        </div>
      </div>

      {/* FAQ Modal */}
      <Modal 
        title="Manage Frequently Asked Questions" 
        open={isFaqModalVisible} 
        onOk={handleFaqOk} 
        onCancel={() => setIsFaqModalVisible(false)}
        okText="Publish FAQs"
        okButtonProps={{ style: { backgroundColor: '#d9a05b', borderColor: '#d9a05b' } }}
        width={800}
      >
        <Form form={faqForm} layout="vertical" className="mt-4 max-h-[60vh] overflow-y-auto px-2">
          <Form.List name="faqs">
            {(fields, { add, remove }) => (
              <>
                {fields.map(({ key, name, ...restField }) => (
                  <div key={key} className="border border-gray-200 p-4 rounded-lg mb-4 bg-gray-50 relative">
                    <Button 
                      type="text" 
                      danger 
                      onClick={() => remove(name)} 
                      className="absolute top-2 right-2"
                    >
                      Delete
                    </Button>
                    <Form.Item
                      {...restField}
                      name={[name, 'question']}
                      label="Question"
                      rules={[{ required: true, message: 'Missing question' }]}
                    >
                      <Input placeholder="e.g. How secure is the platform?" />
                    </Form.Item>
                    <Form.Item
                      {...restField}
                      name={[name, 'topic']}
                      label="Topic"
                      rules={[{ required: true, message: 'Missing topic' }]}
                    >
                      <Input placeholder="e.g. General Questions, Suppliers, RFQ Protocols" />
                    </Form.Item>
                    <Form.Item
                      {...restField}
                      name={[name, 'answer']}
                      label="Answer"
                      rules={[{ required: true, message: 'Missing answer' }]}
                    >
                      <Input.TextArea rows={3} placeholder="e.g. We use industry standard encryption..." />
                    </Form.Item>
                  </div>
                ))}
                <Form.Item>
                  <Button type="dashed" onClick={() => add()} block icon={<Plus size={16} className="inline mr-2" />}>
                    Add FAQ Entry
                  </Button>
                </Form.Item>
              </>
            )}
          </Form.List>
        </Form>
      </Modal>

      {/* Help Center Modal */}
      <Modal 
        title="Manage Help Center Articles" 
        open={isHelpCenterModalVisible} 
        onOk={handleHelpCenterOk} 
        onCancel={() => setIsHelpCenterModalVisible(false)}
        okText="Publish Articles"
        okButtonProps={{ style: { backgroundColor: '#d9a05b', borderColor: '#d9a05b' } }}
        width={800}
      >
        <Form form={helpCenterForm} layout="vertical" className="mt-4 max-h-[60vh] overflow-y-auto px-2">
          <Form.List name="articles">
            {(fields, { add, remove }) => (
              <>
                {fields.map(({ key, name, ...restField }) => (
                  <div key={key} className="border border-gray-200 p-4 rounded-lg mb-4 bg-gray-50 relative">
                    <Button 
                      type="text" 
                      danger 
                      onClick={() => remove(name)} 
                      className="absolute top-2 right-2"
                    >
                      Delete
                    </Button>
                    <Form.Item
                      {...restField}
                      name={[name, 'title']}
                      label="Article Title"
                      rules={[{ required: true, message: 'Missing title' }]}
                    >
                      <Input placeholder="e.g. How do I reset my password?" />
                    </Form.Item>
                    <Form.Item
                      {...restField}
                      name={[name, 'content']}
                      label="Article Content"
                      rules={[{ required: true, message: 'Missing content' }]}
                    >
                      <Input.TextArea rows={4} placeholder="HTML or text content..." />
                    </Form.Item>
                  </div>
                ))}
                <Form.Item>
                  <Button type="dashed" onClick={() => add()} block icon={<Plus size={16} className="inline mr-2" />}>
                    Add Help Center Article
                  </Button>
                </Form.Item>
              </>
            )}
          </Form.List>
        </Form>
      </Modal>

      {/* Policies Modal */}
      <Modal 
        title="Manage Legal Policies" 
        open={isPolicyModalVisible} 
        onOk={handlePolicyOk} 
        onCancel={() => setIsPolicyModalVisible(false)}
        okText="Publish Policies"
        okButtonProps={{ style: { backgroundColor: '#d9a05b', borderColor: '#d9a05b' } }}
        width={900}
      >
        <Form form={policyForm} layout="vertical" className="mt-4 max-h-[65vh] overflow-y-auto px-2">
          <Collapse accordion defaultActiveKey={['terms-of-service']}>
            <Collapse.Panel header={<span className="font-semibold text-gray-700">Terms of Service</span>} key="terms-of-service">
              <Form.Item name="termsOfService" rules={[{ required: true }]}>
                <Input.TextArea rows={6} placeholder="Enter HTML or text..." />
              </Form.Item>
            </Collapse.Panel>

            <Collapse.Panel header={<span className="font-semibold text-gray-700">Privacy Policy</span>} key="privacy-policy">
              <Form.Item name="privacyPolicy" rules={[{ required: true }]}>
                <Input.TextArea rows={6} placeholder="Enter HTML or text..." />
              </Form.Item>
            </Collapse.Panel>

            <Collapse.Panel header={<span className="font-semibold text-gray-700">Supplier Listing Policy</span>} key="supplier-listing-policy">
              <Form.Item name="supplierListingPolicy" rules={[{ required: true }]}>
                <Input.TextArea rows={6} placeholder="Enter HTML or text..." />
              </Form.Item>
            </Collapse.Panel>

            <Collapse.Panel header={<span className="font-semibold text-gray-700">RFQ Policy</span>} key="rfq-policy">
              <Form.Item name="rfqPolicy" rules={[{ required: true }]}>
                <Input.TextArea rows={6} placeholder="Enter HTML or text..." />
              </Form.Item>
            </Collapse.Panel>

            <Collapse.Panel header={<span className="font-semibold text-gray-700">Payment & Subscription Policy</span>} key="payment-subscription-policy">
              <Form.Item name="paymentSubscriptionPolicy" rules={[{ required: true }]}>
                <Input.TextArea rows={6} placeholder="Enter HTML or text..." />
              </Form.Item>
            </Collapse.Panel>

            <Collapse.Panel header={<span className="font-semibold text-gray-700">Cancellation Policy</span>} key="cancellation-policy">
              <Form.Item name="cancellationPolicy" rules={[{ required: true }]}>
                <Input.TextArea rows={6} placeholder="Enter HTML or text..." />
              </Form.Item>
            </Collapse.Panel>
          </Collapse>
        </Form>
      </Modal>

      {/* Banners Modal */}
      <Modal 
        title="Manage Banners" 
        open={isBannerModalVisible} 
        onCancel={() => setIsBannerModalVisible(false)}
        footer={null}
        width={800}
      >
        <div className="mt-4 max-h-[60vh] overflow-y-auto px-2">
          {/* List existing banners */}
          <div className="mb-8">
            <h3 className="text-sm font-bold text-gray-700 uppercase tracking-wider mb-4 border-b pb-2">Active Banners</h3>
            {bannersResponse?.data?.length === 0 ? (
              <p className="text-gray-500 text-sm">No active banners found.</p>
            ) : (
              <div className="space-y-4">
                {bannersResponse?.data?.map(banner => (
                  <div key={banner._id} className="flex items-center gap-4 bg-gray-50 p-4 rounded-lg border border-gray-200">
                    <img src={banner.imageUrl} alt={banner.title} className="w-24 h-16 object-cover rounded shadow-sm border border-gray-200" />
                    <div className="flex-1">
                      <h4 className="font-bold text-sm text-gray-900">{banner.title}</h4>
                      <p className="text-xs text-gray-500 font-mono mt-1">{banner.linkTarget || 'No link'}</p>
                    </div>
                    <Button type="text" danger onClick={() => handleDeleteBanner(banner._id)}>Delete</Button>
                  </div>
                ))}
              </div>
            )}
          </div>

          <div className="border-t pt-6">
            <h3 className="text-sm font-bold text-gray-700 uppercase tracking-wider mb-4">Add New Banner</h3>
            <Form form={bannerForm} layout="vertical" onFinish={handleBannerSubmit}>
              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                <Form.Item name="title" label="Banner Title" rules={[{ required: true, message: 'Please enter title' }]}>
                  <Input placeholder="e.g. Summer Sale" />
                </Form.Item>
                <Form.Item name="linkTarget" label="Link Target (Optional)">
                  <Input placeholder="e.g. /suppliers/featured" />
                </Form.Item>
              </div>
              <Form.Item name="imageUrl" label="Image URL" rules={[{ required: true, message: 'Please enter image URL' }]}>
                <Input placeholder="https://example.com/image.jpg" />
              </Form.Item>
              <Form.Item>
                <Button type="primary" htmlType="submit" style={{ backgroundColor: '#d9a05b', borderColor: '#d9a05b' }}>
                  Create Banner
                </Button>
              </Form.Item>
            </Form>
          </div>
        </div>
      </Modal>
    </div>
  );
};

