import React, { useState, useEffect, useMemo } from "react";
import { Link } from "react-router-dom";
import { useGetListingsQuery, useReviewListingMutation, useFeatureListingMutation } from "../../../redux/features/listings/listingsApi";
import { ChevronRight, Filter, Download, Search, Hourglass, CheckCircle2, XCircle, Star, TrendingUp } from "lucide-react";
import ListingTable from "../../../Components/admin-components/listings/ListingTable";

export default function ListingReview() {
  const { data: listingsResponse, isLoading } = useGetListingsQuery();
  const [reviewListing] = useReviewListingMutation();
  const [featureListing] = useFeatureListingMutation();
  
  const listings = listingsResponse?.data || [];

  const [searchQuery, setSearchQuery] = useState("");
  const [selectedIds, setSelectedIds] = useState([]);

  // Calculate profile completeness for quality score
  const calculateQualityScore = (listing) => {
    let score = 0;
    if (listing.companyName) score += 20;
    if (listing.description) score += 20;
    if (listing.contactEmail) score += 20;
    if (listing.logo && listing.logo !== 'no-logo.jpg') score += 20;
    if (listing.categories && listing.categories.length > 0) score += 20;
    return score;
  };

  const mappedListings = useMemo(() => {
    return listings.map(l => ({
      id: l._id,
      companyName: l.companyName,
      category: l.categories && l.categories.length > 0 ? l.categories[0].name : "Uncategorized",
      submitted: new Date(l.createdAt).toLocaleDateString('en-US', { month: 'short', day: '2-digit', year: 'numeric' }),
      supplier: l.user ? (l.user.name || "Unknown") : "Unknown", // user is populated if possible, otherwise we might need to rely on companyName
      plan: l.subscriptionPlan === 'premium' ? 'Pro' : 'Basic',
      status: l.listingStatus || 'Pending',
      quality: calculateQualityScore(l),
      isFeatured: l.isFeatured || false
    }));
  }, [listings]);

  const filteredListings = mappedListings.filter(l =>
    l.companyName?.toLowerCase().includes(searchQuery.toLowerCase()) ||
    l.supplier?.toLowerCase().includes(searchQuery.toLowerCase())
  );

  const handleApprove = async (id) => {
    try {
      await reviewListing({ id, listingStatus: 'Approved' }).unwrap();
    } catch (err) {
      console.error(err);
      alert("Error approving listing");
    }
  };

  const handleReject = async (id) => {
    try {
      await reviewListing({ id, listingStatus: 'Rejected' }).unwrap();
    } catch (err) {
      console.error(err);
      alert("Error rejecting listing");
    }
  };

  const handleFeature = async (id, isFeatured) => {
    try {
      await featureListing({ id, isFeatured }).unwrap();
    } catch (err) {
      console.error(err);
      alert("Error updating featured status");
    }
  };

  const handleSelect = (id) => {
    setSelectedIds(prev => prev.includes(id) ? prev.filter(i => i !== id) : [...prev, id]);
  };

  const handleSelectAll = (e) => {
    if (e.target.checked) {
      setSelectedIds(filteredListings.map(l => l.id));
    } else {
      setSelectedIds([]);
    }
  };

  const pendingCount = mappedListings.filter(l => l.status === 'Pending').length;
  const approvedCount = mappedListings.filter(l => l.status === 'Approved').length;
  const rejectedCount = mappedListings.filter(l => l.status === 'Rejected').length;
  const featuredCount = mappedListings.filter(l => l.isFeatured).length;

  return (
    <div className="min-h-screen p-6 mt-16 lg:p-8 bg-[#F8F9FB] text-[#0F172A] font-sans pt-24">


      {/* Header */}
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center mb-8 gap-4">
        <h1 className="text-3xl font-extrabold text-[#0F172A] tracking-tight">
          Listing Review
        </h1>
        <div className="flex items-center gap-3">
          <button className="flex items-center gap-2 px-4 py-2 bg-white border border-gray-200 rounded-md text-[13px] font-bold text-gray-700 hover:bg-gray-50 transition-colors shadow-sm">
            <Filter size={16} />
            Filter
          </button>
          <button className="flex items-center gap-2 px-4 py-2 bg-[#D4AF37] border border-[#D4AF37] rounded-md text-[13px] font-bold text-[#0F172A] hover:bg-[#C2982B] transition-colors shadow-sm">
            <Download size={16} />
            Export
          </button>
        </div>
      </div>

      {/* Summary Cards */}
      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-6 mb-8">

        {/* Pending Card */}
        <div className="bg-white rounded-xl shadow-sm border border-gray-200 p-6 relative overflow-hidden group hover:shadow-md transition-shadow cursor-pointer">
          <div className="flex justify-between items-start mb-4">
            <h3 className="text-[14px] font-bold text-gray-500">Pending Review</h3>
            <Hourglass size={20} className="text-[#D97706]" />
          </div>
          <div className="text-4xl font-extrabold text-[#0F172A] mb-3">{pendingCount}</div>
          <div className="flex items-center gap-1.5 text-[12px] font-bold text-[#10B981]">
            <TrendingUp size={14} />
            +3 today
          </div>
        </div>

        {/* Approved Card */}
        <div className="bg-white rounded-xl shadow-sm border border-gray-200 p-6 relative overflow-hidden group hover:shadow-md transition-shadow cursor-pointer">
          <div className="flex justify-between items-start mb-4">
            <h3 className="text-[14px] font-bold text-gray-500">Approved</h3>
            <CheckCircle2 size={20} className="text-[#10B981]" />
          </div>
          <div className="text-4xl font-extrabold text-[#0F172A] mb-3">{approvedCount}</div>
          <div className="text-[12px] font-medium text-gray-400">
            Last 7 days
          </div>
        </div>

        {/* Rejected Card */}
        <div className="bg-white rounded-xl shadow-sm border border-gray-200 p-6 relative overflow-hidden group hover:shadow-md transition-shadow cursor-pointer">
          <div className="flex justify-between items-start mb-4">
            <h3 className="text-[14px] font-bold text-gray-500">Rejected</h3>
            <XCircle size={20} className="text-[#EF4444]" />
          </div>
          <div className="text-4xl font-extrabold text-[#0F172A] mb-3">{rejectedCount}</div>
          <div className="text-[12px] font-medium text-gray-400">
            Last 7 days
          </div>
        </div>

        {/* Featured Card */}
        <div className="bg-white rounded-xl shadow-sm border border-gray-200 p-6 relative overflow-hidden group hover:shadow-md transition-shadow cursor-pointer">
          <div className="flex justify-between items-start mb-4">
            <h3 className="text-[14px] font-bold text-gray-500">Featured</h3>
            <Star size={20} className="text-[#F59E0B]" />
          </div>
          <div className="text-4xl font-extrabold text-[#0F172A] mb-3">{featuredCount}</div>
          <div className="text-[12px] font-medium text-gray-400">
            Active promotions
          </div>
        </div>

      </div>

      {/* Main Table Area */}
      <div className="bg-white border border-gray-200 rounded-xl shadow-sm overflow-hidden">

        {/* Table Header */}
        <div className="p-4 border-b border-gray-100 flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4">
          <h2 className="text-[18px] font-extrabold text-[#0F172A]">
            Pending Listings Directory
          </h2>
          <div className="relative">
            <Search className="absolute left-3 top-2.5 text-gray-400" size={16} />
            <input
              type="text"
              placeholder="Search table..."
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              className="pl-9 pr-4 py-2 bg-[#F8F9FB] border border-gray-200 rounded-md text-[13px] font-medium text-[#0F172A] w-[240px] focus:outline-none focus:ring-2 focus:ring-[#D4AF37]/50 focus:border-[#D4AF37] transition-all"
            />
          </div>
        </div>

        {/* Table Component */}
        <ListingTable
          listings={filteredListings}
          selectedIds={selectedIds}
          onSelect={handleSelect}
          onSelectAll={handleSelectAll}
          onApprove={handleApprove}
          onReject={handleReject}
          onFeature={handleFeature}
        />

      </div>
    </div>
  );
}

import React, { useState } from 'react';
import { 
  Banknote, RefreshCw, CreditCard, Tag, AlertCircle, Download, CreditCard as VisaIcon 
} from 'lucide-react';
import { Select, Table, Tag as AntTag, message } from 'antd';
import { 
  BarChart, Bar, XAxis, Tooltip, ResponsiveContainer, 
  PieChart, Pie, Cell 
} from 'recharts';
import { useGetAllPaymentsQuery } from '../../../redux/features/subscriptions/subscriptionsApi';
import { useGetDashboardStatsQuery } from '../../../redux/features/reports/reportsApi';

const RevenueReports = () => {
  const [timeframe, setTimeframe] = useState('Last 12 Months');
  const [isExporting, setIsExporting] = useState(false);
  const { data: paymentsResponse, isLoading: isPaymentsLoading } = useGetAllPaymentsQuery();
  const { data: statsResponse, isLoading: isStatsLoading } = useGetDashboardStatsQuery();
  const payments = paymentsResponse?.data || [];
  const chartData = statsResponse?.data?.chartData || [];

  const totalRevenue = payments.reduce((acc, curr) => acc + (curr.amount || 0), 0);
  const formattedRevenue = totalRevenue >= 1000 ? (totalRevenue / 1000).toFixed(2) + 'K' : totalRevenue.toString();
  const paidSuppliersCount = new Set(payments.map(p => p.supplier?._id).filter(Boolean)).size;

  // Stat Card Data
  const stats = [
    { title: 'TOTAL REVENUE', value: `$${formattedRevenue}`, icon: <Banknote size={18} />, color: 'text-gray-700', sub: null },
    { title: 'MRR', value: `$${(totalRevenue / 12).toFixed(2)}`, icon: <RefreshCw size={18} />, color: 'text-gray-700', sub: null },
    { title: 'PAYMENTS', value: payments.length.toString(), icon: <CreditCard size={18} />, color: 'text-gray-700', sub: 'Total count' },
    { title: 'PAID SUPPLIERS', value: paidSuppliersCount.toString(), icon: <Tag size={18} />, color: 'text-gray-700', sub: null },
  ];

  // Bar Chart Data (Revenue by Month) mapped from dynamic chartData
  const defaultBarData = chartData.length > 0 ? chartData.map((d, index) => {
    // Dynamic fill colors to match previous design aesthetics based on recent months
    let fill = '#f1f5f9';
    if (index >= 9) fill = '#4ade80'; // Last 3 months green
    else if (index >= 6) fill = '#cbd5e1'; 
    else if (index >= 3) fill = '#e2e8f0';
    if (index === 11) fill = '#dcb14b'; // Current month gold
    return { name: d.name.toUpperCase(), uv: d.revenue, fill };
  }) : [
    { name: 'JAN', uv: 0, fill: '#f1f5f9' },
    { name: 'FEB', uv: 0, fill: '#f1f5f9' },
    { name: 'MAR', uv: 0, fill: '#f1f5f9' },
    { name: 'APR', uv: 0, fill: '#e2e8f0' },
    { name: 'MAY', uv: 0, fill: '#e2e8f0' },
    { name: 'JUN', uv: 0, fill: '#cbd5e1' },
    { name: 'JUL', uv: 0, fill: '#cbd5e1' },
    { name: 'AUG', uv: 0, fill: '#cbd5e1' },
    { name: 'SEP', uv: 0, fill: '#86efac' },
    { name: 'OCT', uv: 0, fill: '#4ade80' },
    { name: 'NOV', uv: 0, fill: '#86efac' },
    { name: 'DEC', uv: 0, fill: '#dcb14b' },
  ];

  const allTimeBarData = defaultBarData.map(d => ({ ...d, uv: d.uv * 1.8 }));
  const barData = timeframe === 'All Time' ? allTimeBarData : defaultBarData;

  // Custom Tooltip for Bar Chart
  const CustomTooltip = ({ active, payload, label }) => {
    if (active && payload && payload.length) {
      return (
        <div className="bg-[#1a1f36] text-white text-xs font-bold px-3 py-2 rounded-md shadow-lg">
          {label}: ${payload[0].value.toLocaleString()}
        </div>
      );
    }
    return null;
  };

  // Pie Chart Data (Plan Breakdown)
  const pieData = [
    { name: 'Premium', value: 52, color: '#0E1726' }, // Dark Navy
    { name: 'Pro', value: 34, color: '#D4AF37' },     // Gold
    { name: 'Basic', value: 14, color: '#F59E0B' },    // Orange/Amber
  ];

  const tableData = payments.map((p, index) => ({
    key: p._id || index,
    paymentId: p._id,
    supplier: { 
      initial: p.supplier?.companyName ? p.supplier.companyName.charAt(0).toUpperCase() : 'U', 
      name: p.supplier?.companyName || 'Unknown Supplier', 
      color: 'bg-[#0E1726] text-white' 
    },
    plan: p.supplier?.subscriptionPlan?.toUpperCase() || 'PREMIUM',
    amount: `$${p.amount.toFixed(2)}`,
    method: { type: 'Visa', last4: '****' },
    date: new Date(p.createdAt).toLocaleDateString(),
    status: p.status === 'paid' ? 'PAID' : 'FAILED',
  }));

  const columns = [
    {
      title: 'PAYMENT ID',
      dataIndex: 'paymentId',
      key: 'paymentId',
      render: (text) => <span className="font-mono text-gray-500 text-xs">{text}</span>
    },
    {
      title: 'SUPPLIER',
      dataIndex: 'supplier',
      key: 'supplier',
      render: (supplier) => (
        <div className="flex items-center gap-3">
          <div className={`w-6 h-6 rounded flex items-center justify-center text-[10px] font-bold ${supplier.color}`}>
            {supplier.initial}
          </div>
          <span className="font-bold text-gray-800 text-sm">{supplier.name}</span>
        </div>
      )
    },
    {
      title: 'PLAN',
      dataIndex: 'plan',
      key: 'plan',
      render: (plan) => {
        let bgColor = '';
        if (plan === 'PREMIUM') bgColor = 'bg-gray-200 text-gray-800 border-gray-300';
        else if (plan === 'PRO') bgColor = 'bg-yellow-100 text-yellow-700 border-yellow-200';
        else if (plan === 'BASIC') bgColor = 'bg-orange-100 text-orange-700 border-orange-200';
        return <span className={`px-2 py-0.5 text-[9px] font-black tracking-widest rounded uppercase border ${bgColor}`}>{plan}</span>;
      }
    },
    {
      title: 'AMOUNT',
      dataIndex: 'amount',
      key: 'amount',
      render: (text, record) => <span className={`font-black text-sm ${record.status === 'FAILED' ? 'text-red-600' : 'text-gray-900'}`}>{text}</span>
    },
    {
      title: 'METHOD',
      dataIndex: 'method',
      key: 'method',
      render: (method) => (
        <div className="flex items-center gap-2 text-gray-500 text-xs font-medium">
          <CreditCard size={14} className="text-gray-400" />
          <span>{method.type}{method.last4 ? ` -- ${method.last4}` : ''}</span>
        </div>
      )
    },
    {
      title: 'DATE',
      dataIndex: 'date',
      key: 'date',
      render: (text) => <span className="text-gray-500 text-xs font-medium">{text}</span>
    },
    {
      title: 'STATUS',
      dataIndex: 'status',
      key: 'status',
      render: (status) => (
        <span className={`px-3 py-1 rounded-full text-[10px] font-bold uppercase tracking-wider border ${status === 'PAID' ? 'bg-[#f4fbf7] text-[#2e8a5b] border-[#d3ecd9]' : 'bg-[#fef2f2] text-[#ef4444] border-[#fecaca]'}`}>
          {status}
        </span>
      )
    },
  ];

  const handleExport = () => {
    setIsExporting(true);
    setTimeout(() => {
      setIsExporting(false);
      message.success('Report exported successfully! Check your downloads.');
    }, 1200);
  };

  return (
    <div className="p-8 max-w-[1400px] mx-auto bg-[#FAFAFA] min-h-screen mt-16">
      
      {/* Header */}
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center mb-8 gap-4">
        <h1 className="text-3xl font-black text-[#1a1f36]">Revenue Reports</h1>
        <div className="flex flex-wrap items-center gap-3">
          <button 
            onClick={() => setTimeframe('Last 12 Months')}
            className={`px-4 py-2 rounded-md text-sm font-bold shadow-sm transition-colors ${timeframe === 'Last 12 Months' ? 'bg-[#dcb14b] text-gray-900' : 'bg-white text-gray-400 border border-gray-200'}`}
          >
            Last 12 Months
          </button>
          <button 
            onClick={() => setTimeframe('All Time')}
            className={`px-4 py-2 rounded-md text-sm font-bold shadow-sm transition-colors ${timeframe === 'All Time' ? 'bg-[#dcb14b] text-gray-900' : 'bg-white text-gray-400 border border-gray-200'}`}
          >
            All Time
          </button>
          <Select 
            defaultValue="All Plans" 
            style={{ width: 120 }}
            className="revenue-select"
            options={[
              { value: 'All Plans', label: 'All Plans' },
              { value: 'Premium', label: 'Premium' },
              { value: 'Pro', label: 'Pro' },
              { value: 'Basic', label: 'Basic' },
            ]}
          />
          <button 
            onClick={handleExport}
            disabled={isExporting}
            className={`flex items-center gap-2 px-5 py-2.5 rounded-md text-sm font-bold transition-colors shadow-sm ml-2 ${isExporting ? 'bg-gray-300 text-gray-500 cursor-not-allowed' : 'bg-[#dcb14b] text-gray-900 hover:bg-[#c9a040]'}`}
          >
            <Download size={16} className={isExporting ? 'animate-bounce' : ''} />
            {isExporting ? 'Exporting...' : 'Export Report'}
          </button>
        </div>
      </div>

      {/* Stat Cards */}
      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-5 gap-6 mb-8">
        {stats.map((stat, idx) => (
          <div key={idx} className="bg-white rounded-xl border border-gray-100 p-6 flex flex-col justify-between shadow-sm">
            <div className="flex justify-between items-start mb-4">
              <h3 className="text-[10px] font-bold text-gray-500 uppercase tracking-widest w-2/3 leading-tight">{stat.title}</h3>
              <div className="text-gray-400">{stat.icon}</div>
            </div>
            <div className="flex items-end gap-2">
              <span className="text-3xl font-black text-gray-900">{stat.value}</span>
              {stat.sub && <span className="text-[10px] text-gray-400 font-medium mb-1 leading-tight w-8">{stat.sub}</span>}
            </div>
          </div>
        ))}
        {/* Failed Card (Special Styling) */}
        <div className="bg-[#fffcfc] rounded-xl border border-red-100 p-6 flex flex-col justify-between shadow-sm">
          <div className="flex justify-between items-start mb-4">
            <h3 className="text-[10px] font-bold text-red-600 uppercase tracking-widest leading-tight">FAILED</h3>
            <div className="text-red-500 bg-red-50 p-1 rounded-full"><AlertCircle size={16} /></div>
          </div>
          <div className="flex items-end gap-2">
            <span className="text-3xl font-black text-red-600">{payments.filter(p => p.status === 'failed').length}</span>
            <span className="text-[10px] text-gray-500 font-medium mb-1 leading-tight w-16">Past 30 days</span>
          </div>
        </div>
      </div>

      {/* Charts Row */}
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6 mb-8">
        
        {/* Revenue by Month (Bar Chart) */}
        <div className="lg:col-span-2 bg-white rounded-xl border border-gray-200 p-6 shadow-sm flex flex-col">
          <div className="flex justify-between items-start mb-6">
            <div>
              <h2 className="text-lg font-black text-gray-900">Revenue by Month</h2>
              <p className="text-[11px] text-gray-500 font-medium">Fiscal trend analysis (Jul - Jun)</p>
            </div>
            <div className="flex items-center gap-2">
              <div className="w-2.5 h-2.5 rounded-full bg-[#dcb14b]"></div>
              <span className="text-[10px] font-bold text-gray-500 uppercase tracking-widest">REVENUE</span>
            </div>
          </div>
          
          <div className="flex-1 w-full h-[250px] min-h-[250px]">
            <ResponsiveContainer width="100%" height="100%">
              <BarChart data={barData} margin={{ top: 10, right: 10, left: 10, bottom: 0 }}>
                <Tooltip content={<CustomTooltip />} cursor={{fill: 'transparent'}} />
                <XAxis 
                  dataKey="name" 
                  axisLine={false} 
                  tickLine={false} 
                  tick={{ fontSize: 10, fill: '#64748b', fontWeight: 'bold' }} 
                  dy={10}
                />
                <Bar dataKey="uv" radius={[2, 2, 0, 0]}>
                  {barData.map((entry, index) => (
                    <Cell key={`cell-${index}`} fill={entry.fill} />
                  ))}
                </Bar>
              </BarChart>
            </ResponsiveContainer>
          </div>
        </div>

        {/* Plan Breakdown (Donut Chart) */}
        <div className="bg-white rounded-xl border border-gray-200 p-6 shadow-sm flex flex-col">
          <h2 className="text-lg font-black text-gray-900 mb-2">Plan Breakdown</h2>
          
          <div className="relative flex-1 w-full flex items-center justify-center min-h-[200px]">
            <ResponsiveContainer width="100%" height="100%">
              <PieChart>
                <Pie
                  data={pieData}
                  cx="50%"
                  cy="50%"
                  innerRadius={60}
                  outerRadius={85}
                  stroke="none"
                  paddingAngle={2}
                  dataKey="value"
                >
                  {pieData.map((entry, index) => (
                    <Cell key={`cell-${index}`} fill={entry.color} />
                  ))}
                </Pie>
                <Tooltip 
                  formatter={(value) => [`${value}%`, 'Plan Share']} 
                  contentStyle={{ borderRadius: '8px', border: 'none', boxShadow: '0 4px 6px -1px rgb(0 0 0 / 0.1)' }}
                />
              </PieChart>
            </ResponsiveContainer>
            
            {/* Center Label */}
            <div className="absolute inset-0 flex flex-col items-center justify-center pointer-events-none pb-2">
              <span className="text-xl font-black text-[#0E1726]">${formattedRevenue}</span>
              <span className="text-[8px] font-bold text-gray-400 uppercase tracking-widest">REVENUE</span>
            </div>
          </div>

          {/* Custom Legend */}
          <div className="mt-4 space-y-3">
            {pieData.map((item, idx) => (
              <div key={idx} className="flex justify-between items-center text-xs font-bold text-gray-700">
                <div className="flex items-center gap-2">
                  <div className="w-2 h-2 rounded-full" style={{ backgroundColor: item.color }}></div>
                  <span>{item.name}</span>
                </div>
                <span>{item.value}%</span>
              </div>
            ))}
          </div>
        </div>
      </div>

      {/* Recent Stripe Payments Table */}
      <div className="bg-white rounded-xl border border-gray-200 shadow-sm overflow-hidden">
        <div className="px-6 py-5 border-b border-gray-100 flex justify-between items-center">
          <h2 className="text-lg font-black text-gray-900">Recent Stripe Payments</h2>
          <button className="text-[10px] font-bold text-[#dcb14b] uppercase tracking-widest hover:text-[#c9a040] transition-colors flex items-center gap-1">
            VIEW ALL TRANSACTIONS <span>→</span>
          </button>
        </div>

        <div className="px-6 pb-6 pt-2">
          <Table 
            columns={columns} 
            dataSource={tableData} 
            loading={isPaymentsLoading}
            pagination={{
              pageSize: 5,
              showSizeChanger: true,
              pageSizeOptions: ['5', '10', '20'],
              className: 'mt-6'
            }}
            rowClassName="hover:bg-gray-50 cursor-pointer"
            className="revenue-table"
          />
        </div>
      </div>

      {/* Custom Styles */}
      <style jsx global>{`
        .revenue-select .ant-select-selector {
          padding: 8px 12px !important;
          border-radius: 6px !important;
          border-color: #e5e7eb !important;
          height: auto !important;
        }
        .revenue-select .ant-select-selection-item {
          font-size: 14px !important;
          font-weight: 600 !important;
          color: #4b5563 !important;
        }
        
        .revenue-table .ant-table-thead > tr > th {
          background-color: transparent;
          color: #9ca3af;
          font-weight: 800;
          font-size: 9px;
          letter-spacing: 0.1em;
          text-transform: uppercase;
          border-bottom: 1px solid #f3f4f6;
          padding: 16px 16px;
        }
        .revenue-table .ant-table-tbody > tr > td {
          padding: 16px 16px;
          border-bottom: 1px solid #f9fafb;
        }
        
        /* Fix recharts responsive container issue inside flex/grid */
        .recharts-responsive-container {
          min-height: 100px;
        }
      `}</style>
    </div>
  );
};

export default RevenueReports;

import React, { useState, useMemo } from "react";
import { Download, Plus } from "lucide-react";
import { toast } from "react-toastify";
import { useGetRfqsQuery, useCreateRfqMutation, useGetRfqStatsQuery } from "../../../redux/features/rfqs/rfqsApi";
import RfqMetrics from "../../../Components/admin-components/rfqs/RfqMetrics";
import RfqFilters from "../../../Components/admin-components/rfqs/RfqFilters";
import RfqTable from "../../../Components/admin-components/rfqs/RfqTable";
import ManualEntryModal from "../../../Components/admin-components/rfqs/ManualEntryModal";

export default function RfqManagement() {
  const { data: rfqsResponse, isLoading } = useGetRfqsQuery();
  const { data: statsResponse } = useGetRfqStatsQuery();
  const [createRfq] = useCreateRfqMutation();
  
  const rfqs = rfqsResponse?.data || [];
  const stats = statsResponse?.data || null;

  const rfqsList = useMemo(() => {
    return rfqs.map(rfq => ({
      id: rfq._id,
      displayId: `#RFQ-${rfq._id.substring(0, 8).toUpperCase()}`,
      buyer: { 
        name: rfq.buyerName || (rfq.buyerUser ? rfq.buyerUser.name : "Unknown Buyer"), 
        logo: (rfq.buyerName || rfq.buyerUser?.name || "UK").substring(0, 2).toUpperCase(), 
        color: "bg-blue-100 text-blue-700" 
      },
      supplier: rfq.supplier ? rfq.supplier.companyName : "Unknown Supplier",
      category: "GENERAL",
      status: rfq.status.charAt(0).toUpperCase() + rfq.status.slice(1), // e.g., 'pending' -> 'Pending'
      statusColor: rfq.status === "closed" ? "bg-gray-400" : (rfq.status === 'responded' ? "bg-green-500" : "bg-[#D4AF37]"),
      created: new Date(rfq.createdAt).toLocaleDateString('en-US', { month: 'short', day: '2-digit', year: 'numeric' }),
      dispute: rfq.status === 'disputed' ? "Yes" : "No"
    }));
  }, [rfqs]);

  const [isModalOpen, setIsModalOpen] = useState(false);
  const [modalMode, setModalMode] = useState("create");
  const [selectedRfq, setSelectedRfq] = useState(null);

  const [searchTerm, setSearchTerm] = useState("");
  const [statusFilter, setStatusFilter] = useState("All");
  const [categoryFilter, setCategoryFilter] = useState("All");
  const [disputeToggle, setDisputeToggle] = useState(false);
  const [currentPage, setCurrentPage] = useState(1);
  const itemsPerPage = 4;

  const handleClearFilters = () => {
    setSearchTerm("");
    setStatusFilter("All");
    setCategoryFilter("All");
    setDisputeToggle(false);
    setCurrentPage(1);
  };

  const handleCreateEntry = async (entryData) => {
    try {
      await createRfq({
        supplierId: entryData.supplierId, 
        buyerName: entryData.buyerName,
        buyerEmail: entryData.buyerEmail,
        subject: entryData.subject,
        details: entryData.details,
        quantity: entryData.quantity || 1
      }).unwrap();
      setIsModalOpen(false);
      toast.success("Manual RFQ entry created successfully!");
    } catch (err) {
      console.error(err);
      toast.error(err?.data?.message || err.message || "Failed to create manual entry");
    }
  };

  const handleOpenCreate = () => {
    setModalMode("create");
    setSelectedRfq(null);
    setIsModalOpen(true);
  };

  const handleOpenEdit = (rfq) => {
    setModalMode("edit");
    setSelectedRfq(rfq);
    setIsModalOpen(true);
  };

  const handleOpenView = (rfq) => {
    setModalMode("view");
    setSelectedRfq(rfq);
    setIsModalOpen(true);
  };

  const filteredRfqs = useMemo(() => {
    return rfqsList.filter(rfq => {
      const matchesSearch = 
        rfq.id.toLowerCase().includes(searchTerm.toLowerCase()) || 
        rfq.buyer.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
        rfq.supplier.toLowerCase().includes(searchTerm.toLowerCase());
      
      const matchesStatus = statusFilter === "All" || rfq.status === statusFilter;
      const matchesCategory = categoryFilter === "All" || rfq.category.toLowerCase() === categoryFilter.toLowerCase();
      const matchesDispute = !disputeToggle || rfq.dispute === "Yes";

      return matchesSearch && matchesStatus && matchesCategory && matchesDispute;
    });
  }, [rfqsList, searchTerm, statusFilter, categoryFilter, disputeToggle]);

  const totalPages = Math.ceil(filteredRfqs.length / itemsPerPage);
  const paginatedRfqs = filteredRfqs.slice((currentPage - 1) * itemsPerPage, currentPage * itemsPerPage);
  return (
    <div className="min-h-screen bg-[#F8F9FB] text-[#0F172A] font-sans pt-24 pb-32">
      
      {/* Header */}
      <div className="px-6 lg:px-8 max-w-[1400px] mx-auto mb-8">
        <div className="flex flex-col md:flex-row justify-between items-start md:items-end gap-4">
          <div>
            <h1 className="text-2xl font-bold text-[#0F172A] tracking-tight mb-1">
              RFQ Monitoring
            </h1>
            <p className="text-[14px] text-gray-500">
              Real-time procurement oversight & dispute management
            </p>
          </div>

          <div className="flex items-center gap-3 w-full md:w-auto">
            <button className="flex-1 md:flex-none flex items-center justify-center gap-2 px-4 py-2.5 bg-white border border-gray-200 rounded-md text-[13px] font-bold text-gray-700 hover:bg-gray-50 transition-colors shadow-sm">
              <Download size={14} />
              Export Matrix
            </button>
            <button 
              onClick={handleOpenCreate}
              className="flex-1 md:flex-none flex items-center justify-center gap-2 px-4 py-2.5 bg-[#D4AF37] border border-[#D4AF37] rounded-md text-[13px] font-bold text-[#0F172A] hover:bg-[#C2982B] transition-colors shadow-sm"
            >
              <Plus size={16} />
              Manual Entry
            </button>
          </div>
        </div>
      </div>

      {/* Main Content Area */}
      <div className="px-6 lg:px-8 max-w-[1400px] mx-auto">
        <RfqMetrics data={stats} />
        <RfqFilters 
          searchTerm={searchTerm} setSearchTerm={setSearchTerm}
          statusFilter={statusFilter} setStatusFilter={setStatusFilter}
          categoryFilter={categoryFilter} setCategoryFilter={setCategoryFilter}
          disputeToggle={disputeToggle} setDisputeToggle={setDisputeToggle}
          onClear={handleClearFilters}
        />
        <RfqTable 
          rfqs={paginatedRfqs}
          currentPage={currentPage}
          setCurrentPage={setCurrentPage}
          totalPages={totalPages}
          totalItems={filteredRfqs.length}
          itemsPerPage={itemsPerPage}
          onView={handleOpenView}
          onEdit={handleOpenEdit}
        />
      </div>

      <ManualEntryModal 
        isOpen={isModalOpen}
        onClose={() => {
          setIsModalOpen(false);
          setSelectedRfq(null);
        }}
        onSubmit={handleCreateEntry}
        mode={modalMode}
        initialData={selectedRfq}
      />

    </div>
  );
}

import React, { useState, useEffect } from "react";
import { useParams, useNavigate } from "react-router-dom";
import { useGetPlanQuery, useGetPlansQuery, useUpdatePlanMutation } from "../../../redux/features/subscriptions/subscriptionsApi";
import { toast } from 'react-toastify';
import EditPackageHeader from "../../../Components/admin-components/subscriptions/EditPackageHeader";
import PackageInfoForm from "../../../Components/admin-components/subscriptions/PackageInfoForm";
import PricingPeriodsForm from "../../../Components/admin-components/subscriptions/PricingPeriodsForm";
import FeatureAccessForm from "../../../Components/admin-components/subscriptions/FeatureAccessForm";
import CapacityLimitsForm from "../../../Components/admin-components/subscriptions/CapacityLimitsForm";
import BillingRulesForm from "../../../Components/admin-components/subscriptions/BillingRulesForm";
import UpsellAddonsForm from "../../../Components/admin-components/subscriptions/UpsellAddonsForm";
import PublicMarketingForm from "../../../Components/admin-components/subscriptions/PublicMarketingForm";
import PackageHistoryTable from "../../../Components/admin-components/subscriptions/PackageHistoryTable";
import LivePreviewCard from "../../../Components/admin-components/subscriptions/LivePreviewCard";

export default function EditSubscription() {
  const { id } = useParams();
  const navigate = useNavigate();
  const [activeTab, setActiveTab] = useState("Overview");
  
  const { data: planResponse, isLoading } = useGetPlanQuery(id, { skip: !id });
  const { data: plansResponse } = useGetPlansQuery();
  const [updatePlan] = useUpdatePlanMutation();
  
  const [formData, setFormData] = useState({
    internalName: "",
    name: "",
    slug: "",
    status: "Published",
    description: "",
    badge: "",
    accentColor: "#D4AF37",
    publicVisibility: true,
    basePrice: "",
    billingCycle: "",
    taxCategory: "",
    features: [1, 2, 3, 4] // feature IDs that are checked
  });

  useEffect(() => {
    if (planResponse?.data) {
      const plan = planResponse.data;
      setFormData({
        internalName: plan.internalName || "",
        name: plan.name || "",
        slug: plan.slug || "",
        status: plan.isActive ? "Published" : "Draft",
        description: plan.description || "",
        badge: plan.badgeText || "",
        accentColor: plan.accentColor || "#D4AF37",
        publicVisibility: plan.isActive,
        basePrice: plan.price || "",
        billingCycle: plan.billingCycle || "",
        taxCategory: plan.taxCategory || "",
        features: plan.features || [1, 2, 3, 4] 
      });
    }
  }, [planResponse]);

  const handleChange = (name, value) => {
    setFormData(prev => ({ ...prev, [name]: value }));
  };

  const handleSave = async () => {
    if (!formData.internalName || !formData.name || !formData.basePrice) {
      toast.warning("Please fill in required fields (Internal Name, Display Name, Base Price)");
      return;
    }

    const finalSlug = formData.slug.trim() || formData.name.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/(^-|-$)+/g, '');

    if (!finalSlug) {
      toast.warning("Unable to generate slug. Please provide a valid Display Name or Slug.");
      return;
    }

    const existingPlans = plansResponse?.data || [];
    const isDuplicateName = existingPlans.some(
      plan => 
        plan._id !== id && (
          (plan.name && formData.name && plan.name.toLowerCase() === formData.name.toLowerCase()) || 
          (plan.internalName && formData.internalName && plan.internalName.toLowerCase() === formData.internalName.toLowerCase())
        )
    );

    if (isDuplicateName) {
      toast.error("A package with this internal name or display name already exists.");
      return;
    }

    const payload = {
      internalName: formData.internalName,
      name: formData.name,
      slug: finalSlug,
      price: Number(formData.basePrice),
      isActive: formData.status === "Published" ? true : false,
      features: formData.features
    };

    if (formData.description !== undefined) payload.description = formData.description;
    if (formData.badge !== undefined) payload.badgeText = formData.badge;
    if (formData.accentColor !== undefined) payload.accentColor = formData.accentColor;
    if (formData.billingCycle !== undefined) payload.billingCycle = formData.billingCycle;
    if (formData.taxCategory !== undefined) payload.taxCategory = formData.taxCategory;

    try {
      await updatePlan({ id, planData: payload }).unwrap();
      toast.success("Package updated successfully!");
      navigate('/subscriptions');
    } catch (error) {
      console.error("Failed to update package", error);
      toast.error(error?.data?.message || "Failed to update package. Please try again.");
    }
  };

  // Smooth scroll logic when a tab is clicked
  useEffect(() => {
    if (activeTab) {
      const element = document.getElementById(activeTab);
      if (element) {
        element.scrollIntoView({ behavior: "smooth", block: "start" });
      }
    }
  }, [activeTab]);

  return (
    <div className="min-h-screen bg-[#F8F9FB] text-[#0F172A] font-sans pb-32">
      
      {/* Sticky Header with Tabs */}
      <EditPackageHeader activeTab={activeTab} setActiveTab={setActiveTab} handleSave={handleSave} />

      {/* Main Content Area */}
      <div className="px-6 lg:px-8 max-w-[1200px] mx-auto">
        <div className="flex flex-col gap-6">
          
          {/* Row 1: Info (Left 2/3) & Live Preview (Right 1/3) */}
          <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
            <div className="lg:col-span-2">
              <PackageInfoForm data={formData} onChange={handleChange} />
            </div>
            <div className="lg:col-span-1">
              <LivePreviewCard data={formData} />
            </div>
          </div>

          {/* Row 2: Pricing Periods */}
          <div>
            <PricingPeriodsForm data={formData} onChange={handleChange} />
          </div>

          {/* Row 3: Feature Access & Capacity Limits */}
          <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
            <FeatureAccessForm data={formData} onChange={handleChange} />
            <CapacityLimitsForm />
          </div>

          {/* Row 4: Billing Rules & Upsell Addons */}
          <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
            <BillingRulesForm />
            <UpsellAddonsForm />
          </div>

          {/* Row 5: Public Marketing */}
          <div>
            <PublicMarketingForm data={formData} onChange={handleChange} />
          </div>

          {/* Row 6: History Table */}
          <div>
            <PackageHistoryTable />
          </div>

        </div>
      </div>
    </div>
  );
}

import React, { useState, useMemo } from "react";
import { useNavigate } from "react-router-dom";
import { Download, Plus, ChevronDown, Search, Filter } from "lucide-react";
import { 
  useGetListingsQuery, 
  useUpdateListingMutation 
} from "../../../redux/features/listings/listingsApi";
import { useUpdateUserMutation, useDeleteUserMutation } from "../../../redux/features/users/usersApi";
import SupplierTable from "../../../Components/admin-components/supplier/SupplierTable";
import SupplierFormModal from "../../../Components/admin-components/supplier/SupplierFormModal";
import SupplierDetailsModal from "../../../Components/admin-components/supplier/SupplierDetailsModal";
import { Pagination } from "../../../Components/admin-components/buyer/BuyerTable"; // Reuse pagination

export default function SupplierManagement() {
  const navigate = useNavigate();
  const { data: listingsResponse, isLoading, error } = useGetListingsQuery(undefined, { refetchOnMountOrArgChange: true });
  const suppliersData = listingsResponse?.data || [];
  const [updateListing] = useUpdateListingMutation();
  const [updateUser] = useUpdateUserMutation();
  const [deleteUser] = useDeleteUserMutation();

  // Filter only suppliers
  const suppliers = useMemo(() => {
    return suppliersData.map(sup => ({
      id: sup._id,
      icon: "Box", 
      name: sup.user?.name || sup.contactEmail || "Unknown",
      company: sup.companyName || "No Company Name",
      email: sup.contactEmail || sup.user?.email || "No Email",
      plan: sup.subscriptionPlan ? `${sup.subscriptionPlan.charAt(0).toUpperCase()}${sup.subscriptionPlan.slice(1)}` : "Free",
      verification: sup.isApproved ? "Verified" : (sup.listingStatus === 'Suspended' ? "Suspended" : "Pending"),
      listingStatus: sup.listingStatus || "Pending",
      subscription: sup.subscriptionStatus ? `${sup.subscriptionStatus.charAt(0).toUpperCase()}${sup.subscriptionStatus.slice(1)}` : "Inactive"
    }));
  }, [suppliersData]);

  const [currentPage, setCurrentPage] = useState(1);
  const [selectedIds, setSelectedIds] = useState([]);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingSupplier, setEditingSupplier] = useState(null);
  const [isViewModalOpen, setIsViewModalOpen] = useState(false);
  const [viewingSupplier, setViewingSupplier] = useState(null);
  const [searchQuery, setSearchQuery] = useState("");
  const [planFilter, setPlanFilter] = useState("All");
  const [verificationFilter, setVerificationFilter] = useState("All");
  const [statusFilter, setStatusFilter] = useState("All");
  const [bulkAction, setBulkAction] = useState("");
  const pageSize = 4; // Design shows 4 items per page

  const handleSaveSupplier = async (savedSupplier) => {
    try {
      if (editingSupplier) {
        const originalSup = suppliersData.find(s => s._id === savedSupplier.id);
        const userId = originalSup?.user?._id || originalSup?.user;

        let isApproved = savedSupplier.verification === 'Verified';
        let listingStatus = savedSupplier.listingStatus;
        if (listingStatus.includes("Approved")) listingStatus = "Approved";
        if (listingStatus.includes("Pending")) listingStatus = "Pending";
        if (listingStatus.includes("Hidden")) listingStatus = "Hidden";

        // Update listing
        await updateListing({ 
          id: savedSupplier.id, 
          data: { 
            companyName: savedSupplier.company,
            contactEmail: savedSupplier.email,
            isApproved,
            listingStatus
          } 
        }).unwrap();

        // Update user account (status & verification)
        if (userId) {
          let userStatus = "Active";
          if (savedSupplier.verification === "Suspended") userStatus = "Suspended";
          
          let isVerified = savedSupplier.verification === "Verified";

          await updateUser({
            id: userId,
            userData: {
              status: userStatus,
              isVerified,
              name: savedSupplier.name
            }
          }).unwrap();
        }
      }
      setEditingSupplier(null);
      setIsModalOpen(false);
    } catch (err) {
      console.error(err);
      alert("Error saving supplier");
    }
  };

  const handleDeleteSupplier = async (id) => {
    if (window.confirm("Are you sure you want to delete this supplier listing?")) {
      try {
        const originalSup = suppliersData.find(s => s._id === id);
        const userId = originalSup?.user?._id || originalSup?.user;
        if (userId) {
           await deleteUser(userId).unwrap();
        } else {
           alert("No user account associated with this listing");
        }
      } catch (err) {
        console.error(err);
        alert("Error deleting supplier");
      }
    }
  };

  const handleApproveSupplier = async (supplier) => {
    try {
      await updateListing({ id: supplier.id, data: { isApproved: true, listingStatus: 'Approved' } }).unwrap();
    } catch (err) {
      console.error(err);
      alert("Error approving supplier");
    }
  };

  const openAddModal = () => {
    navigate("/sign-up?mode=admin_assisted");
  };

  const openEditModal = (supplier) => {
    setEditingSupplier(supplier);
    setIsModalOpen(true);
  };

  const openViewModal = (supplier) => {
    setViewingSupplier(supplier);
    setIsViewModalOpen(true);
  };

  const handlePrint = () => {
    window.print();
  };

  const filteredSuppliers = useMemo(() => {
    return suppliers.filter(supplier => {
      const matchSearch = supplier.name.toLowerCase().includes(searchQuery.toLowerCase()) || 
                          supplier.email.toLowerCase().includes(searchQuery.toLowerCase()) ||
                          supplier.company.toLowerCase().includes(searchQuery.toLowerCase());
      const matchPlan = planFilter === "All" || supplier.plan === planFilter;
      const matchVerification = verificationFilter === "All" || supplier.verification === verificationFilter;
      const matchStatus = statusFilter === "All" || supplier.subscription === statusFilter;
      
      return matchSearch && matchPlan && matchVerification && matchStatus;
    });
  }, [suppliers, searchQuery, planFilter, verificationFilter, statusFilter]);

  const paginatedSuppliers = useMemo(() => {
    const start = (currentPage - 1) * pageSize;
    return filteredSuppliers.slice(start, start + pageSize);
  }, [currentPage, filteredSuppliers]);

  const handleSelect = (id) => {
    setSelectedIds((prev) =>
      prev.includes(id) ? prev.filter((i) => i !== id) : [...prev, id]
    );
  };

  const handleSelectAll = (e) => {
    if (e.target.checked) {
      setSelectedIds(paginatedSuppliers.map(s => s.id));
    } else {
      setSelectedIds([]);
    }
  };

  const handleApplyBulkAction = async () => {
    if (!bulkAction || selectedIds.length === 0) return;
    
    try {
      if (bulkAction === "verify") {
        await Promise.all(selectedIds.map(id => 
          updateListing({ id, data: { isApproved: true, listingStatus: 'Approved' } }).unwrap()
        ));
      } else if (bulkAction === "suspend") {
        await Promise.all(selectedIds.map(id => 
          updateListing({ id, data: { listingStatus: 'Suspended' } }).unwrap()
        ));
      } else if (bulkAction === "delete") {
        alert("Bulk delete is not implemented in listingsApi yet.");
      }
      setSelectedIds([]);
      setBulkAction("");
    } catch (err) {
      console.error(err);
      alert("Error applying bulk action");
    }
  };

  const hasSelection = selectedIds.length > 0;

  return (
    <div className="min-h-screen p-6 mt-16 lg:p-8 bg-[#F8F9FB] text-[#0F172A] font-sans pt-24">

      {/* Header Section */}
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center mb-8 gap-4">
        <div>
          <h1 className="text-3xl font-extrabold text-[#0F172A] mb-2 tracking-tight">
            Supplier Management
          </h1>
          <p className="text-[14px] text-gray-500 font-medium">
            Manage supplier accounts, verify businesses, and monitor listing compliance.
          </p>
        </div>

        <div className="flex items-center gap-3">
          <button 
            onClick={handlePrint}
            className="flex items-center gap-2 px-4 py-2 bg-white border border-gray-200 rounded-md text-[13px] font-bold text-[#0F172A] hover:bg-gray-50 transition-colors shadow-sm print:hidden"
          >
            <Download size={16} />
            Export Suppliers
          </button>
          <button 
            onClick={openAddModal}
            className="flex items-center gap-2 px-4 py-2 bg-[#D4AF37] border border-[#D4AF37] rounded-md text-[13px] font-bold text-[#0F172A] hover:bg-[#C2982B] transition-colors shadow-sm"
          >
            <Plus size={16} strokeWidth={3} />
            Add Supplier
          </button>
        </div>
      </div>

      {/* Main Content Area */}
      <div className="bg-white border border-gray-200 rounded-xl shadow-sm mb-8">

        {/* Filters and Bulk Actions Bar */}
        <div className="flex flex-col xl:flex-row justify-between items-start xl:items-center p-4 border-b border-gray-100 gap-4">

          <div className="flex flex-wrap items-center gap-3">
            {/* Search */}
            <div className="relative">
              <Search className="absolute left-3 top-2.5 text-gray-400" size={16} />
              <input 
                type="text" 
                placeholder="Search suppliers, emails..." 
                value={searchQuery}
                onChange={(e) => {
                  setSearchQuery(e.target.value);
                  setCurrentPage(1);
                }}
                className="pl-9 pr-4 py-2 bg-[#F8F9FB] border border-gray-200 rounded-md text-[13px] font-medium text-[#0F172A] min-w-[240px] focus:outline-none focus:ring-2 focus:ring-[#D4AF37]/50 focus:border-[#D4AF37] transition-all"
              />
            </div>
            
            <div className="h-6 w-px bg-gray-200 hidden md:block"></div>

            {/* Plan Filter */}
            <div className="relative">
              <select 
                value={planFilter}
                onChange={(e) => {
                  setPlanFilter(e.target.value);
                  setCurrentPage(1);
                }}
                className="appearance-none flex items-center justify-between gap-2 pl-3 pr-8 py-2 bg-[#F1F5F9] rounded-md text-[12px] font-bold text-[#475569] min-w-[110px] hover:bg-[#E2E8F0] transition-colors outline-none cursor-pointer border border-gray-200"
              >
                <option value="All">Plan: All</option>
                <option value="Premium">Premium</option>
                <option value="Pro">Pro</option>
                <option value="Basic">Basic</option>
              </select>
              <ChevronDown size={14} className="absolute right-3 top-2.5 text-[#475569] pointer-events-none" />
            </div>

            {/* Verification Filter */}
            <div className="relative">
              <select 
                value={verificationFilter}
                onChange={(e) => {
                  setVerificationFilter(e.target.value);
                  setCurrentPage(1);
                }}
                className="appearance-none flex items-center justify-between gap-2 pl-3 pr-8 py-2 bg-[#F1F5F9] rounded-md text-[12px] font-bold text-[#475569] min-w-[130px] hover:bg-[#E2E8F0] transition-colors outline-none cursor-pointer border border-gray-200"
              >
                <option value="All">Verification: All</option>
                <option value="Verified">Verified</option>
                <option value="Pending">Pending</option>
                <option value="Suspended">Suspended</option>
              </select>
              <ChevronDown size={14} className="absolute right-3 top-2.5 text-[#475569] pointer-events-none" />
            </div>
            
            {/* Status Filter */}
            <div className="relative">
              <select 
                value={statusFilter}
                onChange={(e) => {
                  setStatusFilter(e.target.value);
                  setCurrentPage(1);
                }}
                className="appearance-none flex items-center justify-between gap-2 pl-3 pr-8 py-2 bg-[#F1F5F9] rounded-md text-[12px] font-bold text-[#475569] min-w-[110px] hover:bg-[#E2E8F0] transition-colors outline-none cursor-pointer border border-gray-200"
              >
                <option value="All">Status: All</option>
                <option value="Active">Active</option>
                <option value="Paused">Paused</option>
                <option value="Past Due">Past Due</option>
              </select>
              <ChevronDown size={14} className="absolute right-3 top-2.5 text-[#475569] pointer-events-none" />
            </div>
            
            <button className="p-2 border border-gray-200 rounded-md text-gray-400 hover:text-gray-600 hover:bg-gray-50">
              <Filter size={16} />
            </button>
          </div>

          <div className="flex items-center gap-3 w-full xl:w-auto">
            <span className="text-[12px] font-bold text-gray-500 mr-1">Bulk Actions:</span>
            
            <div className="relative">
              <select 
                value={bulkAction}
                onChange={(e) => setBulkAction(e.target.value)}
                disabled={!hasSelection || isLoading}
                className="appearance-none flex items-center justify-between gap-2 pl-3 pr-8 py-2 bg-white rounded-md text-[12px] font-bold text-gray-700 min-w-[160px] border border-gray-200 disabled:opacity-50 disabled:cursor-not-allowed outline-none cursor-pointer"
              >
                <option value="" disabled>Select Action...</option>
                <option value="verify">Verify Selected</option>
                <option value="suspend">Suspend Selected</option>
                <option value="delete">Delete Selected</option>
              </select>
              <ChevronDown size={14} className="absolute right-3 top-2.5 text-gray-400 pointer-events-none" />
            </div>

            <button
              onClick={handleApplyBulkAction}
              disabled={!hasSelection || !bulkAction || isLoading}
              className="px-4 py-2 border border-gray-200 rounded-md text-[12px] font-bold text-gray-600 bg-gray-50 hover:bg-gray-100 disabled:opacity-50 disabled:cursor-not-allowed transition-colors shadow-sm"
            >
              Apply
            </button>
          </div>

        </div>

        {/* Table Area */}
        {error && (
          <div className="p-8 text-center text-red-500 font-bold border border-red-200 bg-red-50 rounded-md m-4">
            <h3>Error loading suppliers</h3>
            <pre className="text-left mt-4 text-xs overflow-auto">
              {JSON.stringify(error, null, 2)}
            </pre>
          </div>
        )}
        
        {isLoading ? (
          <div className="p-8 text-center text-gray-500">Loading suppliers...</div>
        ) : !error && (
          <SupplierTable 
            suppliers={paginatedSuppliers}
            selectedIds={selectedIds}
            onSelect={handleSelect}
            onSelectAll={handleSelectAll}
            onEdit={openEditModal}
            onDelete={handleDeleteSupplier}
            onApprove={handleApproveSupplier}
            onView={openViewModal}
          />
        )}

        {/* Pagination Area */}
        {!isLoading && !error && (
          <Pagination 
            currentPage={currentPage}
            totalItems={filteredSuppliers.length}
            pageSize={pageSize}
            onPageChange={setCurrentPage}
          />
        )}

      </div>

      <SupplierFormModal 
        isOpen={isModalOpen} 
        onClose={() => setIsModalOpen(false)}
        onSave={handleSaveSupplier}
        supplier={editingSupplier}
      />

      <SupplierDetailsModal
        isOpen={isViewModalOpen}
        onClose={() => setIsViewModalOpen(false)}
        supplier={viewingSupplier}
      />
    </div>
  );
}

import { createRequire } from 'module';

const require = createRequire(import.meta.url);

/** @type {import('tailwindcss').Config} */
export default {
  content: [
    "./index.html",
    "./src/**/*.{js,ts,jsx,tsx}",
  ],
  theme: {
    extend: {},
